// Bai tap ngu phap hsk4v3 — soan rieng theo trinh do (sinh tu data-grammar/hsk4v3/).
window.GRAMMAR_EXTRA = Object.assign(window.GRAMMAR_EXTRA || {}, {"/lessons/hsk4v3-bai-1.html":[{"point":"指示代词“任何” — bất kỳ, bất cứ","items":[{"context":"“Sau này có bất kỳ vấn đề gì đều có thể đến tìm cô.”","pre":"你们以后有","blank":"任何","post":"问题都可以来找我。","options":["任何","每","所有的"],"answer":0,"explanation":"任何 + danh từ + 都 + V."},{"context":"“Bất kỳ ai cũng không được đến muộn.”","pre":"明天8点出发，任何人","blank":"也","post":"不能迟到。","options":["也","就","才"],"answer":0,"explanation":"任何……也 + phủ định."},{"context":"“Có bất kỳ thông báo nào, tôi đều báo cho bạn ngay.”","pre":"学校有任何通知，我","blank":"都","post":"会第一时间告诉你。","options":["都","还","再"],"answer":0,"explanation":"任何……都…… — 都 đứng trước động từ của vế sau."},{"context":"“Việc này anh ấy không nói với bất kỳ ai.”","pre":"这件事他没有告诉","blank":"任何","post":"人。","options":["任何","什么的","哪"],"answer":0,"explanation":"没有 + V + 任何 + N."},{"context":"“Bất cứ lúc nào em cũng có thể gọi cho cô.”","pre":"","blank":"任何","post":"时候你都可以给我打电话。","options":["任何","那","一"],"answer":0,"explanation":"任何时候 = bất cứ lúc nào."},{"type":"sort","context":"Sắp xếp: “Em có bất kỳ vấn đề gì đều có thể hỏi tôi.”","words":["你","有","任何","问题","都","可以","问我"],"answer":"你有任何问题都可以问我。","explanation":"任何 + N + 都 + 可以 + V."},{"type":"sort","context":"Sắp xếp: “Bất kỳ ai cũng không được đến muộn.”","words":["任何人","也","不能","迟到"],"answer":"任何人也不能迟到。","explanation":"任何人 + 也 + 不能."},{"type":"sort","context":"Sắp xếp: “Việc này anh ấy không nói với ai cả.”","words":["他","没有","告诉","任何人","这件事"],"answer":"这件事他没有告诉任何人。","explanation":"Phủ định: 没有 + V + 任何 + N."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"任何的学生都可以参加。","isCorrect":false,"correctVersion":"任何学生都可以参加。","explanation":"任何 + N, không thêm 的."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们有任何问题都可以找王老师。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 任何问题 + 都 + 可以."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他不认识任何人们。","isCorrect":false,"correctVersion":"他不认识任何人。","explanation":"任何 không đi với 们."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bất cứ lúc nào em cũng có thể gọi điện cho cô.","answer":"任何时候你都可以给我打电话。","answerPy":"Rènhé shíhou nǐ dōu kěyǐ gěi wǒ dǎdiànhuà.","explanation":"任何时候 + 都 + 可以."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Trong thư viện, bất kỳ ai cũng không được nói to.","answer":"在图书馆里，任何人都不能大声说话。","answerPy":"Zài túshūguǎn lǐ, rènhé rén dōu bù néng dàshēng shuōhuà.","explanation":"任何人 + 都 / 也 + 不能."}]},{"point":"假设复句“要是……，就……” — nếu … thì …","items":[{"context":"“Nếu xin được học bổng thì …”","pre":"","blank":"要是","post":"申请到奖学金，就能减轻不少经济压力。","options":["要是","虽然","因为"],"answer":0,"explanation":"要是 nêu giả thiết."},{"context":"“… thì đi leo núi với tớ nhé.”","pre":"你要是明天有时间，","blank":"就","post":"跟我一起去爬山吧。","options":["就","才","也"],"answer":0,"explanation":"要是……，就……"},{"context":"“… thì chúng ta hỏi người khác.”","pre":"要是她不愿意参加比赛，我们","blank":"就","post":"再问问别人。","options":["就","还","都"],"answer":0,"explanation":"就 đứng sau chủ ngữ 我们."},{"context":"“Nếu bạn đói thì mình đi nhà ăn trước.” (ôn từ mới)","pre":"要是你饿了，我们就先去","blank":"食堂","post":"吧。","options":["食堂","签证","证件"],"answer":0,"explanation":"食堂 = nhà ăn."},{"context":"“Nếu không làm visa thì không thể sang Trung Quốc du học.”","pre":"","blank":"要是","post":"不办签证，就不能来中国留学。","options":["要是","一方面","随着"],"answer":0,"explanation":"要是 + phủ định 不……，就不能……"},{"type":"sort","context":"Sắp xếp: “Nếu mai mưa thì chúng ta không đi nữa.”","words":["要是","明天","下雨","，","我们","就","不去了"],"answer":"要是明天下雨，我们就不去了。","explanation":"要是 + giả thiết，chủ ngữ + 就 + V."},{"type":"sort","context":"Sắp xếp: “Nếu bạn mệt rồi thì nghỉ một chút đi.”","words":["你","要是","累了","，","就","休息","一下吧"],"answer":"你要是累了，就休息一下吧。","explanation":"要是 đứng sau chủ ngữ 你."},{"type":"sort","context":"Sắp xếp: “Nếu có vấn đề thì đến tìm tôi.”","words":["要是","有","问题","，","就","来","找我"],"answer":"要是有问题，就来找我。","explanation":"要是……，就……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"要是你不舒服，就去看医生吧。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 要是……，就……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"要是明天有时间，我们去就看电影。","isCorrect":false,"correctVersion":"要是明天有时间，我们就去看电影。","explanation":"就 đứng trước động từ 去."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"要是我有钱，我就买一辆新车。","isCorrect":true,"correctVersion":"","explanation":"Đúng: chủ ngữ 我 + 就 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nếu xin được học bổng thì tôi sẽ học thạc sĩ ở Trung Quốc.","answer":"要是申请到奖学金，我就在中国读硕士。","answerPy":"Yàoshi shēnqǐng dào jiǎngxuéjīn, wǒ jiù zài Zhōngguó dú shuòshì.","explanation":"要是……，就…… + từ mới 申请, 奖学金, 硕士."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nếu bạn không hiểu thì hỏi cô giáo đi.","answer":"要是你不懂，就问老师吧。","answerPy":"Yàoshi nǐ bù dǒng, jiù wèn lǎoshī ba.","explanation":"要是……，就……吧."}]},{"point":"介词“随着” — cùng với, theo (sự thay đổi)","items":[{"context":"“Cùng với sự phát triển của Trung Quốc …”","pre":"","blank":"随着","post":"中国的发展，越来越多的外国学生来中国学习。","options":["随着","通过","除了"],"answer":0,"explanation":"随着 + N 的发展."},{"context":"“Cùng với trình độ tiếng Trung nâng cao …”","pre":"随着中文水平的","blank":"提高","post":"，我现在能看懂中文报纸了。","options":["提高","知识","方面"],"answer":0,"explanation":"随着……的提高."},{"context":"“Theo trời ngày càng nóng …”","pre":"随着天气","blank":"越来越","post":"热，人们都换上了凉快的衣服。","options":["越来越","一方面","任何"],"answer":0,"explanation":"随着 + 越来越 + tính từ."},{"context":"“Thông qua những giao lưu này …” (phân biệt với 随着)","pre":"","blank":"通过","post":"这些交流，外国学生能更快地适应中国的大学生活。","options":["通过","随着","要是"],"answer":0,"explanation":"通过 = nhờ/qua cách gì; 随着 = theo sự thay đổi."},{"context":"“… giao lưu cũng ngày càng nhiều.”","pre":"随着来中国留学的人越来越多，中国学生和外国学生的交流","blank":"也","post":"越来越多。","options":["也","就","才"],"answer":0,"explanation":"Vế sau thường có 也 + 越来越."},{"type":"sort","context":"Sắp xếp: “Cùng với kinh tế phát triển, đời sống mọi người ngày càng tốt.”","words":["随着","经济","的","发展","，","人们的生活","越来越好"],"answer":"随着经济的发展，人们的生活越来越好。","explanation":"随着 + N 的 + 发展，……越来越……"},{"type":"sort","context":"Sắp xếp: “Cùng với tuổi tác tăng lên, cậu ấy ngày càng hiểu chuyện.”","words":["随着","年龄","的","增长","，","他","越来越","懂事了"],"answer":"随着年龄的增长，他越来越懂事了。","explanation":"随着……的增长."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"随着我到了北京，就给你打电话。","isCorrect":false,"correctVersion":"我到了北京以后，就给你打电话。","explanation":"“Đến Bắc Kinh” là hành động, không phải sự thay đổi dần → dùng ……以后."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"随着生活水平的提高，人们越来越关注身体健康。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 随着……的提高，……越来越……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"人们都换上了凉快的衣服，随着天气越来越热。","isCorrect":false,"correctVersion":"随着天气越来越热，人们都换上了凉快的衣服。","explanation":"Cụm 随着 đặt ở đầu câu."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cùng với sự phát triển kinh tế, ngày càng nhiều người đi du lịch nước ngoài.","answer":"随着经济的发展，越来越多的人去国外旅游。","answerPy":"Suízhe jīngjì de fāzhǎn, yuèláiyuè duō de rén qù guówài lǚyóu.","explanation":"随着……的发展，越来越多的……"}]},{"point":"并列复句“一方面……，另一方面……” — một mặt …, mặt khác …","items":[{"context":"“… mặt khác vì tiện.”","pre":"他经常在网上买东西，一方面因为便宜，","blank":"另一方面","post":"因为方便。","options":["另一方面","一方面","另外"],"answer":0,"explanation":"一方面……，另一方面……"},{"context":"“… mặt khác cũng giảm được áp lực.”","pre":"多做运动一方面能让身体更健康，另一方面","blank":"也","post":"能减轻压力。","options":["也","就","才"],"answer":0,"explanation":"Vế 另一方面 thường có 也."},{"context":"“Một mặt là để học ngôn ngữ …”","pre":"来中国留学，","blank":"一方面","post":"是为了学习语言，另一方面也是为将来做准备。","options":["一方面","随着","要是"],"answer":0,"explanation":"Vế đầu dùng 一方面."},{"context":"“… kiến thức về thương mại quốc tế.” (ôn từ 方面)","pre":"我想了解更多国际贸易","blank":"方面","post":"的知识。","options":["方面","知识","专业"],"answer":0,"explanation":"N + 方面的知识."},{"type":"sort","context":"Sắp xếp: “Tôi đạp xe đi làm, một mặt tốt cho môi trường, mặt khác cũng tốt cho sức khỏe.”","words":["我","骑车上班","，","一方面","对环境好","，","另一方面","对身体也好"],"answer":"我骑车上班，一方面对环境好，另一方面对身体也好。","explanation":"一方面……，另一方面……也……"},{"type":"sort","context":"Sắp xếp: “Học tiếng Trung một mặt vì công việc, mặt khác để hiểu văn hóa Trung Quốc.”","words":["学中文","一方面","为了","工作","，","另一方面","为了","了解中国文化"],"answer":"学中文一方面为了工作，另一方面为了了解中国文化。","explanation":"Hai vế cân đối: 为了……，为了……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他一方面是学生，另外方面是老师。","isCorrect":false,"correctVersion":"他一方面是学生，另一方面也是老师。","explanation":"Phải là 另一方面."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我住在学校里，一方面因为便宜，另一方面因为方便。","isCorrect":true,"correctVersion":"","explanation":"Đúng: nêu hai lý do song song."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"一方面天气很好，一方面我们去公园吧。","isCorrect":false,"correctVersion":"天气很好，我们去公园吧。","explanation":"Hai vế không phải hai mặt song song của một sự việc → không dùng cấu trúc này."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi chọn ngành kinh tế, một mặt vì có hứng thú, mặt khác vì sau này muốn làm thương mại quốc tế.","answer":"我选择经济专业，一方面是因为感兴趣，另一方面是因为将来想做国际贸易。","answerPy":"Wǒ xuǎnzé jīngjì zhuānyè, yìfāngmiàn shì yīnwèi gǎnxìngqù, lìngyìfāngmiàn shì yīnwèi jiānglái xiǎng zuò guójì màoyì.","explanation":"一方面……，另一方面…… + từ mới 专业, 将来, 国际贸易."}]}],"/lessons/hsk4v3-bai-10.html":[{"point":"固定格式“说什么/怎么（着）也得×” — dù thế nào cũng phải …","items":[{"context":"“… dù thế nào cũng phải mặc áo dày một chút.”","pre":"更重要的是，说什么","blank":"也得","post":"穿上厚一点儿的衣服。","options":["也得","就得","才得"],"answer":0,"explanation":"Cấu trúc cố định: 说什么 + 也得 + V."},{"context":"“Ngày mai dù thế nào tôi cũng phải làm xong bài tập.”","pre":"假期还有两天就结束了，我明天","blank":"说什么","post":"也得把作业做完。","options":["说什么","为什么","什么时候"],"answer":0,"explanation":"说什么也得 = dù thế nào cũng phải."},{"context":"“Lần này dù thế nào cũng phải đi.”","pre":"我很后悔上次没参加这个活动，这次怎么","blank":"着","post":"也得去。","options":["着","了","过"],"answer":0,"explanation":"怎么着也得 (着 = zhe)."},{"context":"“… nếu không sẽ rét cóng đấy.” (ôn 否则 – Bài 8)","pre":"这么低的温度，你说什么也得多穿点儿，","blank":"否则","post":"会冻坏的。","options":["否则","所以","而且"],"answer":0,"explanation":"……，否则…… = nếu không thì …"},{"context":"“… phải mặc quần áo dày một chút.”","pre":"冬天去哈尔滨，说什么也得穿上","blank":"厚","post":"一点儿的衣服。","options":["厚","低","暖和"],"answer":0,"explanation":"厚一点儿的衣服 = áo dày hơn một chút."},{"type":"sort","context":"Sắp xếp: “Ngày mai dù thế nào tôi cũng phải làm xong bài tập.”","words":["我","明天","说什么","也得","把作业","做完"],"answer":"我明天说什么也得把作业做完。","explanation":"Chủ ngữ + thời gian + 说什么也得 + V."},{"type":"sort","context":"Sắp xếp: “Lần này dù thế nào tôi cũng phải đi Cáp Nhĩ Tân ngắm tuyết.”","words":["这次","我","怎么着","也得","去","哈尔滨","看雪"],"answer":"这次我怎么着也得去哈尔滨看雪。","explanation":"怎么着也得 + V."},{"type":"sort","context":"Sắp xếp: “Dù bận đến đâu, Tết tôi nhất định phải về nhà.”","words":["不管","多忙","，","春节","我","说什么也得","回家"],"answer":"不管多忙，春节我说什么也得回家。","explanation":"Ôn 不管 (Bài 8) + 说什么也得."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"妈妈生病了，我说什么也得回去看看她。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 说什么也得 + V, biểu thị nhất định phải."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他说什么也得不去。","isCorrect":false,"correctVersion":"他说什么也不去。","explanation":"Phủ định: 说什么也不 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我说什么得去参加这个活动。","isCorrect":false,"correctVersion":"我说什么也得去参加这个活动。","explanation":"Thiếu 也."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Ngày mai dù thế nào tôi cũng phải dậy sớm một chút.","answer":"明天我说什么也得早点儿起床。","answerPy":"Míngtiān wǒ shuō shénme yě děi zǎodiǎnr qǐchuáng.","explanation":"Thời gian + 说什么也得 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Mùa đông đến Cáp Nhĩ Tân, dù thế nào cũng phải mặc quần áo dày.","answer":"冬天去哈尔滨，说什么也得穿厚衣服。","answerPy":"Dōngtiān qù Hā'ěrbīn, shuō shénme yě děi chuān hòu yīfu.","explanation":"说什么也得 + 穿厚衣服 (从课文1)."}]},{"point":"固定短语“有的是” — có thừa, có khối, thiếu gì","items":[{"context":"“Không sao, áo dày tớ có thừa.”","pre":"没问题，受得了，我","blank":"有的是","post":"厚衣服。","options":["有的是","有的","是有"],"answer":0,"explanation":"有的是 + N = có rất nhiều."},{"context":"“Đồ ăn ngon, đồ uống ngon có khối.”","pre":"过年时，家里有的是","blank":"好吃","post":"的、好喝的，孩子们特别开心。","options":["好吃","很多","多少"],"answer":0,"explanation":"有的是 + 好吃的、好喝的."},{"context":"“… muốn mua rau gì cũng mua được.”","pre":"这个市场特别大，有的是水果和菜，你想买什么菜","blank":"都","post":"能买到。","options":["都","才","再"],"answer":0,"explanation":"什么……都…… (đại từ phiếm chỉ, HSK 3)."},{"context":"“Đừng vội, sau này thiếu gì cơ hội.”","pre":"别着急，以后有的是","blank":"机会","post":"，这次没申请到也没关系。","options":["机会","误会","社会"],"answer":0,"explanation":"以后有的是机会 = sau này còn nhiều cơ hội."},{"context":"“Trời lạnh thế này cậu chịu nổi không?” (ôn V得了 – Bài 4)","pre":"这么冷的天气你","blank":"受","post":"得了吗？——没问题，我有的是厚衣服。","options":["受","冻","举"],"answer":0,"explanation":"受得了 / 受不了."},{"type":"sort","context":"Sắp xếp: “Tôi có thừa thời gian, có thể đi cùng bạn.”","words":["我","有的是","时间","，","可以","陪你","去"],"answer":"我有的是时间，可以陪你去。","explanation":"有的是 + N; 陪 (Bài 6)."},{"type":"sort","context":"Sắp xếp: “Chợ hoa tươi ở Quảng Châu hoa nhiều vô kể.”","words":["广州的","鲜花市场","里","有的是","花"],"answer":"广州的鲜花市场里有的是花。","explanation":"Nơi chốn + 有的是 + N."},{"type":"sort","context":"Sắp xếp: “Đừng lo, sau này thiếu gì cơ hội.”","words":["别","担心","，","以后","有的是","机会"],"answer":"别担心，以后有的是机会。","explanation":"Dùng để trấn an."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们学校有的是外国留学生。","isCorrect":true,"correctVersion":"","explanation":"Đúng: nơi chốn + 有的是 + N."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我有的是很多钱。","isCorrect":false,"correctVersion":"我有的是钱。","explanation":"Không thêm 很多 sau 有的是."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"图书馆里有的是五本中文书。","isCorrect":false,"correctVersion":"图书馆里有的是中文书。","explanation":"有的是 không đi với số lượng cụ thể."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đừng lo, ở Cáp Nhĩ Tân quần áo dày có thừa, muốn mua thì mua.","answer":"别担心，哈尔滨有的是厚衣服，想买就买。","answerPy":"Bié dānxīn, Hā'ěrbīn yǒudeshì hòu yīfu, xiǎng mǎi jiù mǎi.","explanation":"Nơi chốn + 有的是 + N."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thời gian còn thừa, chúng ta vẫn kịp.","answer":"时间有的是，我们还来得及。","answerPy":"Shíjiān yǒudeshì, wǒmen hái láidejí.","explanation":"有的是 + 来得及 (ôn Bài 4 · điểm 4)."}]},{"point":"连词“而” — còn, mà, nhưng; (vì …) mà …","items":[{"context":"“Quảng Châu gần như không có mùa đông, còn Cáp Nhĩ Tân …”","pre":"广州基本上没有冬天，","blank":"而","post":"哈尔滨的冬天一般会从十月开始。","options":["而","和","跟"],"answer":0,"explanation":"Đối lập hai đối tượng → 而 (和 / 跟 chỉ nối danh từ)."},{"context":"“Trong những ngày căng thẳng mà hào hứng này …”","pre":"在这个紧张","blank":"而","post":"兴奋的日子里，我们都走出教室，为运动员们加油。","options":["而","也","就"],"answer":0,"explanation":"Adj + 而 + Adj (nối tiếp)."},{"context":"“… vì thời tiết ấm mà thu hút nhiều du khách.”","pre":"冬天，这个城市因为天气暖和而","blank":"吸引","post":"了很多游客。","options":["吸引","引起","举办"],"answer":0,"explanation":"因为……而 + kết quả; 吸引游客 = thu hút du khách."},{"context":"“… còn tiếng Quảng Châu khác tiếng phổ thông khá nhiều.”","pre":"哈尔滨方言和普通话听起来比较像，而广州方言和普通话","blank":"差别","post":"较大。","options":["差别","气候","方言"],"answer":0,"explanation":"差别较大 = khác biệt khá lớn."},{"context":"“Trường do thời tiết xấu mà huỷ đại hội thể thao.” (ôn 由于 – Bài 2)","pre":"学校","blank":"由于","post":"天气不好而取消了运动会。","options":["由于","虽然","如果"],"answer":0,"explanation":"由于 / 因为 + nguyên nhân + 而 + kết quả."},{"type":"sort","context":"Sắp xếp: “Miền Nam mùa đông rất ấm, còn miền Bắc mùa đông rất lạnh.”","words":["南方","冬天","很暖和","，","而","北方","冬天","很冷"],"answer":"南方冬天很暖和，而北方冬天很冷。","explanation":"A……，而 B…… (đối lập)."},{"type":"sort","context":"Sắp xếp: “Cô ấy thể hiện nhiệt tình và tích cực.”","words":["她","表现得","热情","而","积极"],"answer":"她表现得热情而积极。","explanation":"Adj + 而 + Adj; 表现 (Bài 1)."},{"type":"sort","context":"Sắp xếp: “Sân trường vì nghỉ đông mà trở nên rất yên tĩnh.”","words":["校园","因为","放寒假","而","变得","十分安静"],"answer":"校园因为放寒假而变得十分安静。","explanation":"因为……而…… (nhân quả)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"哥哥喜欢安静，而弟弟喜欢热闹。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 而 nối hai vế đối lập."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我买了牛奶而面包。","isCorrect":false,"correctVersion":"我买了牛奶和面包。","explanation":"而 không nối hai danh từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他因为生病了，而所以没来上课。","isCorrect":false,"correctVersion":"他因为生病而没来上课。","explanation":"因为……而…… đã có ý nhân quả, không thêm 所以."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Miền Nam mùa đông rất ấm, còn miền Bắc mùa đông rất lạnh.","answer":"南方冬天很暖和，而北方冬天很冷。","answerPy":"Nánfāng dōngtiān hěn nuǎnhuo, ér běifāng dōngtiān hěn lěng.","explanation":"A……，而 B…… (đối lập)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thành phố này vì có nhiều hoa mà được gọi là “Thành phố hoa”.","answer":"这个城市因为花多而叫“花城”。","answerPy":"Zhège chéngshì yīnwèi huā duō ér jiào “huāchéng”.","explanation":"因为……而…… (nhân quả)."}]},{"point":"频率副词“再次” — lại một lần nữa, lần thứ hai","items":[{"context":"“… chúng ta lại một lần nữa phát động hoạt động “Sống xanh”.”","pre":"今年的“世界环境日”，我们","blank":"再次","post":"开展“绿色生活”活动。","options":["再次","从来","偶尔"],"answer":0,"explanation":"再次 + V."},{"context":"“… tôi định lại đi Cáp Nhĩ Tân ngắm tuyết.”","pre":"今年冬天，我计划再次去哈尔滨","blank":"看","post":"雪。","options":["看","见","冻"],"answer":0,"explanation":"看雪 = ngắm tuyết."},{"context":"“Một lần nữa xin cảm ơn sự ủng hộ và quan tâm của quý vị!”","pre":"","blank":"再次","post":"感谢您的支持与关心！","options":["再次","再说","此外"],"answer":0,"explanation":"再次感谢 — câu trang trọng cuối thư, phát biểu."},{"context":"“Trước khi ra khỏi nhà anh ấy kiểm tra lại hành lý lần nữa.”","pre":"他出门前再次","blank":"检查","post":"了一下行李，看看东西都带好了没有。","options":["检查","举办","开展"],"answer":0,"explanation":"再次 + 检查."},{"context":"“Dù lần trước không thành công, nhưng anh ấy vẫn …” (ôn Bài 9)","pre":"尽管上次没有成功，","blank":"但是","post":"他还是决定再次试一试。","options":["但是","而且","所以"],"answer":0,"explanation":"尽管……但是……"},{"type":"sort","context":"Sắp xếp: “Chào mừng ngài lại đến chỗ chúng tôi du lịch.”","words":["欢迎","您","再次","来","我们这里","旅游"],"answer":"欢迎您再次来我们这里旅游。","explanation":"再次 + 来."},{"type":"sort","context":"Sắp xếp: “Gặp lại bạn học cũ, mọi người đều đặc biệt vui.”","words":["再次","见到","老同学","，","大家","都特别高兴"],"answer":"再次见到老同学，大家都特别高兴。","explanation":"再次 + 见到."},{"type":"sort","context":"Sắp xếp: “Trường lại tổ chức hoạt động phân loại rác.”","words":["学校","再次","举办了","垃圾分类","活动"],"answer":"学校再次举办了垃圾分类活动。","explanation":"再次 + V了 (việc đã xảy ra)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"下个月我们会再次开展环保活动。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 再次 dùng cho việc sắp làm."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他又再次忘了带钥匙。","isCorrect":false,"correctVersion":"他再次忘了带钥匙。","explanation":"又 và 再次 trùng nghĩa — bỏ 又."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们再次了检查行李。","isCorrect":false,"correctVersion":"我们再次检查了行李。","explanation":"了 đặt sau động từ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Một lần nữa cảm ơn sự giúp đỡ của mọi người!","answer":"再次感谢大家的帮助！","answerPy":"Zàicì gǎnxiè dàjiā de bāngzhù!","explanation":"再次感谢 — trang trọng."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Năm sau tôi định lại đi Quảng Châu lần nữa.","answer":"明年我打算再次去广州。","answerPy":"Míngnián wǒ dǎsuàn zàicì qù Guǎngzhōu.","explanation":"Thời gian + 打算 / 计划 + 再次 + V."}]}],"/lessons/hsk4v3-bai-11.html":[{"point":"让步复句“即使……，也……” — cho dù …, cũng …","items":[{"context":"“Có những người dù tuổi đã cao vẫn kiên trì …”","pre":"有些人","blank":"即使","post":"年龄大了，也坚持去老年班学习。","options":["即使","虽然","因为"],"answer":0,"explanation":"Vế sau có 也 → vế trước dùng 即使 (giả thiết nhượng bộ)."},{"context":"“Cho dù mai mưa to, chúng ta cũng sẽ xuất phát đúng giờ.”","pre":"即使明天下大雨，我们","blank":"也","post":"会按时出发。","options":["也","就","才"],"answer":0,"explanation":"即使……，(Sub) + 也 + V."},{"context":"“Dù tuổi đã cao, ông vẫn kiên trì đi học máy tính.”","pre":"即使年龄大了，爷爷也","blank":"坚持","post":"去老年班学电脑。","options":["坚持","羡慕","散步"],"answer":0,"explanation":"坚持 + V = kiên trì làm gì."},{"context":"“… mỗi tuần anh ấy cũng gọi về nhà ít nhất một lần.” (ôn 至少 – Bài 5)","pre":"即使工作再忙，他也","blank":"至少","post":"每周给家里打一次电话。","options":["至少","甚至","从来"],"answer":0,"explanation":"至少 + V + số lượng = ít nhất."},{"context":"“Cho dù không học cùng trường nữa, chúng ta cũng phải thường xuyên liên lạc.”","pre":"","blank":"即使","post":"不在一个学校了，我们也要经常联系。","options":["即使","由于","随着"],"answer":0,"explanation":"Giả thiết bất lợi + 也 → 即使."},{"type":"sort","context":"Sắp xếp: “Cho dù ngày mai mưa to, chúng ta cũng sẽ xuất phát đúng giờ.”","words":["即使","明天","下大雨","，","我们","也会","按时出发"],"answer":"即使明天下大雨，我们也会按时出发。","explanation":"即使 + giả thiết，Sub + 也 + V."},{"type":"sort","context":"Sắp xếp: “Cho dù thiếu nước, hoa trước cửa vẫn mọc rất tốt.”","words":["即使","缺水","，","门前的花","也","长得","很好"],"answer":"即使缺水，门前的花也长得很好。","explanation":"也 đứng sau chủ ngữ 门前的花."},{"type":"sort","context":"Sắp xếp: “Anh ấy cho dù bận đến mấy cũng kiên trì rèn luyện thân thể.”","words":["他","即使","再忙","，","也","会","坚持锻炼身体"],"answer":"他即使再忙，也会坚持锻炼身体。","explanation":"即使 + 再 + Adj，也……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"即使大家都说很难，我也要试一试。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 即使……，Sub + 也……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"即使昨天下了大雨，但是比赛没有停。","isCorrect":false,"correctVersion":"虽然昨天下了大雨，但是比赛没有停。","explanation":"Sự thật đã xảy ra + 但是 → 虽然……但是……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"即使你不去，我去。","isCorrect":false,"correctVersion":"即使你不去，我也去。","explanation":"Thiếu 也."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cho dù tuổi đã cao, ông tôi vẫn kiên trì đi học lớp người cao tuổi.","answer":"即使年龄大了，我爷爷也坚持去老年班学习。","answerPy":"Jíshǐ niánlíng dà le, wǒ yéye yě jiānchí qù lǎoniánbān xuéxí.","explanation":"即使……，Sub + 也 + 坚持……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cho dù ngày mai mưa to, chúng ta cũng sẽ xuất phát đúng giờ.","answer":"即使明天下大雨，我们也会准时出发。","answerPy":"Jíshǐ míngtiān xià dàyǔ, wǒmen yě huì zhǔnshí chūfā.","explanation":"即使……也…… + từ mới 准时."}]},{"point":"让步复句“就是……，也……” — cho dù …, cũng … (khẩu ngữ)","items":[{"context":"“Mình cho dù không ở lớp cũng có thể học tiếng Trung …”","pre":"我","blank":"就是","post":"不在教室，也可以学习中文，和同学一起练口语。","options":["就是","就是了","只要"],"answer":0,"explanation":"就是 (liên từ) ở vế đầu + 也 ở vế sau."},{"context":"“… cho dù bận đến mấy cũng phải kiên trì tập thể thao.”","pre":"锻炼身体很重要，就是再忙，","blank":"也","post":"要坚持运动。","options":["也","就","才"],"answer":0,"explanation":"就是再 + Adj，也……"},{"context":"“… dù đêm nay không ngủ cũng phải sửa xong nó.”","pre":"明天开会需要这份材料，我就是今晚不睡觉，也要把它","blank":"改","post":"完。","options":["改","留","弹"],"answer":0,"explanation":"把 + O + 改完 (ôn câu chữ 把)."},{"context":"“Cho dù không ở cùng thành phố, chúng ta vẫn có thể gặp nhau trực tuyến.”","pre":"就是不在一个城市，我们也可以在","blank":"线上","post":"上见面。","options":["线上","线下","网友"],"answer":0,"explanation":"在线上 + V = trực tuyến."},{"context":"“… cho dù không có thầy, sau giờ học vẫn có thể xem video ghi lại để tự học.”","pre":"课上没听明白也没关系，就是没有老师，课后也能看","blank":"视频","post":"记录自学。","options":["视频","分数","口语"],"answer":0,"explanation":"视频记录 = video ghi lại."},{"type":"sort","context":"Sắp xếp: “Cho dù bận đến mấy cũng phải kiên trì tập thể thao.”","words":["就是","再忙","，","也","要","坚持运动"],"answer":"就是再忙，也要坚持运动。","explanation":"就是再 + Adj，也 + V."},{"type":"sort","context":"Sắp xếp: “Tôi dù đêm nay không ngủ cũng phải sửa xong tài liệu.”","words":["我","就是","今晚不睡觉","，","也要","把材料","改完"],"answer":"我就是今晚不睡觉，也要把材料改完。","explanation":"Sub + 就是……，也要 + 把……"},{"type":"sort","context":"Sắp xếp: “Cho dù mưa to, chúng ta cũng phải đi.”","words":["就是","下大雨","，","我们","也得","去"],"answer":"就是下大雨，我们也得去。","explanation":"也得 (děi) = cũng phải."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"就是再贵，我就买。","isCorrect":false,"correctVersion":"就是再贵，我也买。","explanation":"Vế sau của 就是 phải dùng 也."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"就是他是我的好朋友，我也不能帮他做这种事。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 就是 + một câu, vế sau 也 + phủ định."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他就是不来，我们开会也。","isCorrect":false,"correctVersion":"他就是不来，我们也开会。","explanation":"也 đứng trước động từ 开会."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cho dù bận đến mấy, cuối tuần tôi cũng sẽ dành thời gian đi dạo cùng ông bà.","answer":"就是再忙，周末我也会留出时间陪爷爷奶奶散步。","answerPy":"Jiùshì zài máng, zhōumò wǒ yě huì liúchū shíjiān péi yéye nǎinai sànbù.","explanation":"就是再忙，……也…… + từ mới 留, 散步."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cho dù không có thầy cô, chúng ta cũng có thể tự học trên mạng.","answer":"就是没有老师，我们也可以在网上自学。","answerPy":"Jiùshì méiyǒu lǎoshī, wǒmen yě kěyǐ zài wǎngshang zìxué.","explanation":"就是……，Sub + 也 + 可以 / 能……"}]},{"point":"并列复句“不是……，而是……” — không phải …, mà là …","items":[{"context":"“… không phải là để con thi điểm cao, mà là giúp con hình thành thói quen tốt.”","pre":"教育的目的不是让孩子考高分，","blank":"而是","post":"帮助孩子养成好习惯。","options":["而是","而且","还是"],"answer":0,"explanation":"不是……，而是…… (phủ định – khẳng định)."},{"context":"“Tôi không phải muốn uống trà, mà là muốn uống nước.”","pre":"我","blank":"不是","post":"想喝茶，而是想喝水。","options":["不是","不仅","没有"],"answer":0,"explanation":"而是 đi với 不是; 不仅 đi với 而且."},{"context":"“Cậu ấy học piano không phải vì điểm số, mà vì thật sự thích.”","pre":"他学钢琴不是为了","blank":"分数","post":"，而是因为真的喜欢。","options":["分数","礼貌","资料"],"answer":0,"explanation":"Hai vế đều nêu lý do: 为了…… / 因为……"},{"context":"“Họ không phải đang tán gẫu, mà là đang họp trực tuyến.”","pre":"他们不是在聊天儿，而是在开线上","blank":"会议","post":"。","options":["会议","视频","网页"],"answer":0,"explanation":"开会议 / 线上会议 = họp trực tuyến."},{"context":"“Con không vui không phải vì học quá khó, mà vì áp lực quá lớn.” (ôn từ 压力 – Bài 1)","pre":"孩子不开心，不是因为学习太难，而是因为","blank":"压力","post":"太大。","options":["压力","目的","做法"],"answer":0,"explanation":"压力大 = áp lực lớn."},{"type":"sort","context":"Sắp xếp: “Tôi không phải muốn uống trà, mà là muốn uống nước.”","words":["我","不是","想喝茶","，","而是","想喝水"],"answer":"我不是想喝茶，而是想喝水。","explanation":"不是 A，而是 B — A, B cùng loại."},{"type":"sort","context":"Sắp xếp: “Mục đích của giáo dục không phải là để con thi điểm cao, mà là giúp con hình thành thói quen tốt.”","words":["教育的目的","不是","让孩子考高分","，","而是","帮助孩子","养成好习惯"],"answer":"教育的目的不是让孩子考高分，而是帮助孩子养成好习惯。","explanation":"……的目的不是……，而是……"},{"type":"sort","context":"Sắp xếp: “Cậu ấy không phải đang chơi game, mà là đang luyện nói.”","words":["他","不是","在玩游戏","，","而是","在练口语"],"answer":"他不是在玩游戏，而是在练口语。","explanation":"在 + V: đang làm gì; hai vế cân đối."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我放学后不是直接回家，而是先去超市买笔。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 不是 / 而是 cùng đứng trước phần so sánh."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"教育的目的不是让孩子考高分，而且帮助孩子养成好习惯。","isCorrect":false,"correctVersion":"教育的目的不是让孩子考高分，而是帮助孩子养成好习惯。","explanation":"不是 đi với 而是, không đi với 而且."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我不是不想去，而实在来不及了。","isCorrect":false,"correctVersion":"我不是不想去，而是实在来不及了。","explanation":"Không bỏ 是 trong 而是."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi học tiếng Trung không phải vì công việc, mà là vì thích văn hóa Trung Quốc.","answer":"我学中文不是因为工作，而是因为喜欢中国文化。","answerPy":"Wǒ xué Zhōngwén bú shì yīnwèi gōngzuò, érshì yīnwèi xǐhuan Zhōngguó wénhuà.","explanation":"不是因为……，而是因为…… (hai vế cùng nêu lý do)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Mục đích của giáo dục không phải là điểm số, mà là giúp trẻ hình thành thói quen tốt.","answer":"教育的目的不是分数，而是帮助孩子养成好习惯。","answerPy":"Jiàoyù de mùdì bú shì fēnshù, érshì bāngzhù háizi yǎngchéng hǎo xíguàn.","explanation":"目的 + 不是……，而是…… + từ mới 分数, 养成."}]},{"point":"固定短语“就是说” — tức là, nghĩa là, nói cách khác","items":[{"context":"“Con người phải luôn kiên trì học tập, nghĩa là …”","pre":"人要一直坚持学习，","blank":"就是说","post":"，学习是人一生的事情。","options":["就是说","就是了","不是说"],"answer":0,"explanation":"就是说 đứng giữa, giải thích lại câu trước."},{"context":"“Đừng vội viết, tức là đừng vội đặt bút …”","pre":"别着急写，就是说，别着急动","blank":"笔","post":"，想好后再写。","options":["笔","脑","心"],"answer":0,"explanation":"动笔 = đặt bút viết."},{"context":"“… nghĩa là bạn hoàn thành càng nhiều thì lương càng cao.”","pre":"工资是根据你工作的完成情况来发的，就是说，你完成得","blank":"越","post":"多，工资越高。","options":["越","更","最"],"answer":0,"explanation":"越……越…… (HSK 3)."},{"context":"“… tức là phải sống đến già học đến già.”","pre":"“学而不厌”的意思是人要一直坚持学习，就是说，要活到老","blank":"学","post":"到老。","options":["学","活","教"],"answer":0,"explanation":"活到老学到老."},{"context":"“… tức là bất kể lúc nào bạn cũng có thể đi đọc sách.” (ôn 不管 – Bài 8)","pre":"图书馆二十四小时开门，就是说，","blank":"不管","post":"什么时候你都可以去看书。","options":["不管","即使","虽然"],"answer":0,"explanation":"不管 + đại từ nghi vấn + 都……"},{"type":"sort","context":"Sắp xếp: “Con người phải luôn kiên trì học tập, nghĩa là học tập là việc cả đời.”","words":["人","要","一直坚持学习","，","就是说","，","学习是人一生的事情"],"answer":"人要一直坚持学习，就是说，学习是人一生的事情。","explanation":"Câu A，就是说，câu B."},{"type":"sort","context":"Sắp xếp: “Đừng vội viết, tức là nghĩ kỹ rồi hãy viết.”","words":["别着急写","，","就是说","，","想好后","再写"],"answer":"别着急写，就是说，想好后再写。","explanation":"就是说 + giải thích cụ thể."},{"type":"sort","context":"Sắp xếp: “Ngày mai được nghỉ, tức là chúng ta không phải đến trường.”","words":["明天放假","，","就是说","，","我们","不用","去学校了"],"answer":"明天放假，就是说，我们不用去学校了。","explanation":"就是说 + hệ quả trực tiếp."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他会说英语、法语和中文，就是说，他会三种语言。","isCorrect":true,"correctVersion":"","explanation":"Đúng: câu sau nói lại cùng ý bằng cách khác."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"明天下雨，就是说，我们去公园吧。","isCorrect":false,"correctVersion":"明天会下雨，就是说，我们不能去公园了。","explanation":"Câu sau phải là giải thích / hệ quả của câu trước."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这家店二十四小时开门，就是说，晚上它不开门。","isCorrect":false,"correctVersion":"这家店二十四小时开门，就是说，什么时候去都可以。","explanation":"Câu sau mâu thuẫn với câu trước."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cửa hàng này mở cửa 24 giờ, nghĩa là lúc nào bạn cũng có thể đến.","answer":"这家店二十四小时开门，就是说，你什么时候都可以来。","answerPy":"Zhè jiā diàn èr shísì xiǎoshí kāimén, jiùshì shuō, nǐ shénme shíhou dōu kěyǐ lái.","explanation":"就是说 + đại từ nghi vấn phiếm chỉ 什么时候都……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Lớp học số có thể chụp ảnh điểm danh, tức là giáo sư không cần gọi tên từng người nữa.","answer":"数字教室可以拍照点名，就是说，教授不用一个个叫名字了。","answerPy":"Shùzì jiàoshì kěyǐ pāizhào diǎnmíng, jiùshì shuō, jiàoshòu búyòng yígègè jiào míngzi le.","explanation":"就是说 + từ mới 数字, 点名, 教授."}]}],"/lessons/hsk4v3-bai-12.html":[{"point":"固定短语“不怎么” — không … lắm; ít khi","items":[{"context":"“Chỉ là màu hình như không hợp với mẹ lắm.”","pre":"样子不错，就是颜色好像","blank":"不怎么","post":"适合她。","options":["不怎么","怎么不","不什么"],"answer":0,"explanation":"不怎么 + động từ 适合 = không hợp lắm."},{"context":"“… ít khi ra ngoài chơi.”","pre":"他总是在图书馆看书，","blank":"不怎么","post":"出去玩。","options":["不怎么","怎么","很少的"],"answer":0,"explanation":"不怎么 + động từ hành động = ít khi."},{"context":"“… không thích ăn cơm lắm.”","pre":"我爱吃饺子、包子，不怎么","blank":"喜欢","post":"吃米饭。","options":["喜欢","多","很"],"answer":0,"explanation":"不怎么 + động từ tâm lý 喜欢."},{"context":"“Hôm nay không lạnh lắm, không cần mặc áo len nữa.” (ôn từ 毛衣)","pre":"今天不怎么","blank":"冷","post":"，不用穿毛衣了。","options":["冷","伤心","热闹"],"answer":0,"explanation":"不怎么 + tính từ."},{"context":"“Ít khi đi, dạo này bận quá.”","pre":"A：你常去体育馆打球吗？ B：","blank":"不怎么","post":"去，最近太忙了。","options":["不怎么","怎么不","没怎么样"],"answer":0,"explanation":"Trả lời câu hỏi về tần suất: 不怎么去 = ít khi đi."},{"type":"sort","context":"Sắp xếp: “Màu sắc hình như không hợp với cô ấy lắm.”","words":["颜色","好像","不怎么","适合","她"],"answer":"颜色好像不怎么适合她。","explanation":"好像 + 不怎么 + V."},{"type":"sort","context":"Sắp xếp: “Cậu ấy lúc nào cũng đọc sách ở thư viện, ít khi ra ngoài chơi.”","words":["他","总是","在图书馆","看书","，","不怎么","出去玩"],"answer":"他总是在图书馆看书，不怎么出去玩。","explanation":"不怎么 đứng trước động từ."},{"type":"sort","context":"Sắp xếp: “Dạo này tôi ít khi đến nhà thi đấu chơi bóng.”","words":["我","最近","不怎么","去","体育馆","打球"],"answer":"我最近不怎么去体育馆打球。","explanation":"Trạng ngữ thời gian 最近 + 不怎么 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服不怎么很好看。","isCorrect":false,"correctVersion":"这件衣服不怎么好看。","explanation":"Không dùng 很 sau 不怎么."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我不怎么喜欢喝咖啡，更喜欢喝茶。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 不怎么 + 喜欢."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我昨天不怎么去上课。","isCorrect":false,"correctVersion":"我昨天没去上课。","explanation":"Việc cụ thể đã xảy ra → phủ định bằng 没."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chiếc áo len này kiểu dáng đẹp, chỉ là chất lượng không tốt lắm.","answer":"这件毛衣样子很好看，就是质量不怎么好。","answerPy":"Zhè jiàn máoyī yàngzi hěn hǎokàn, jiùshì zhìliàng bù zěnme hǎo.","explanation":"……，就是…… (Bài 3) + 不怎么 + tính từ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Ông tôi ít khi xem tivi, thích ra công viên đi dạo hơn.","answer":"我爷爷不怎么看电视，更喜欢去公园散步。","answerPy":"Wǒ yéye bù zěnme kàn diànshì, gèng xǐhuan qù gōngyuán sànbù.","explanation":"不怎么 + V = ít khi."}]},{"point":"双重否定 — 不是不 / 不能不 / 不得不: khẳng định với giọng mạnh hơn","items":[{"context":"“Nó cũng không phải không biết mình sai, chỉ là ngại nói.”","pre":"他也","blank":"不是","post":"不知道自己错了，只是不好意思说。","options":["不是","不能","不得"],"answer":0,"explanation":"不是不 + V: thanh minh, giải thích."},{"context":"“… cậu lại là lớp trưởng, không thể không đến!”","pre":"今天是毕业后第一次同学聚餐，你又是班长，","blank":"不能不","post":"来啊！","options":["不能不","不能","不来不"],"answer":0,"explanation":"不能不 + V = nhất định phải."},{"context":"“… bố đành phải thay đổi kế hoạch.”","pre":"由于天气不好，飞机不能起飞，爸爸","blank":"不得不","post":"改变计划。","options":["不得不","不是不","不怎么"],"answer":0,"explanation":"Hoàn cảnh ép buộc → 不得不."},{"context":"“Tôi không phải không muốn tham gia, mà là thật sự không có thời gian.”","pre":"我不是不想参加，","blank":"是","post":"实在没有时间。","options":["是","就","也"],"answer":0,"explanation":"不是不……，是…… (cũng có thể nói 而是)."},{"context":"“Ông bà lớn tuổi rồi, chúng ta không thể không chăm sóc chu đáo.”","pre":"爷爷奶奶年纪大了，我们","blank":"不能不","post":"好好照顾他们。","options":["不能不","不是不","不怎么"],"answer":0,"explanation":"Trách nhiệm, tình cảm → 不能不."},{"type":"sort","context":"Sắp xếp: “Nó cũng không phải không biết mình sai.”","words":["他","也","不是","不知道","自己错了"],"answer":"他也不是不知道自己错了。","explanation":"不是 + 不知道."},{"type":"sort","context":"Sắp xếp: “Cậu là lớp trưởng, không thể không đến.”","words":["你","是班长","，","不能不","来","啊"],"answer":"你是班长，不能不来啊。","explanation":"不能不 + V."},{"type":"sort","context":"Sắp xếp: “Vì mưa to, chúng tôi buộc phải thay đổi kế hoạch.”","words":["因为","下大雨","，","我们","不得不","改变","计划"],"answer":"因为下大雨，我们不得不改变计划。","explanation":"Chủ ngữ + 不得不 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件事我不得不告诉他。","isCorrect":true,"correctVersion":"","explanation":"Đúng: buộc phải nói cho anh ấy biết."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他病了，不得不不去上班。","isCorrect":false,"correctVersion":"他病了，不得不请假。","explanation":"Sau 不得不 là động từ khẳng định."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我不是不想去，是实在没有时间。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 不是不想去 = muốn đi chứ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Không phải tôi không muốn giúp bạn, mà là tôi thật sự không có thời gian.","answer":"我不是不想帮你，是我实在没有时间。","answerPy":"Wǒ bú shì bù xiǎng bāng nǐ, shì wǒ shízai méiyǒu shíjiān.","explanation":"不是不……，(而)是…… — kết hợp Bài 11 · điểm 3."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Vì trời mưa to, chúng tôi đành phải ở nhà.","answer":"因为下大雨，我们不得不待在家里。","answerPy":"Yīnwèi xià dàyǔ, wǒmen bùdébù dāi zài jiāli.","explanation":"不得不 + 待在家里 (từ mới 待 dāi)."}]},{"point":"条件复句“无论……，都/也……” — dù … (thế nào) … cũng …","items":[{"context":"“Dù ngày thường công việc bận đến đâu …”","pre":"","blank":"无论","post":"平时工作有多忙，他每个周末都会给父母打电话。","options":["无论","虽然","因为"],"answer":0,"explanation":"无论 + 多 + tính từ."},{"context":"“… trong mắt bố mẹ con đều là giỏi nhất.”","pre":"无论你考多少分，你在我们眼里","blank":"都","post":"是最优秀的。","options":["都","就","才"],"answer":0,"explanation":"无论……，都……"},{"context":"“Dù con đi đâu cũng phải gọi điện về nhà.”","pre":"无论你去","blank":"哪儿","post":"，都要给家里打个电话。","options":["哪儿","北京","那儿"],"answer":0,"explanation":"Sau 无论 dùng từ nghi vấn 哪儿, không dùng địa điểm cụ thể."},{"context":"“Dù gió hay mưa …”","pre":"无论刮风","blank":"还是","post":"下雨，爷爷每天都去公园跑步。","options":["还是","或者","和"],"answer":0,"explanation":"无论 A 还是 B (không dùng 或者)."},{"context":"“Dù gặp chuyện gì cũng đừng sốt ruột.”","pre":"无论遇到什么事，","blank":"也","post":"不要着急。","options":["也","就","才"],"answer":0,"explanation":"无论……，也 + phủ định."},{"type":"sort","context":"Sắp xếp: “Dù công việc bận đến đâu, anh ấy cũng gọi điện cho bố mẹ.”","words":["无论","工作","多忙","，","他","都","给父母","打电话"],"answer":"无论工作多忙，他都给父母打电话。","explanation":"无论 + 多忙，chủ ngữ + 都 + V."},{"type":"sort","context":"Sắp xếp: “Dù em đi đâu, anh cũng đi cùng em.”","words":["无论","你","去哪儿","，","我","都","跟你去"],"answer":"无论你去哪儿，我都跟你去。","explanation":"无论 + 哪儿."},{"type":"sort","context":"Sắp xếp: “Dù gió hay mưa, ông ấy vẫn kiên trì chạy bộ.”","words":["无论","刮风","还是","下雨","，","他","都","坚持跑步"],"answer":"无论刮风还是下雨，他都坚持跑步。","explanation":"无论 A 还是 B，都……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"无论明天下雨，我们都去。","isCorrect":false,"correctVersion":"无论明天下不下雨，我们都去。","explanation":"Sau 无论 cần dạng không xác định: 下不下雨."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"无论你多大，在父母眼里你都是孩子。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 无论 + 多大，都……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"无论你去哪儿，我跟你去。","isCorrect":false,"correctVersion":"无论你去哪儿，我都跟你去。","explanation":"Vế sau phải có 都 / 也."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Dù bận đến đâu, cuối tuần nào anh ấy cũng gọi điện cho bố mẹ.","answer":"无论多忙，他每个周末都给父母打电话。","answerPy":"Wúlùn duō máng, tā měi gè zhōumò dōu gěi fùmǔ dǎdiànhuà.","explanation":"无论 + 多忙，chủ ngữ + 每个周末 + 都……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Dù em gặp khó khăn gì, bất cứ lúc nào cũng có thể bàn bạc với bố mẹ.","answer":"无论你遇到什么困难，任何时候都可以和父母商量。","answerPy":"Wúlùn nǐ yùdào shénme kùnnan, rènhé shíhou dōu kěyǐ hé fùmǔ shāngliang.","explanation":"无论……什么…… + ôn 任何……都…… (Bài 1 · điểm 1)."}]},{"point":"固定格式“为了……而……” — vì (để) … mà …","items":[{"context":"“… vì tiết kiệm thời gian mà không ăn uống tử tế.”","pre":"父母总是担心她为了节约时间","blank":"而","post":"不好好吃饭。","options":["而","就","才"],"answer":0,"explanation":"为了…… + 而 + hành động."},{"context":"“Chúng ta đều đang nỗ lực làm việc vì cuộc sống hạnh phúc.”","pre":"我们都在","blank":"为了","post":"生活幸福而努力工作着。","options":["为了","因为","随着"],"answer":0,"explanation":"为了 nêu mục đích (khác 因为 nêu nguyên nhân)."},{"context":"“… từ chối dùng cốc giấy.”","pre":"他们为了保护环境而","blank":"拒绝","post":"使用纸杯。","options":["拒绝","允许","商量"],"answer":0,"explanation":"Hành động sau 而: 拒绝使用."},{"context":"“Để đồ ăn tươi ngon, bố chọn chuyển phát nhanh nhất.”","pre":"","blank":"为了","post":"让食物新鲜，父亲选择了城里最快的快递。","options":["为了","无论","因为"],"answer":0,"explanation":"为了……，…… (dạng có dấu phẩy, HSK 3)."},{"context":"“Cô ấy vì chăm sóc mẹ bị bệnh mà ở lại quê.” (ôn từ mới 待 dāi)","pre":"她为了照顾生病的母亲而","blank":"待","post":"在老家。","options":["待","挂","脱"],"answer":0,"explanation":"而 + 待在 + nơi."},{"type":"sort","context":"Sắp xếp: “Chúng ta đều đang nỗ lực làm việc vì cuộc sống hạnh phúc.”","words":["我们","都在","为了","生活幸福","而","努力工作着"],"answer":"我们都在为了生活幸福而努力工作着。","explanation":"Chủ ngữ + 都在 + 为了…… + 而 + V着."},{"type":"sort","context":"Sắp xếp: “Họ từ chối dùng cốc giấy để bảo vệ môi trường.”","words":["他们","为了","保护环境","而","拒绝","使用纸杯"],"answer":"他们为了保护环境而拒绝使用纸杯。","explanation":"为了 + mục đích + 而 + hành động."},{"type":"sort","context":"Sắp xếp: “Cậu ấy vì muốn sang Trung Quốc du học mà chăm chỉ học tiếng Trung.”","words":["他","为了","去中国留学","而","努力","学中文"],"answer":"他为了去中国留学而努力学中文。","explanation":"Bài tập SGK câu 2."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"为了节约时间，而他不好好吃饭。","isCorrect":false,"correctVersion":"他为了节约时间而不好好吃饭。","explanation":"Chủ ngữ trước 为了; 而 ngay trước hành động."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她为了参加比赛而每天练习三个小时。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 为了 + mục đích + 而 + hành động."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我为了考试而。","isCorrect":false,"correctVersion":"我为了考试而努力复习。","explanation":"Sau 而 phải có hành động."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bố mẹ luôn lo cô ấy vì tiết kiệm thời gian mà không ăn uống tử tế.","answer":"父母总是担心她为了节约时间而不好好吃饭。","answerPy":"Fùmǔ zǒngshì dānxīn tā wèile jiéyuē shíjiān ér bù hǎohāo chīfàn.","explanation":"为了…… + 而 + 不好好吃饭."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Họ đang nỗ lực làm việc vì một cuộc sống hạnh phúc.","answer":"他们正在为了生活幸福而努力工作。","answerPy":"Tāmen zhèngzài wèile shēnghuó xìngfú ér nǔlì gōngzuò.","explanation":"正在 + 为了…… + 而 + V."}]}],"/lessons/hsk4v3-bai-13.html":[{"point":"固定格式“怎么都/也+不/没……” — thế nào cũng không …, mãi mà không …","items":[{"context":"“… tìm mãi mà không thấy, lạ thật.”","pre":"她在包里找了半天，","blank":"怎么","post":"都没找到，真奇怪。","options":["怎么","什么","哪儿"],"answer":0,"explanation":"怎么 + 都 + 没 + V到."},{"context":"“… nhưng thế nào cũng không ngờ lại rộng đến thế!”","pre":"我知道北京野生动物园很大，可怎么","blank":"也","post":"没想到这么大！","options":["也","还","就"],"answer":0,"explanation":"怎么也没想到 = không ngờ (ngạc nhiên)."},{"context":"“… nhưng con gấu trúc đó nhất định không chịu ra.”","pre":"我们等了两个多小时，可是那只熊猫怎么都","blank":"不","post":"出来。","options":["不","没","别"],"answer":0,"explanation":"Ý muốn của con vật (không chịu) → 不."},{"context":"“Tối qua nóng quá, tôi trằn trọc mãi không ngủ được.”","pre":"昨天晚上太热了，我怎么也睡","blank":"不","post":"着。","options":["不","没","得"],"answer":0,"explanation":"Bổ ngữ khả năng 睡不着."},{"context":"“… làm mãi mà không ra.”","pre":"这道题太难了，我做了好久，怎么都做","blank":"不","post":"出来。","options":["不","没","得"],"answer":0,"explanation":"Bổ ngữ khả năng 做不出来."},{"type":"sort","context":"Sắp xếp: “Cô ấy lục trong túi nửa ngày mà tìm mãi không thấy.”","words":["她","在包里","找了半天","，","怎么","都","没找到"],"answer":"她在包里找了半天，怎么都没找到。","explanation":"V了半天，怎么都没 + V到."},{"type":"sort","context":"Sắp xếp: “Tôi thế nào cũng không nhớ ra tên anh ấy.”","words":["我","怎么","也","想不起来","他的名字"],"answer":"我怎么也想不起来他的名字。","explanation":"怎么也 + V不起来."},{"type":"sort","context":"Sắp xếp: “Tôi biết ở đây rộng, nhưng không ngờ lại rộng thế này.”","words":["我","知道","这里很大","，","可","怎么也","没想到","这么大"],"answer":"我知道这里很大，可怎么也没想到这么大。","explanation":"可 + 怎么也没想到 (ngạc nhiên)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我怎么都找到不我的手机。","isCorrect":false,"correctVersion":"我怎么都找不到我的手机。","explanation":"Phải là bổ ngữ khả năng 找不到."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"那只熊猫怎么都不出来，我们只好走了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 怎么都 + 不 + V (con vật không chịu ra)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他怎么都没睡不着。","isCorrect":false,"correctVersion":"他怎么都睡不着。","explanation":"没 và 不 không đi chung; dùng bổ ngữ khả năng 睡不着."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi gọi cho anh ấy mấy lần, thế nào cũng không gọi được.","answer":"我给他打了好几次电话，怎么都打不通。","answerPy":"Wǒ gěi tā dǎ le hǎojǐ cì diànhuà, zěnme dōu dǎ bù tōng.","explanation":"怎么都 / 也 + V不通 (bổ ngữ khả năng)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi biết kỳ thi này khó, nhưng thế nào cũng không ngờ lại khó đến vậy.","answer":"我知道这次考试很难，可怎么也没想到这么难。","answerPy":"Wǒ zhīdao zhè cì kǎoshì hěn nán, kě zěnme yě méi xiǎngdào zhème nán.","explanation":"怎么也没想到 + 这么 + Adj (ngạc nhiên)."}]},{"point":"固定格式“一+量词+比+一+量词” — cái sau hơn cái trước, ngày càng …","items":[{"context":"“… trời cũng ngày một nóng hơn.”","pre":"夏天快到了，天气也一天比一","blank":"天","post":"热。","options":["天","年","个"],"answer":0,"explanation":"Hai lượng từ giống nhau: 一天比一天."},{"context":"“Cốc ở đây cái nào cũng đẹp hơn cái nào.”","pre":"这家店里的杯子一个","blank":"比","post":"一个漂亮，我都不知道选哪个了。","options":["比","跟","和"],"answer":0,"explanation":"一个 + 比 + 一个 + Adj."},{"context":"“… năm sau náo nhiệt hơn năm trước.”","pre":"这几年，中秋节的活动一年比一年","blank":"热闹","post":"。","options":["热闹","很热闹","热闹多了"],"answer":0,"explanation":"Tính từ đứng trần, không thêm 很 / 多了."},{"context":"“Ba anh em nhà họ, người sau cao hơn người trước.”","pre":"他们兄弟三个，一","blank":"个","post":"比一个高。","options":["个","天","次"],"answer":0,"explanation":"So người → lượng từ 个."},{"context":"“… đời sống năm sau tốt hơn năm trước.” (ôn 随着)","pre":"随着经济的发展，人们的生活","blank":"一年比一年","post":"好。","options":["一年比一年","一年比两年","一年一年"],"answer":0,"explanation":"一年比一年 + Adj."},{"type":"sort","context":"Sắp xếp: “Trời ngày một lạnh hơn rồi.”","words":["天气","一天","比","一天","冷","了"],"answer":"天气一天比一天冷了。","explanation":"一天比一天 + Adj + 了 (thay đổi)."},{"type":"sort","context":"Sắp xếp: “Mấy năm nay Trung thu năm sau náo nhiệt hơn năm trước.”","words":["这几年","中秋节","一年","比","一年","热闹"],"answer":"这几年中秋节一年比一年热闹。","explanation":"Chủ ngữ + 一年比一年 + Adj."},{"type":"sort","context":"Sắp xếp: “Quần áo ở đây bộ nào cũng đẹp hơn bộ nào.”","words":["这儿的","衣服","一件","比","一件","漂亮"],"answer":"这儿的衣服一件比一件漂亮。","explanation":"Lượng từ 件 cho quần áo."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"天气一天比一天很热。","isCorrect":false,"correctVersion":"天气一天比一天热。","explanation":"Không thêm 很 trước tính từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们班的同学一个比一个努力。","isCorrect":true,"correctVersion":"","explanation":"Đúng: so nhiều người, ai cũng chăm chỉ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他的中文一天比两天好。","isCorrect":false,"correctVersion":"他的中文一天比一天好。","explanation":"Hai vế đều là 一 + cùng lượng từ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Từ khi đến Trung Quốc, tiếng Trung của tôi ngày một tốt hơn.","answer":"来中国以后，我的中文一天比一天好。","answerPy":"Lái Zhōngguó yǐhòu, wǒ de Zhōngwén yì tiān bǐ yì tiān hǎo.","explanation":"一天比一天 + Adj."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Những món mẹ nấu, món nào cũng ngon hơn món nào.","answer":"妈妈做的菜一个比一个好吃。","answerPy":"Māma zuò de cài yí gè bǐ yí gè hǎochī.","explanation":"一个 / 一道 + 比 + 一个 / 一道 + 好吃."}]},{"point":"用“大约”“左右”表示概数 — khoảng, chừng","items":[{"context":"“Khoảng năm giờ sáng họ đã lên tàu cao tốc.”","pre":"早上五点","blank":"左右","post":"他们就坐上了高铁。","options":["左右","大约","大概"],"answer":0,"explanation":"Sau thời gian dùng 左右."},{"context":"“Chừng bảy giờ họ đã đến thành phố …”","pre":"他们","blank":"大约","post":"七点就来到了儿子工作的城市。","options":["大约","左右","以后"],"answer":0,"explanation":"Trước thời gian dùng 大约."},{"context":"“Khoảng mười hai giờ trưa tôi đến trường các bạn.”","pre":"我中午十二点","blank":"左右","post":"到你们学校。","options":["左右","大约","刚才"],"answer":0,"explanation":"Thời gian + 左右."},{"context":"“… tối khoảng mười giờ rưỡi mới về đến nhà.”","pre":"昨天飞机晚点，我晚上","blank":"大约","post":"十点半才到家。","options":["大约","左右","已经"],"answer":0,"explanation":"大约 + thời gian + 才."},{"context":"“Từ đây đến khu du lịch đi xe mất khoảng một tiếng.”","pre":"从这儿到景区坐车要一个小时","blank":"左右","post":"。","options":["左右","大约","以后"],"answer":0,"explanation":"Thời đoạn + 左右."},{"type":"sort","context":"Sắp xếp: “Chúng ta khoảng bảy giờ gặp nhau ở cổng nhà hát.”","words":["我们","大约","七点","在剧院门口","见面"],"answer":"我们大约七点在剧院门口见面。","explanation":"Chủ ngữ + 大约 + thời gian + nơi chốn + V."},{"type":"sort","context":"Sắp xếp: “Tối nào anh ấy cũng đi ngủ khoảng mười một giờ.”","words":["他","每天","晚上","十一点左右","睡觉"],"answer":"他每天晚上十一点左右睡觉。","explanation":"Thời gian + 左右 + V."},{"type":"sort","context":"Sắp xếp: “Thành phố này có khoảng mười triệu người.”","words":["这个城市","大约","有","一千万","人"],"answer":"这个城市大约有一千万人。","explanation":"大约 + 有 + số lượng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"左右八点我们出发吧。","isCorrect":false,"correctVersion":"八点左右我们出发吧。","explanation":"左右 đứng sau thời gian."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他看起来三十岁左右。","isCorrect":true,"correctVersion":"","explanation":"Đúng: số tuổi + 左右."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们七点大约到。","isCorrect":false,"correctVersion":"我们大约七点到。","explanation":"大约 đứng trước thời gian."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Khoảng tám giờ sáng mai chúng ta xuất phát, đừng đến muộn nhé.","answer":"明天早上八点左右我们出发，别迟到。","answerPy":"Míngtiān zǎoshang bā diǎn zuǒyòu wǒmen chūfā, bié chídào.","explanation":"八点左右 / 大约八点."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Từ nhà tôi đến trường đi bộ mất khoảng hai mươi phút.","answer":"从我家到学校走路要二十分钟左右。","answerPy":"Cóng wǒ jiā dào xuéxiào zǒulù yào èrshí fēnzhōng zuǒyòu.","explanation":"Thời đoạn + 左右 / 大约 + 要 + thời đoạn."}]},{"point":"介词“作为” — với tư cách là, là (một …)","items":[{"context":"“Là ngày lễ truyền thống quan trọng nhất trong năm …”","pre":"","blank":"作为","post":"一年里最重要的传统节日，春节对中国人来说有着特别的意义。","options":["作为","因为","成为"],"answer":0,"explanation":"作为 + N (tính chất của sự vật)."},{"context":"“… giá cũng không cao.” (ôn 不仅……也……)","pre":"作为新产品，这个手机不仅样子好看，价格","blank":"也","post":"不高。","options":["也","就","才"],"answer":0,"explanation":"不仅……，……也…… (Bài 3 · điểm 2)."},{"context":"“… luôn quan tâm, giúp đỡ lẫn nhau.”","pre":"作为好朋友，我们一直","blank":"互相","post":"关心、互相帮助。","options":["互相","一起","自己"],"answer":0,"explanation":"互相 + V = lẫn nhau."},{"context":"“Là cha mẹ, chúng ta nên ở bên con nhiều hơn.”","pre":"作为父母，","blank":"我们","post":"应该多陪陪孩子。","options":["我们","孩子们","老师"],"answer":0,"explanation":"Chủ ngữ vế sau phải là người mang thân phận “cha mẹ”."},{"context":"“Là một bác sĩ, ngày nào cô ấy cũng quan tâm bệnh nhân.”","pre":"她","blank":"作为","post":"一名医生，每天都很关心病人。","options":["作为","对于","关于"],"answer":0,"explanation":"Chủ ngữ + 作为 + N."},{"type":"sort","context":"Sắp xếp: “Là học sinh, chúng ta nên học hành chăm chỉ.”","words":["作为","学生","，","我们","应该","好好学习"],"answer":"作为学生，我们应该好好学习。","explanation":"作为 + N，chủ ngữ + V."},{"type":"sort","context":"Sắp xếp: “Là người Bắc Kinh, tôi nhất định phải mời bạn ăn vịt quay.”","words":["作为","北京人","，","我","一定要","请你","吃烤鸭"],"answer":"作为北京人，我一定要请你吃烤鸭。","explanation":"作为 + thân phận，我 + ……"},{"type":"sort","context":"Sắp xếp: “Là ngày lễ truyền thống quan trọng nhất của Trung Quốc, Tết có ý nghĩa đặc biệt.”","words":["作为","中国","最重要的","传统节日","，","春节","有着","特别的意义"],"answer":"作为中国最重要的传统节日，春节有着特别的意义。","explanation":"作为 + N (tính chất của vật)，chủ ngữ + 有着……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"是学生，我们应该好好学习。","isCorrect":false,"correctVersion":"作为学生，我们应该好好学习。","explanation":"Đầu câu dùng 作为, không dùng 是."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"作为一名老师，学生们都很喜欢他。","isCorrect":false,"correctVersion":"作为一名老师，他很关心学生。","explanation":"Người là “giáo viên” (他) phải làm chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"作为新产品，这个手机的价格不太高。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 作为 + N chỉ tính chất của sự vật."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Là người Việt Nam, tôi rất thích Tết.","answer":"作为越南人，我很喜欢过春节。","answerPy":"Zuòwéi Yuènánrén, wǒ hěn xǐhuan guò Chūnjié.","explanation":"作为 + thân phận，我 + ……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Là lớp trưởng, cậu ấy luôn quan tâm đến mọi người.","answer":"作为班长，他一直很关心大家。","answerPy":"Zuòwéi bānzhǎng, tā yìzhí hěn guānxīn dàjiā.","explanation":"作为 + chức vụ，他 + ……"}]}],"/lessons/hsk4v3-bai-14.html":[{"point":"语气副词“究竟” — rốt cuộc, cuối cùng thì","items":[{"context":"“… rốt cuộc nên mua loại nào đây?”","pre":"这里茶叶这么多，","blank":"究竟","post":"买哪种好呢？","options":["究竟","已经","一共"],"answer":0,"explanation":"究竟 + câu hỏi có đại từ nghi vấn 哪."},{"context":"“… rốt cuộc anh ấy đi đâu rồi?”","pre":"我一直没找到他，他究竟去哪里了","blank":"呢","post":"？","options":["呢","吗","吧"],"answer":0,"explanation":"Câu có 究竟 cuối câu dùng 呢, không dùng 吗."},{"context":"“Mai rốt cuộc cậu có đi hay không?”","pre":"你明天究竟去","blank":"不","post":"去？快决定吧！","options":["不","没","也"],"answer":0,"explanation":"究竟 + V不V (việc tương lai dùng 不)."},{"context":"“Rốt cuộc là đúng hay sai?”","pre":"","blank":"究竟","post":"是对还是错？我现在也不清楚。","options":["究竟","一定","已经"],"answer":0,"explanation":"究竟 + 是A还是B."},{"context":"“… rốt cuộc cậu thích đôi nào?”","pre":"这两双鞋，你究竟喜欢","blank":"哪","post":"一双？","options":["哪","那","这"],"answer":0,"explanation":"Câu hỏi phải có đại từ nghi vấn 哪."},{"type":"sort","context":"Sắp xếp: “Rốt cuộc bạn muốn mua gì?”","words":["你","究竟","想","买","什么","呢"],"answer":"你究竟想买什么呢？","explanation":"Chủ ngữ + 究竟 + V + 什么 + 呢."},{"type":"sort","context":"Sắp xếp: “Rốt cuộc ai đi dự thi?”","words":["究竟","谁","去","参加","比赛"],"answer":"究竟谁去参加比赛？","explanation":"Chủ ngữ là 谁 → 究竟 đứng trước 谁."},{"type":"sort","context":"Sắp xếp: “Tôi không biết rốt cuộc tại sao anh ấy không đến.”","words":["我","不知道","他","究竟","为什么","不来"],"answer":"我不知道他究竟为什么不来。","explanation":"Câu hỏi gián tiếp: 不知道 + chủ ngữ + 究竟 + 为什么."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你究竟喜欢这件外套吗？","isCorrect":false,"correctVersion":"你究竟喜欢不喜欢这件外套？","explanation":"究竟 không đi với 吗 → dùng V不V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"究竟是谁告诉你的？","isCorrect":true,"correctVersion":"","explanation":"Đúng: 究竟 + 是 + 谁."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"谁究竟是你的老师？","isCorrect":false,"correctVersion":"究竟谁是你的老师？","explanation":"究竟 đứng trước đại từ nghi vấn làm chủ ngữ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Rốt cuộc bạn muốn mua loại trà nào?","answer":"你究竟想买哪种茶叶？","answerPy":"Nǐ jiūjìng xiǎng mǎi nǎ zhǒng cháyè?","explanation":"究竟 + V + 哪种 + N."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Rốt cuộc ai đã nói với bạn chuyện này?","answer":"究竟是谁告诉你这件事的？","answerPy":"Jiūjìng shì shuí gàosu nǐ zhè jiàn shì de?","explanation":"究竟 + 是 + 谁 + ……的."}]},{"point":"承接复句“首先……，然后/其次……” — trước hết …, sau đó / thứ đến …","items":[{"context":"“… sau đó mới xem chất lượng thế nào.”","pre":"首先看样子喜不喜欢，","blank":"然后","post":"再看质量怎么样。","options":["然后","其次","首先"],"answer":0,"explanation":"Thứ tự thời gian: 首先……，然后再……"},{"context":"“Gặp vấn đề, trước hết nghĩ xem …”","pre":"遇到问题，","blank":"首先","post":"想想问题为什么出现，然后再积极想办法解决。","options":["首先","最后","其次"],"answer":0,"explanation":"Vế đầu dùng 首先."},{"context":"“… sau đó dựa vào bài khóa làm bài tập.”","pre":"请大家首先读一遍课文，","blank":"然后","post":"根据课文完成课后练习。","options":["然后","而且","加上"],"answer":0,"explanation":"首先……，然后……"},{"context":"“… thứ nhất là vì thích, thứ hai là vì gần nhà.”","pre":"我选这份工作，首先是因为喜欢，","blank":"其次","post":"是因为离家近。","options":["其次","然后","首先"],"answer":0,"explanation":"Liệt kê lý do (chính – phụ) → 其次."},{"context":"“… cuối cùng còn phải đọc nhiều viết nhiều.”","pre":"学中文首先要多听，其次要多说，","blank":"最后","post":"还要多读多写。","options":["最后","首先","究竟"],"answer":0,"explanation":"首先……，其次……，最后……"},{"type":"sort","context":"Sắp xếp: “Chúng ta đi siêu thị trước, sau đó đến ngân hàng.”","words":["我们","首先","去超市","，","然后","去","银行"],"answer":"我们首先去超市，然后去银行。","explanation":"首先 + V1，然后 + V2."},{"type":"sort","context":"Sắp xếp: “Mua đồ trước hết xem chất lượng, thứ đến mới xem giá.”","words":["买东西","首先","看质量","，","其次","看价格"],"answer":"买东西首先看质量，其次看价格。","explanation":"首先……，其次…… (chính – phụ)."},{"type":"sort","context":"Sắp xếp: “Mời mọi người đọc bài khóa một lượt trước, sau đó trả lời câu hỏi.”","words":["请大家","首先","读一遍课文","，","然后","回答问题"],"answer":"请大家首先读一遍课文，然后回答问题。","explanation":"首先……，然后……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我每天首先起床，其次刷牙。","isCorrect":false,"correctVersion":"我每天首先起床，然后刷牙。","explanation":"Thứ tự thời gian → 然后, không dùng 其次."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"首先，我要感谢老师；其次，我要感谢我的家人。","isCorrect":true,"correctVersion":"","explanation":"Đúng: liệt kê các ý theo thứ tự, 首先……；其次……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"先，我们来介绍一下自己。","isCorrect":false,"correctVersion":"首先，我们来介绍一下自己。","explanation":"Đứng đầu câu có dấu phẩy phải là 首先."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Trước hết phải xem mình có thật sự cần không, sau đó mới so sánh giá.","answer":"首先要看自己是不是真正需要，然后再比较价格。","answerPy":"Shǒuxiān yào kàn zìjǐ shì bu shì zhēnzhèng xūyào, ránhòu zài bǐjiào jiàgé.","explanation":"首先……，然后再……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi thích căn nhà này: thứ nhất là giao thông thuận tiện, thứ hai là tiền thuê không đắt.","answer":"我喜欢这个房子，首先是交通方便，其次是房租不贵。","answerPy":"Wǒ xǐhuan zhège fángzi, shǒuxiān shì jiāotōng fāngbiàn, qícì shì fángzū bú guì.","explanation":"Liệt kê lý do → 首先……，其次……; ôn 房租 (Bài 2)."}]},{"point":"连词“加上” — thêm vào đó, cộng thêm","items":[{"context":"“… thêm vào đó nhân viên thân thiện …”","pre":"小店虽然小，但东西适合年轻人，","blank":"加上","post":"店员态度友好，使得小店的生意越来越好。","options":["加上","首先","对于"],"answer":0,"explanation":"加上 đưa thêm một lý do cùng chiều."},{"context":"“… nên nhiều người trẻ thuê nhà ở đây.”","pre":"这里交通很方便，加上房租便宜，","blank":"所以","post":"很多年轻人都在这里租房子。","options":["所以","但是","虽然"],"answer":0,"explanation":"Vế sau 加上 nêu kết quả, thường có 所以."},{"context":"“… lại thêm hôm nay là cuối tuần …”","pre":"今天下雨，加上","blank":"又","post":"是周末，路上车特别多。","options":["又","才","都"],"answer":0,"explanation":"加上 + 又 + lý do thêm."},{"context":"“… lại thêm phục vụ tốt …”","pre":"这家店东西便宜，再","blank":"加上","post":"服务好，顾客越来越多。","options":["加上","而且","不光"],"answer":0,"explanation":"再加上 = lại thêm."},{"context":"“… khiến nhiều người muốn mua nhà ở đây.”","pre":"这里环境好，加上交通也方便，","blank":"使得","post":"很多人想在这儿买房子。","options":["使得","但是","虽然"],"answer":0,"explanation":"……，加上……，使得 + kết quả (使得 – từ mới bài khoá 3)."},{"type":"sort","context":"Sắp xếp: “Trà này rất thơm, thêm vào đó đang khuyến mãi, nên tôi mua hai cân.”","words":["这些茶叶","很香","，","加上","在促销","，","我","买了两斤"],"answer":"这些茶叶很香，加上在促销，我买了两斤。","explanation":"Lý do 1，加上 + lý do 2，kết quả."},{"type":"sort","context":"Sắp xếp: “Trời rất lạnh, lại thêm mưa, nên trên phố chẳng có mấy người.”","words":["天气","很冷","，","加上","下雨","，","街上","没什么人"],"answer":"天气很冷，加上下雨，街上没什么人。","explanation":"Hai lý do cùng chiều → một kết quả."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他很聪明，加上一直非常努力。","isCorrect":false,"correctVersion":"他很聪明，加上一直非常努力，所以考上了理想的大学。","explanation":"Thiếu vế kết quả."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这里环境很好，加上交通方便，所以房子很好卖。","isCorrect":true,"correctVersion":"","explanation":"Đúng: hai lý do cùng chiều + kết quả 所以……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这家饭馆的菜很好吃，加上服务员态度很差，所以顾客很多。","isCorrect":false,"correctVersion":"这家饭馆的菜很好吃，加上服务员态度很好，所以顾客很多。","explanation":"Lý do sau 加上 phải cùng chiều với lý do trước."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tiệm này đồ rẻ, thêm vào đó nhân viên rất thân thiện, nên khách rất đông.","answer":"这家店东西便宜，加上店员很友好，所以顾客很多。","answerPy":"Zhè jiā diàn dōngxi piányi, jiāshàng diànyuán hěn yǒuhǎo, suǒyǐ gùkè hěn duō.","explanation":"……，加上……，所以……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Hôm nay tôi dậy muộn, thêm vào đó đường lại tắc, nên đã đến muộn.","answer":"今天我起晚了，加上路上又堵车，所以迟到了。","answerPy":"Jīntiān wǒ qǐwǎn le, jiāshàng lùshang yòu dǔchē, suǒyǐ chídào le.","explanation":"加上 + 又 + lý do thêm; 所以 + kết quả."}]},{"point":"介词“对于” — đối với, về","items":[{"context":"“Đối với những thứ muốn mua …”","pre":"","blank":"对于","post":"想买的东西，她不光看质量，还看价格。","options":["对于","加上","首先"],"answer":0,"explanation":"对于 + đối tượng，chủ ngữ + V."},{"context":"“… mọi người đều rất ủng hộ.” (ôn 支持 – Bài 9)","pre":"对于他的做法，大家都很","blank":"支持","post":"。","options":["支持","友好","仔细"],"answer":0,"explanation":"对于 + việc，ai + 支持."},{"context":"“… chúng tôi nhất định nghiên cứu kỹ.”","pre":"对于你们提的这个建议，我们一定好好","blank":"研究","post":"。","options":["研究","表示","降价"],"answer":0,"explanation":"对于 + 建议，……研究."},{"context":"“Cậu ấy rất lễ phép với thầy cô.”","pre":"他","blank":"对","post":"老师很有礼貌。","options":["对","对于","关于"],"answer":0,"explanation":"Thái độ với NGƯỜI → chỉ dùng 对."},{"context":"“Đối với nhiều bạn trẻ mà nói …”","pre":"对于很多年轻人","blank":"来说","post":"，买盲盒是一件快乐的事。","options":["来说","以后","的话"],"answer":0,"explanation":"对于……来说 = đối với … mà nói."},{"type":"sort","context":"Sắp xếp: “Về vấn đề này, mọi người có ý kiến gì?”","words":["对于","这个问题","，","大家","有","什么","看法"],"answer":"对于这个问题，大家有什么看法？","explanation":"对于 + N，chủ ngữ + V."},{"type":"sort","context":"Sắp xếp: “Đối với ý kiến của khách hàng, chúng tôi nhất định nghiên cứu kỹ.”","words":["对于","顾客的意见","，","我们","一定","好好研究"],"answer":"对于顾客的意见，我们一定好好研究。","explanation":"Cụm 对于 đứng đầu câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她对于孩子很耐心。","isCorrect":false,"correctVersion":"她对孩子很耐心。","explanation":"Thái độ với người → 对."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"对于这件事，我还没想好。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 对于 + việc，chủ ngữ + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"对于买东西很仔细。","isCorrect":false,"correctVersion":"对于买东西，她很仔细。","explanation":"Thiếu chủ ngữ; cụm 对于 không làm chủ ngữ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Về vấn đề này, mọi người có ý kiến gì?","answer":"对于这个问题，大家有什么看法？","answerPy":"Duìyú zhège wèntí, dàjiā yǒu shénme kànfǎ?","explanation":"对于 + N đứng đầu câu."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đối với những thứ muốn mua, tôi đều so sánh kỹ rồi mới mua.","answer":"对于想买的东西，我都仔细比较后才买。","answerPy":"Duìyú xiǎng mǎi de dōngxi, wǒ dōu zǐxì bǐjiào hòu cái mǎi.","explanation":"对于……，chủ ngữ + 都 + 仔细比较后才……"}]}],"/lessons/hsk4v3-bai-15.html":[{"point":"固定格式“再也不/没……” — không bao giờ … nữa / từ đó không … nữa","items":[{"context":"“Từ sau thi giữa kỳ là không gặp lại cậu nữa.” (quá khứ → nay)","pre":"期中考试后就再也","blank":"没","post":"见过你了。","options":["没","不","别"],"answer":0,"explanation":"Có 过, kể việc đã qua → 再也没."},{"context":"“Từ nay em sẽ không bao giờ đến muộn nữa.” (lời hứa)","pre":"对不起，我以后再也","blank":"不","post":"迟到了。","options":["不","没","还"],"answer":0,"explanation":"以后 + lời hứa → 再也不."},{"context":"“Từ khi ra nước ngoài, tôi không gọi cho anh ấy nữa.”","pre":"我出国以后就","blank":"再也","post":"没给他打过电话。","options":["再也","也再","还是"],"answer":0,"explanation":"Thứ tự: 再也 + 没."},{"context":"“Từ hôm đó, cô ấy không nhắn tin cho tôi nữa.” (ôn từ mới)","pre":"从那天以后，她就再也没给我发过","blank":"短信","post":"。","options":["短信","细节","答案"],"answer":0,"explanation":"发短信 = gửi tin nhắn."},{"context":"“Mẹ yên tâm, con sẽ không bao giờ nằm trên giường xem điện thoại nữa.”","pre":"妈妈，你放心，我","blank":"再也","post":"不躺在床上看手机了。","options":["再也","再也没","也再"],"answer":0,"explanation":"再也 + 不 → lời hứa."},{"type":"sort","context":"Sắp xếp: “Từ nay tôi sẽ không bao giờ đến muộn nữa.”","words":["我","以后","再也","不","迟到了"],"answer":"我以后再也不迟到了。","explanation":"以后 + 再也不 + V + 了."},{"type":"sort","context":"Sắp xếp: “Từ khi tốt nghiệp, chúng tôi không gặp lại nhau nữa.”","words":["毕业以后","，","我们","就","再也没","见过面"],"answer":"毕业以后，我们就再也没见过面。","explanation":"Mốc thời gian + 就 + 再也没 + V过."},{"type":"sort","context":"Sắp xếp: “Từ khi chuyển nhà, anh ấy không đến công viên đó nữa.”","words":["搬家以后","，","他","再也没","去过","那个公园"],"answer":"搬家以后，他再也没去过那个公园。","explanation":"再也没 + V过 + O."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我保证，以后再也没熬夜了。","isCorrect":false,"correctVersion":"我保证，以后再也不熬夜了。","explanation":"Lời hứa về tương lai → 再也不."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"出国以后，我就再也没给他打过电话。","isCorrect":true,"correctVersion":"","explanation":"Đúng: kể việc từ quá khứ đến nay → 再也没……过."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你放心，我不再也玩游戏了。","isCorrect":false,"correctVersion":"你放心，我再也不玩游戏了。","explanation":"Thứ tự đúng: 再也 + 不."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Từ khi tốt nghiệp, tôi không gặp lại cô ấy nữa.","answer":"毕业以后，我就再也没见过她。","answerPy":"Bìyè yǐhòu, wǒ jiù zài yě méi jiàn guò tā.","explanation":"Quá khứ → nay: 再也没 + V过."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Xin lỗi, từ nay em sẽ không bao giờ đến muộn nữa.","answer":"对不起，我以后再也不迟到了。","answerPy":"Duìbuqǐ, wǒ yǐhòu zài yě bù chídào le.","explanation":"Lời hứa: 以后再也不……了."}]},{"point":"介词“由” — do (ai) làm, do (ai) phụ trách","items":[{"context":"“Hôm đó do người phụ trách bộ phận phỏng vấn.”","pre":"那天是","blank":"由","post":"部门负责人来面试的。","options":["由","由于","被"],"answer":0,"explanation":"由 + người + 来 + V."},{"context":"“Vấn đề này rốt cuộc do ai phụ trách giải quyết?”","pre":"这个问题究竟由谁来","blank":"负责","post":"解决？","options":["负责","负责人","部门"],"answer":0,"explanation":"负责 là động từ; 负责人 là danh từ."},{"context":"“Hoạt động lần này do công ty họ sắp xếp.”","pre":"这次活动是由他们公司来安排","blank":"的","post":"。","options":["的","了","着"],"answer":0,"explanation":"Khung 是由……的."},{"context":"“Do thời tiết xấu, trận đấu bị hoãn.” (phân biệt với 由)","pre":"","blank":"由于","post":"天气不好，比赛推迟了。","options":["由于","由","被"],"answer":0,"explanation":"Nguyên nhân → 由于 (Bài 2); người làm → 由."},{"context":"“Việc này để tôi phụ trách nhé.”","pre":"这件事由我","blank":"来","post":"负责吧。","options":["来","去","在"],"answer":0,"explanation":"由 + người + 来 + V."},{"type":"sort","context":"Sắp xếp: “Hoạt động lần này do trường tổ chức.”","words":["这次活动","由","学校","来","举办"],"answer":"这次活动由学校来举办。","explanation":"Sự việc + 由 + đơn vị + 来 + V."},{"type":"sort","context":"Sắp xếp: “Phỏng vấn là do người phụ trách bộ phận làm.”","words":["面试","是","由","部门负责人","来","做","的"],"answer":"面试是由部门负责人来做的。","explanation":"是由……来……的."},{"type":"sort","context":"Sắp xếp: “Bữa tối hôm nay để tôi nấu nhé.”","words":["今天的","晚饭","由","我","来","做","吧"],"answer":"今天的晚饭由我来做吧。","explanation":"由 + 我 + 来 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个工作是由小王一个人完成的。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 是由 + người + V + 的."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"由于你来负责这件事吧。","isCorrect":false,"correctVersion":"由你来负责这件事吧。","explanation":"Chỉ người phụ trách → 由, không phải 由于."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这期交流活动是由学生会举办。","isCorrect":false,"correctVersion":"这期交流活动是由学生会举办的。","explanation":"Khung 是由…… cần 的 ở cuối."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bữa tối hôm nay do tôi nấu.","answer":"今天的晚饭由我来做。","answerPy":"Jīntiān de wǎnfàn yóu wǒ lái zuò.","explanation":"由 + người + (来) + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Hoạt động lần này do nhà trường tổ chức.","answer":"这次活动是由学校举办的。","answerPy":"Zhè cì huódòng shì yóu xuéxiào jǔbàn de.","explanation":"(是)由……(来)举办(的)."}]},{"point":"“把”字句“主语+把+宾语+动词（+一/了）+动词” — làm (qua / thử) một chút","items":[{"context":"“Cậu ấy ra tiệm sửa lại tóc một chút.”","pre":"他去理发店把头发","blank":"理","post":"了理。","options":["理","剪","洗"],"answer":0,"explanation":"V了V: 理了理 — hai động từ phải giống nhau."},{"context":"“Em kiểm tra bài tập một lượt trước …”","pre":"你先把作业","blank":"检查检查","post":"，然后再交给老师。","options":["检查检查","检查一检查","检查"],"answer":0,"explanation":"Động từ hai âm tiết: ABAB; ✗ 检查一检查; 把 + O không thể chỉ có 检查."},{"context":"“Trước giờ học, tôi đã xem qua nội dung hôm nay.” (việc đã làm)","pre":"上课前，我把今天要学习的内容看","blank":"了","post":"看。","options":["了","着","过"],"answer":0,"explanation":"Việc đã làm → V了V."},{"context":"“Trước phỏng vấn, anh ấy định tập phần tự giới thiệu một chút.” (dự định)","pre":"面试前，他打算在镜子前把自我介绍练","blank":"一","post":"练。","options":["一","了","过"],"answer":0,"explanation":"打算 → việc chưa làm → V一V."},{"context":"“Bạn nghĩ kỹ việc này rồi hãy nói cho tôi.”","pre":"你","blank":"把","post":"这件事好好想想，再告诉我吧。","options":["把","被","给"],"answer":0,"explanation":"把 + O + VV."},{"type":"sort","context":"Sắp xếp: “Bạn giặt quần áo một chút đi.”","words":["你","把","衣服","洗","一","洗","吧"],"answer":"你把衣服洗一洗吧。","explanation":"Đề nghị: 把 + O + V一V + 吧."},{"type":"sort","context":"Sắp xếp: “Tôi đi dọn phòng một chút.”","words":["我","去","把","房间","打扫打扫"],"answer":"我去把房间打扫打扫。","explanation":"Hai âm tiết: ABAB."},{"type":"sort","context":"Sắp xếp: “Cô ấy nghĩ một chút về lời thầy nói rồi gật đầu.”","words":["她","把","老师的话","想了想","，","点了点头"],"answer":"她把老师的话想了想，点了点头。","explanation":"Việc đã làm: 把 + O + V了V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你先把课文复习一复习。","isCorrect":false,"correctVersion":"你先把课文复习复习。","explanation":"Động từ hai âm tiết lặp ABAB, không chen 一."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他把头发理了理，又买了一身新衣服。","isCorrect":true,"correctVersion":"","explanation":"Đúng: việc đã làm → V了V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把这本书看。","isCorrect":false,"correctVersion":"我把这本书看了看。","explanation":"Động từ sau 把 không được đứng một mình (có thể sửa: 看了看 / 看一看 / 看完了)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Em sửa bài văn này một chút rồi hãy nộp cho thầy.","answer":"你把这篇作文改一改，再交给老师。","answerPy":"Nǐ bǎ zhè piān zuòwén gǎi yi gǎi, zài jiāogěi lǎoshī.","explanation":"Đề nghị → 把 + O + V一V / VV."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Anh ấy xem qua tin nhắn một chút rồi cười.","answer":"他把短信看了看，笑了。","answerPy":"Tā bǎ duǎnxìn kàn le kàn, xiào le.","explanation":"Việc đã làm → V了V; ôn từ mới 短信."}]},{"point":"比较句“A不如B（+形容词）” — A không bằng B","items":[{"context":"“Học trên sách không bằng tự làm một lần.”","pre":"有些事情，在课本上学","blank":"不如","post":"自己做一遍。","options":["不如","比","没"],"answer":0,"explanation":"A不如B."},{"context":"“Cửa hàng này môi trường không tốt bằng cửa hàng kia.”","pre":"这家店不如那家店环境","blank":"好","post":"。","options":["好","很好","好多了"],"answer":0,"explanation":"不如 + B + Adj (không thêm 很 / 多了)."},{"context":"“… không tiện bằng đi tàu điện ngầm.”","pre":"坐公交要换两次车，我觉得坐公交不如坐地铁","blank":"方便","post":"。","options":["方便","不方便","更方便"],"answer":0,"explanation":"Tính từ tích cực, không thêm 更 / 不."},{"context":"“Mùa đông năm nay không lạnh bằng năm ngoái.”","pre":"今年冬天","blank":"不如","post":"去年冷。","options":["不如","比","跟"],"answer":0,"explanation":"A不如B + Adj."},{"context":"“… vừa an toàn vừa vui.” (ôn Bài 4)","pre":"一个人去不如跟大家一起去，","blank":"既","post":"安全又开心。","options":["既","又","也"],"answer":0,"explanation":"既……又……"},{"type":"sort","context":"Sắp xếp: “Cửa hàng này môi trường không tốt bằng cửa hàng kia.”","words":["这家店","不如","那家店","环境","好"],"answer":"这家店不如那家店环境好。","explanation":"A + 不如 + B + (mặt so sánh) + Adj."},{"type":"sort","context":"Sắp xếp: “Tôi thấy đi xe buýt không tiện bằng tàu điện ngầm.”","words":["我","觉得","坐公交","不如","坐地铁","方便"],"answer":"我觉得坐公交不如坐地铁方便。","explanation":"A, B là hành động."},{"type":"sort","context":"Sắp xếp: “Đọc sách ở nhà chẳng bằng lên thư viện đọc.”","words":["在家","看书","不如","去图书馆","看"],"answer":"在家看书不如去图书馆看。","explanation":"A不如B (không có tính từ)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我唱歌不如她唱得好。","isCorrect":true,"correctVersion":"","explanation":"Đúng: A不如B + V得 + Adj."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服不如那件很漂亮。","isCorrect":false,"correctVersion":"这件衣服不如那件漂亮。","explanation":"Không thêm 很 trước tính từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"坐出租车不如便宜坐地铁。","isCorrect":false,"correctVersion":"坐出租车不如坐地铁便宜。","explanation":"Tính từ đặt sau B."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tiếng Trung của tôi không tốt bằng chị tôi.","answer":"我的中文不如我姐姐好。","answerPy":"Wǒ de Zhōngwén bùrú wǒ jiějie hǎo.","explanation":"A不如B + Adj."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Mua ở cửa hàng không rẻ bằng mua trên mạng.","answer":"在商店买不如在网上买便宜。","answerPy":"Zài shāngdiàn mǎi bùrú zài wǎngshang mǎi piányi.","explanation":"A, B là hành động; tính từ cuối câu."}]}],"/lessons/hsk4v3-bai-16.html":[{"point":"“把”字句“主语+把+宾语+动词+了” — xử lý xong một người / vật xác định","items":[{"context":"“Tôi đã hủy vé máy bay và khách sạn rồi.”","pre":"我已经","blank":"把","post":"机票和酒店取消了。","options":["把","被","给"],"answer":0,"explanation":"Chủ ngữ + 已经 + 把 + O + V + 了."},{"context":"“Bạn tắt đèn đi, tôi muốn ngủ rồi.”","pre":"你把灯","blank":"关","post":"了吧，我想睡觉了。","options":["关","放","看"],"answer":0,"explanation":"把灯关了 = tắt đèn đi."},{"context":"“Đừng quên giặt quần áo nhé, mai còn phải mặc.”","pre":"你别忘了把衣服洗","blank":"了","post":"，明天还得穿呢。","options":["了","过","着"],"answer":0,"explanation":"把 + O + V + 了: việc phải làm xong."},{"context":"“Mau uống thuốc đi, như vậy bạn mới mau khỏi.”","pre":"快把药","blank":"吃","post":"了，这样你才能快点儿好。","options":["吃","做","打"],"answer":0,"explanation":"Tiếng Trung nói 吃药 (✗ 喝药)."},{"context":"“… nếu không nước sẽ vào phòng.” (ôn 否则 – Bài 8)","pre":"下雨了，快把窗户关了，","blank":"否则","post":"房间里会进水的。","options":["否则","于是","并且"],"answer":0,"explanation":"……，否则…… = nếu không thì …"},{"type":"sort","context":"Sắp xếp: “Tôi đã hủy vé máy bay và khách sạn rồi.”","words":["我","已经","把","机票和酒店","取消","了"],"answer":"我已经把机票和酒店取消了。","explanation":"已经 đứng trước 把."},{"type":"sort","context":"Sắp xếp: “Bạn tắt đèn đi.”","words":["你","把","灯","关","了","吧"],"answer":"你把灯关了吧。","explanation":"Câu đề nghị: 把 + O + V + 了 + 吧."},{"type":"sort","context":"Sắp xếp: “Đừng quên trả sách đã mượn nhé.”","words":["别忘了","把","借的书","还","了"],"answer":"别忘了把借的书还了。","explanation":"别忘了 + 把 + O + V + 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你快把这些水果吃了吧，放久了就不新鲜了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 这些水果 xác định, V + 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把一杯咖啡喝了。","isCorrect":false,"correctVersion":"我把那杯咖啡喝了。","explanation":"Tân ngữ của 把 phải xác định."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把机票没取消。","isCorrect":false,"correctVersion":"我没把机票取消。","explanation":"没 đặt trước 把."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi đã hủy vé máy bay và khách sạn rồi.","answer":"我已经把机票和酒店取消了。","answerPy":"Wǒ yǐjīng bǎ jīpiào hé jiǔdiàn qǔxiāo le.","explanation":"已经 + 把 + O + 取消了."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Kế hoạch thay đổi rồi, bạn hủy khách sạn đã đặt đi.","answer":"计划变了，你把订好的酒店取消了吧。","answerPy":"Jìhuà biàn le, nǐ bǎ dìnghǎo de jiǔdiàn qǔxiāo le ba.","explanation":"Câu đề nghị 把……取消了吧."}]},{"point":"递进复句“……，并且……” — …, hơn nữa / đồng thời …","items":[{"context":"“… đồng thời thử thêm một vài ví dụ.”","pre":"再检查一下有没有细节上的错误，","blank":"并且","post":"试着增加一些例子。","options":["并且","但是","所以"],"answer":0,"explanation":"Vế sau là hành động bổ sung → 并且."},{"context":"“… đồng thời lối sống cũng đã thay đổi rất lớn.”","pre":"人们的生活水平提高了，并且生活方式也发生了很大的","blank":"变化","post":"。","options":["变化","例子","错误"],"answer":0,"explanation":"发生变化 = xảy ra thay đổi."},{"context":"“Anh ấy hoàn thành nhiệm vụ đúng hạn, hơn nữa làm rất tốt.”","pre":"他按时完成了任务，","blank":"并且","post":"做得很好。","options":["并且","和","跟"],"answer":0,"explanation":"和 / 跟 nối danh từ; nối hai vế dùng 并且."},{"context":"“Thời gian họp đổi rồi, hơn nữa còn thêm một số nội dung mới.”","pre":"会议时间改了，并且还","blank":"增加","post":"了一些新的内容。","options":["增加","推迟","取消"],"answer":0,"explanation":"增加 + 内容."},{"context":"“Đã quyết định rồi thì viết kế hoạch chi tiết một chút, và làm nghiêm túc theo kế hoạch.” (ôn 既然 – Bài 7)","pre":"","blank":"既然","post":"你已经决定了，就把计划写得详细一些，并且严格按照计划去做。","options":["既然","即使","虽然"],"answer":0,"explanation":"既然……，就…… (Bài 7 · điểm 2)."},{"type":"sort","context":"Sắp xếp: “Anh ấy hoàn thành nhiệm vụ đúng hạn, hơn nữa làm rất tốt.”","words":["他","按时","完成了任务","，","并且","做得很好"],"answer":"他按时完成了任务，并且做得很好。","explanation":"并且 đứng đầu vế sau."},{"type":"sort","context":"Sắp xếp: “Mức sống được nâng cao, đồng thời lối sống cũng thay đổi rất lớn.”","words":["人们的生活水平","提高了","，","并且","生活方式","也发生了很大的变化"],"answer":"人们的生活水平提高了，并且生活方式也发生了很大的变化。","explanation":"Vế sau có chủ ngữ mới → 并且 + chủ ngữ + 也……"},{"type":"sort","context":"Sắp xếp: “Bạn kiểm tra lại tài liệu, đồng thời thử thêm một vài ví dụ.”","words":["你","再检查一下","材料","，","并且","试着","增加一些例子"],"answer":"你再检查一下材料，并且试着增加一些例子。","explanation":"Hai hành động nối tiếp: V1……，并且 + V2……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"小王工作很认真，并且对人很热情。","isCorrect":true,"correctVersion":"","explanation":"Đúng: hai ưu điểm, vế sau bổ sung."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我买了苹果并且香蕉。","isCorrect":false,"correctVersion":"我买了苹果和香蕉。","explanation":"Nối hai danh từ dùng 和."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他按时完成了任务，做得并且很好。","isCorrect":false,"correctVersion":"他按时完成了任务，并且做得很好。","explanation":"并且 đứng đầu vế sau."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Anh ấy đã hoàn thành nhiệm vụ đúng hạn, hơn nữa làm rất tốt.","answer":"他按时完成了任务，并且做得很好。","answerPy":"Tā ànshí wánchéng le rènwu, bìngqiě zuò de hěn hǎo.","explanation":"……，并且 + V得……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi đã điều chỉnh kế hoạch, đồng thời thêm vài ví dụ vào tài liệu.","answer":"我调整了计划，并且在材料里增加了一些例子。","answerPy":"Wǒ tiáozhěng le jìhuà, bìngqiě zài cáiliào lǐ zēngjiā le yìxiē lìzi.","explanation":"V1 + 了……，并且 + V2 + 了…… + từ mới 调整, 增加, 例子."}]},{"point":"固定短语“说不定” — không chừng, biết đâu, có khi","items":[{"context":"“Không lập kế hoạch, không chừng cũng sẽ mang lại phát hiện mới.”","pre":"不做计划，","blank":"说不定","post":"也会带来新的发现。","options":["说不定","一定","不得不"],"answer":0,"explanation":"Phỏng đoán khả năng → 说不定."},{"context":"“Hôm nay âm u thế này, không chừng sẽ mưa.”","pre":"今天这么阴，说不定会","blank":"下雨","post":"。","options":["下雨","出太阳","轻松"],"answer":0,"explanation":"阴 (âm u) → có thể mưa."},{"context":"“Thử lại lần nữa, biết đâu lại thành công.”","pre":"你再试一次，说不定","blank":"就","post":"成功了。","options":["就","才","却"],"answer":0,"explanation":"说不定就……了: biết đâu lại … ngay."},{"context":"“Cuộc họp mai có họp hay không còn chưa chắc, có thể sẽ hoãn.”","pre":"明天的会议开不开","blank":"还","post":"说不定，可能会推迟。","options":["还","就","却"],"answer":0,"explanation":"……还说不定 = còn chưa chắc."},{"context":"“Đã thích thế thì mua đi, biết đâu sau này không mua được nữa.” (ôn 既然 – Bài 7)","pre":"","blank":"既然","post":"你这么喜欢，那就买吧，说不定以后就买不到了。","options":["既然","即使","虽然"],"answer":0,"explanation":"既然……，就…… (Bài 7 · điểm 2)."},{"type":"sort","context":"Sắp xếp: “Hôm nay âm u thế này, không chừng sẽ mưa.”","words":["今天","这么阴","，","说不定","会","下雨"],"answer":"今天这么阴，说不定会下雨。","explanation":"说不定 + 会 + V."},{"type":"sort","context":"Sắp xếp: “Bạn thử lại lần nữa, biết đâu lại thành công.”","words":["你","再试一次","，","说不定","就","成功了"],"answer":"你再试一次，说不定就成功了。","explanation":"说不定 + 就 + V + 了."},{"type":"sort","context":"Sắp xếp: “Có khi anh ấy đã đến sân bay rồi.”","words":["他","说不定","已经","到","机场了"],"answer":"他说不定已经到机场了。","explanation":"说不定 đứng trước hoặc sau chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他今天没来，说不定有事。","isCorrect":true,"correctVersion":"","explanation":"Đúng: phỏng đoán nguyên nhân."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"今天这么阴，一定说不定会下雨。","isCorrect":false,"correctVersion":"今天这么阴，说不定会下雨。","explanation":"Bỏ 一定 — mâu thuẫn với 说不定."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我明天去不去还说不定。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 说不定 làm vị ngữ = còn chưa chắc."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đừng thất vọng, lần sau không chừng bạn sẽ làm tốt hơn.","answer":"别失望，下次你说不定会做得更好。","answerPy":"Bié shīwàng, xià cì nǐ shuōbudìng huì zuò de gèng hǎo.","explanation":"说不定 + 会 + V + từ mới 失望."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bạn thử đi hỏi thầy giáo xem, biết đâu thầy sẽ đồng ý.","answer":"你去问问老师吧，说不定他会同意。","answerPy":"Nǐ qù wènwen lǎoshī ba, shuōbudìng tā huì tóngyì.","explanation":"V V (thử) + 说不定……"}]},{"point":"关联副词“却” — lại, nhưng lại (chuyển ý, trái với mong đợi)","items":[{"context":"“Bạn đã chuẩn bị xong mọi thứ, nhưng lại đột nhiên xuất hiện tình huống mới.”","pre":"你准备好了一切，","blank":"却","post":"突然出现了新情况。","options":["却","就","才"],"answer":0,"explanation":"Vế sau trái với mong đợi → 却."},{"context":"“Anh ấy qua vòng phỏng vấn nhưng lại chẳng phấn khích chút nào.”","pre":"他通过了面试，却一点儿也不","blank":"激动","post":"。","options":["激动","可惜","详细"],"answer":0,"explanation":"一点儿也不 + Adj."},{"context":"“… nhưng tính cách lại hoàn toàn khác.”","pre":"她长得很像她姐姐，性格","blank":"却","post":"完全不同。","options":["却","并且","也"],"answer":0,"explanation":"却 đứng sau chủ ngữ 性格."},{"context":"“Anh ấy nói hôm nay nhất định đến, cuối cùng lại không đến, thật khiến người ta thất vọng.”","pre":"他说今天一定来，","blank":"最后","post":"却没来，真让人失望。","options":["最后","本来","等到"],"answer":0,"explanation":"最后却…… = cuối cùng lại …"},{"context":"“Mặc dù ngày nào cũng cố gắng, thành tích lại không tiến bộ.” (ôn 尽管 – Bài 9)","pre":"","blank":"尽管","post":"他每天都很努力，成绩却一直没有提高。","options":["尽管","既然","只要"],"answer":0,"explanation":"尽管……，却…… (nhượng bộ – chuyển ý)."},{"type":"sort","context":"Sắp xếp: “Anh ấy qua vòng phỏng vấn nhưng lại chẳng phấn khích chút nào.”","words":["他","通过了面试","，","却","一点儿也","不激动"],"answer":"他通过了面试，却一点儿也不激动。","explanation":"Cùng chủ ngữ → vế sau bỏ chủ ngữ, 却 + V."},{"type":"sort","context":"Sắp xếp: “Cô ấy trông rất giống chị gái, tính cách lại hoàn toàn khác.”","words":["她","长得很像她姐姐","，","性格","却","完全不同"],"answer":"她长得很像她姐姐，性格却完全不同。","explanation":"Chủ ngữ 2 + 却 + vị ngữ."},{"type":"sort","context":"Sắp xếp: “Mọi người đều đến rồi, anh ấy lại vẫn chưa đến.”","words":["大家","都","到了","，","他","却","还没来"],"answer":"大家都到了，他却还没来。","explanation":"他却…… — 却 sau chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们都很着急，他却一点儿也不着急。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 却 sau chủ ngữ 他, vế sau ngược với vế trước."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他学习很努力，却考得很好。","isCorrect":false,"correctVersion":"他学习很努力，所以考得很好。","explanation":"Kết quả hợp lý, không trái mong đợi → không dùng 却."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他通过了面试，却他一点儿也不激动。","isCorrect":false,"correctVersion":"他通过了面试，他却一点儿也不激动。","explanation":"却 đứng sau chủ ngữ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đã hẹn gặp bạn rồi, nhưng trời lại đột nhiên đổ mưa.","answer":"约好见朋友了，却突然下起了大雨。","answerPy":"Yuēhǎo jiàn péngyou le, què tūrán xiàqǐ le dàyǔ.","explanation":"约好…… + 却 + 突然……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi học tiếng Trung ba năm rồi, nhưng lại chưa từng đến Trung Quốc.","answer":"我学了三年中文，却从来没去过中国。","answerPy":"Wǒ xué le sān nián Zhōngwén, què cónglái méi qù guò Zhōngguó.","explanation":"却 + ôn 从来没 + V过 (Bài 9 · điểm 4)."}]}],"/lessons/hsk4v3-bai-17.html":[{"point":"固定格式“你×你的吧” — anh / chị cứ (làm việc) của mình đi","items":[{"context":"“… nhưng chị cứ về trước đi …” — đại từ phải giống chữ đầu","pre":"谢谢一雪姐，不过您走","blank":"您","post":"的吧，我一会儿还要去健身房。","options":["您","你","我"],"answer":0,"explanation":"您走您的吧: hai đại từ giống nhau."},{"context":"“Anh cứ làm việc của anh đi, em tự làm xong được.”","pre":"你","blank":"忙","post":"你的吧，我自己就能完成。","options":["忙","帮","等"],"answer":0,"explanation":"你忙你的吧 = anh cứ bận việc của anh."},{"context":"“Các cậu cứ đi chơi đi, hôm nay mình muốn ở nhà nghỉ.”","pre":"你们玩你们","blank":"的吧","post":"，我今天想在家休息。","options":["的吧","吧的","了吧"],"answer":0,"explanation":"Khuôn: 你们 + V + 你们 + 的吧."},{"context":"“Lát nữa em còn phải đến phòng gym một chuyến …”","pre":"我一会儿还要去一","blank":"趟","post":"健身房，您先走吧。","options":["趟","张","家"],"answer":0,"explanation":"去一趟 + nơi: đi một chuyến."},{"context":"“Anh cứ ăn đi, hôm nay em phải tăng ca, về rất muộn.”","pre":"你吃你的吧，我今天要加班，回来得很","blank":"晚","post":"。","options":["晚","早","快"],"answer":0,"explanation":"Lý do từ chối: về muộn → 回来得很晚."},{"type":"sort","context":"Sắp xếp: “Chị cứ về trước đi, em còn phải đến phòng gym một chuyến.”","words":["您","走","您的吧","，","我","还要去","一趟健身房"],"answer":"您走您的吧，我还要去一趟健身房。","explanation":"您 + V + 您的吧，+ lý do."},{"type":"sort","context":"Sắp xếp: “Anh cứ xem của anh đi, em đi nghe điện thoại một chút.”","words":["你","看","你的吧","，","我","去","接个电话"],"answer":"你看你的吧，我去接个电话。","explanation":"你×你的吧 + việc của mình."},{"type":"sort","context":"Sắp xếp: “Các bạn cứ nói chuyện đi, mình hơi mệt rồi.”","words":["你们","聊","你们的吧","，","我","有点儿累了"],"answer":"你们聊你们的吧，我有点儿累了。","explanation":"你们……你们的吧."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你忙你的吧，我自己就能完成。","isCorrect":true,"correctVersion":"","explanation":"Đúng: từ chối khéo ý giúp đỡ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"您走你的吧，我还要去健身房。","isCorrect":false,"correctVersion":"您走您的吧，我还要去健身房。","explanation":"Hai đại từ phải thống nhất."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你玩你吧，我想在家休息。","isCorrect":false,"correctVersion":"你玩你的吧，我想在家休息。","explanation":"Thiếu 的."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chị cứ về trước đi, lát nữa em còn phải đến phòng gym một chuyến.","answer":"您走您的吧，我一会儿还要去一趟健身房。","answerPy":"Nín zǒu nín de ba, wǒ yíhuìr hái yào qù yí tàng jiànshēnfáng.","explanation":"你×你的吧 + từ mới 趟, 健身房."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Các cậu cứ chơi đi, mình phải ở nhà ôn bài.","answer":"你们玩你们的吧，我得在家复习。","answerPy":"Nǐmen wán nǐmen de ba, wǒ děi zài jiā fùxí.","explanation":"你们……你们的吧，+ lý do."}]},{"point":"固定短语“一A一B” — một … một … (hai mặt đối xứng)","items":[{"context":"“… cả đi lẫn về mất nửa tiếng.”","pre":"离我家最近的健身房也要坐两站公交车，一","blank":"来","post":"一回得半个小时。","options":["来","到","回"],"answer":0,"explanation":"一来一回 = cả đi lẫn về."},{"context":"“… nhưng từng chữ từng câu đều rất rõ.”","pre":"她说话的声音不大，但是一字一","blank":"句","post":"说得很清楚。","options":["句","话","声"],"answer":0,"explanation":"一字一句: A, B cùng loại, đơn âm tiết."},{"context":"“Phóng viên và vận động viên một hỏi một đáp …”","pre":"记者和运动员一问一","blank":"答","post":"，谈到了很多比赛中的事情。","options":["答","说","问"],"answer":0,"explanation":"问 ↔ 答: hai mặt đối xứng."},{"context":"“Hai phòng này một to một nhỏ …”","pre":"这两个房间一大一","blank":"小","post":"，你们两个人住大的，我自己住小的。","options":["小","多","少"],"answer":0,"explanation":"大 ↔ 小."},{"context":"“… sao ống trái ống phải một dài một ngắn?”","pre":"您看这条裤子，怎么左腿和右腿一","blank":"长","post":"一短？","options":["长","高","大"],"answer":0,"explanation":"长 ↔ 短; 一 trước 长 đọc yì."},{"type":"sort","context":"Sắp xếp: “Cả đi lẫn về mất nửa tiếng, phí thời gian quá.”","words":["一来一回","得","半个小时","，","太浪费","时间了"],"answer":"一来一回得半个小时，太浪费时间了。","explanation":"一来一回 làm chủ ngữ; 得 (děi) = phải mất."},{"type":"sort","context":"Sắp xếp: “Thầy đọc từng chữ từng câu, mọi người đều nghe rõ.”","words":["老师","一字一句地","读","，","大家","都","听清楚了"],"answer":"老师一字一句地读，大家都听清楚了。","explanation":"一字一句 + 地 + V: làm trạng ngữ."},{"type":"sort","context":"Sắp xếp: “Hai đứa trẻ một béo một gầy, đều rất thích chơi bóng bàn.”","words":["两个孩子","一胖一瘦","，","都","很喜欢","打乒乓球"],"answer":"两个孩子一胖一瘦，都很喜欢打乒乓球。","explanation":"一胖一瘦 làm vị ngữ (胖 ↔ 瘦)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这两个房间一大一小。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 一A一B làm vị ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"记者和运动员一问一回答。","isCorrect":false,"correctVersion":"记者和运动员一问一答。","explanation":"A, B phải đơn âm tiết, đối xứng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"从家到公司一来回要一个多小时。","isCorrect":false,"correctVersion":"从家到公司一来一回要一个多小时。","explanation":"Đủ hai chữ 一."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Hai đứa con nhà chị ấy một béo một gầy.","answer":"她家的两个孩子一胖一瘦。","answerPy":"Tā jiā de liǎng gè háizi yí pàng yí shòu.","explanation":"一胖一瘦 làm vị ngữ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Từ nhà đến công ty cả đi lẫn về mất một tiếng.","answer":"从家到公司一来一回要一个小时。","answerPy":"Cóng jiā dào gōngsī yì lái yì huí yào yí gè xiǎoshí.","explanation":"一来一回 + 得 / 要 + thời gian."}]},{"point":"兼语句“主语+表扬/批评+宾语1+动词+宾语2” — khen / phê bình ai (đã) làm gì","items":[{"context":"“Huấn luyện viên cũng khen anh ấy đã tiến bộ rất lớn.”","pre":"教练也","blank":"表扬","post":"他取得了很大的进步。","options":["表扬","批评","羡慕"],"answer":0,"explanation":"Tiến bộ → khen: 表扬 + ai + V."},{"context":"“Giám đốc phê bình anh ấy không hoàn thành đúng hạn.”","pre":"经理","blank":"批评","post":"他没有按时完成工作。","options":["批评","表扬","鼓励"],"answer":0,"explanation":"Việc chưa tốt → 批评."},{"context":"“… khen Bạch Gia Nguyệt kiên trì học tiếng Trung mỗi ngày.”","pre":"老师表扬白家月","blank":"坚持","post":"每天学习中文。","options":["坚持","受伤","路过"],"answer":0,"explanation":"坚持 + V."},{"context":"“HLV khen anh ấy làm động tác rất chuẩn.”","pre":"教练表扬他把动作做得很","blank":"准确","post":"。","options":["准确","全身","设备"],"answer":0,"explanation":"V得 + 准确."},{"context":"“Mẹ lúc nào cũng trách tôi không dọn phòng.”","pre":"妈妈总是批评我不收拾","blank":"房间","post":"。","options":["房间","操场","会员"],"answer":0,"explanation":"收拾房间 = dọn phòng."},{"type":"sort","context":"Sắp xếp: “Huấn luyện viên khen anh ấy đã có tiến bộ rất lớn.”","words":["教练","表扬","他","取得了","很大的进步"],"answer":"教练表扬他取得了很大的进步。","explanation":"S + 表扬 + O1 + V + O2."},{"type":"sort","context":"Sắp xếp: “Giám đốc phê bình anh ấy không hoàn thành công việc đúng hạn.”","words":["经理","批评","他","没有","按时完成工作"],"answer":"经理批评他没有按时完成工作。","explanation":"Phủ định nằm trong phần lý do."},{"type":"sort","context":"Sắp xếp: “Cô giáo khen chúng tôi dọn lớp rất sạch.”","words":["老师","表扬","我们","把教室","打扫得","很干净"],"answer":"老师表扬我们把教室打扫得很干净。","explanation":"Phần lý do có thể là câu 把."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"老师表扬白家月坚持每天学习中文。","isCorrect":true,"correctVersion":"","explanation":"Đúng: câu kiêm ngữ với 表扬."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"经理批评没有按时完成工作他。","isCorrect":false,"correctVersion":"经理批评他没有按时完成工作。","explanation":"Người bị phê bình đứng ngay sau 批评."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"教练表扬了因为他动作很标准。","isCorrect":false,"correctVersion":"教练表扬他动作很标准。","explanation":"Không dùng 因为 sau 表扬."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Huấn luyện viên khen tôi làm động tác rất chuẩn.","answer":"教练表扬我动作做得很准确。","answerPy":"Jiàoliàn biǎoyáng wǒ dòngzuò zuò de hěn zhǔnquè.","explanation":"表扬 + ai + (O) + V得 + Adj."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thầy giáo phê bình cậu ấy đi học muộn.","answer":"老师批评他上课迟到。","answerPy":"Lǎoshī pīpíng tā shàngkè chídào.","explanation":"批评 + ai + việc đã làm."}]},{"point":"递进复句“连……也/都……，……更……” — ngay cả … cũng …, (thì) … càng …","items":[{"context":"“Ngay cả một số người già lớn tuổi cũng kiên trì chơi bóng.”","pre":"","blank":"连","post":"一些年龄比较大的老人都坚持打球。","options":["连","就","才"],"answer":0,"explanation":"连……都……: nêu ví dụ cực đoan."},{"context":"“… người trẻ thì càng coi nó là cách rèn luyện hằng ngày.”","pre":"连老人都坚持打球，年轻人","blank":"更","post":"是把它作为一种日常锻炼的方式。","options":["更","最","太"],"answer":0,"explanation":"Vế 2 dùng 更 (càng)."},{"context":"“… đến lời thầy nói còn không hiểu …”","pre":"我有时候连老师说的话","blank":"也","post":"听不懂，听广播就更难了。","options":["也","就","才"],"answer":0,"explanation":"连 + tân ngữ đưa lên trước + 也 + V."},{"context":"“… càng không có thời gian chuẩn bị bữa sáng.”","pre":"今天早上他连脸都没来得及洗，更没有时间准备","blank":"早饭","post":"了。","options":["早饭","操场","设备"],"answer":0,"explanation":"Ôn 来得及 / 来不及 (Bài 4 · điểm 4)."},{"context":"“… càng không thể đến phòng gym tập luyện.”","pre":"受伤以后，他连走路都困难，更不能去","blank":"健身房","post":"锻炼了。","options":["健身房","会员","饼干"],"answer":0,"explanation":"去 + nơi + 锻炼."},{"type":"sort","context":"Sắp xếp: “Cậu ấy đến mặt còn không kịp rửa.”","words":["他","连","脸","都","没来得及洗"],"answer":"他连脸都没来得及洗。","explanation":"连 + tân ngữ + 都 + 没 + V."},{"type":"sort","context":"Sắp xếp: “Câu hỏi này đến trẻ con cũng biết, bạn thì càng phải biết.”","words":["这个问题","连","孩子","都","知道","，","你","更","应该知道了"],"answer":"这个问题连孩子都知道，你更应该知道了。","explanation":"连……都……，……更……"},{"type":"sort","context":"Sắp xếp: “Tôi bận đến mức đến cơm cũng không có thời gian ăn, càng không thể đi tập.”","words":["我","忙得","连饭","都","没时间吃","，","更","不能去健身了"],"answer":"我忙得连饭都没时间吃，更不能去健身了。","explanation":"V得 + 连……都……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"连一些年龄比较大的老人坚持打球。","isCorrect":false,"correctVersion":"连一些年龄比较大的老人都坚持打球。","explanation":"连 phải đi với 都 / 也."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他连这么难的事情都能解决，这件小事就更没问题了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: việc khó còn làm được → việc nhỏ càng được."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我连老师说的话也听不懂，听广播就更容易了。","isCorrect":false,"correctVersion":"我连老师说的话也听不懂，听广播就更难了。","explanation":"Hai vế phải cùng chiều."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Ngay cả ông tôi cũng biết dùng điện thoại thông minh, các bạn trẻ thì càng khỏi phải nói.","answer":"连我爷爷都会用智能手机，年轻人就更不用说了。","answerPy":"Lián wǒ yéye dōu huì yòng zhìnéng shǒujī, niánqīngrén jiù gèng búyòng shuō le.","explanation":"连……都 / 也……，……就更不用说了."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Anh ấy bận đến nỗi cuối tuần cũng phải tăng ca, càng không có thời gian đi phòng gym.","answer":"他忙得连周末都要加班，更没有时间去健身房了。","answerPy":"Tā máng de lián zhōumò dōu yào jiābān, gèng méiyǒu shíjiān qù jiànshēnfáng le.","explanation":"V得 + 连……都……，更没有……"}]}],"/lessons/hsk4v3-bai-18.html":[{"point":"“数词+形容词+量词”结构 — 一大碗, 一小段 (nhấn mạnh nhiều / ít, to / nhỏ)","items":[{"context":"“… lại dắt xe đi bộ một đoạn ngắn.”","pre":"快到那边那个出口时又推了一","blank":"小","post":"段。","options":["小","很","多"],"answer":0,"explanation":"一 + 小 + lượng từ 段: một quãng ngắn."},{"context":"“Trưa đói cực kỳ, tôi ăn một bát mì to.”","pre":"中午饿极了，我吃了一","blank":"大","post":"碗面条儿。","options":["大","太","好"],"answer":0,"explanation":"一 + 大 + 碗: nhấn mạnh nhiều."},{"context":"“… còn có cả một túi sô-cô-la to.”","pre":"快递里除了衣服外，还有一大","blank":"包","post":"巧克力。","options":["包","个","本"],"answer":0,"explanation":"Lượng từ tạm thời 包 (túi, gói)."},{"context":"“Anh ấy mượn cả một chồng sách to ở thư viện …”","pre":"他从图书馆借了一大","blank":"堆","post":"书，说要在假期里看完。","options":["堆","张","位"],"answer":0,"explanation":"一大堆 + N: cả đống, cả chồng."},{"context":"“… tôi mới ăn một miếng nhỏ đã không dám ăn nữa.” (ôn từ 小吃 của bài)","pre":"这个小吃太辣了，我只吃了一小","blank":"口","post":"就不敢吃了。","options":["口","条","件"],"answer":0,"explanation":"一小口 = một miếng nhỏ (口 mượn từ “miệng”)."},{"type":"sort","context":"Sắp xếp: “Trưa nay tôi ăn một bát mì to.”","words":["我","中午","吃了","一大碗","面条儿"],"answer":"我中午吃了一大碗面条儿。","explanation":"V + 了 + 一大碗 + N."},{"type":"sort","context":"Sắp xếp: “Sắp đến cổng ra, tôi lại dắt xe đi một đoạn ngắn.”","words":["快到出口时","，","我","又","推了","一小段"],"answer":"快到出口时，我又推了一小段。","explanation":"又 + V + 了 + 一小段."},{"type":"sort","context":"Sắp xếp: “Trên bàn đặt một đĩa đồ ăn vặt to.”","words":["桌子上","放着","一大盘","小吃"],"answer":"桌子上放着一大盘小吃。","explanation":"Nơi chốn + V着 + 一大盘 + N (ôn câu tồn hiện, HSK 3)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"妈妈给我寄了一很大包巧克力。","isCorrect":false,"correctVersion":"妈妈给我寄了一大包巧克力。","explanation":"Không thêm 很 vào giữa 一 và 大."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我只吃了一小块蛋糕，就吃不下了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 一小块 nhấn mạnh rất ít."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他点了一碗大面条儿。","isCorrect":false,"correctVersion":"他点了一大碗面条儿。","explanation":"大 đứng trước lượng từ 碗."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Sáng nay tôi chưa ăn sáng đã đi làm, trưa đói cực kỳ, ăn liền một bát mì to.","answer":"今天早上我没吃早饭就去上班了，中午饿极了，吃了一大碗面条儿。","answerPy":"Jīntiān zǎoshang wǒ méi chī zǎofàn jiù qù shàngbān le, zhōngwǔ è jí le, chī le yí dà wǎn miàntiáor.","explanation":"一大碗 nhấn mạnh ăn nhiều; ôn ……极了 (HSK 3)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Sắp đến cổng ra, tôi lại dắt xe đạp công cộng đi bộ một đoạn ngắn.","answer":"快到出口时，我又把共享单车推了一小段。","answerPy":"Kuài dào chūkǒu shí, wǒ yòu bǎ gòngxiǎng dānchē tuī le yì xiǎo duàn.","explanation":"一小段 + từ mới 出口, 推, 共享单车."}]},{"point":"被动句“主语+让/叫+宾语+动词+其他成分” — bị / được (ai) làm gì (khẩu ngữ)","items":[{"context":"“Sau đó video này được bạn cùng lớp tôi đăng lên mạng.”","pre":"后来这个视频","blank":"让","post":"我同学放到了互联网上。","options":["让","把","对"],"answer":0,"explanation":"Chủ ngữ chịu tác động (视频) + 让 + người làm."},{"context":"“Cửa bị Tiểu Minh đóng lại rồi.”","pre":"门叫小明","blank":"给","post":"关上了。","options":["给","把","被"],"answer":0,"explanation":"Khẩu ngữ: 让 / 叫 + O + 给 + V."},{"context":"“Xin lỗi, bánh trung thu bị tôi ăn hết rồi.”","pre":"不好意思，月饼都让我吃","blank":"了","post":"。","options":["了","过","着"],"answer":0,"explanation":"Động từ phải có 了 / bổ ngữ phía sau."},{"context":"“Đôi giày đó bị người khác mua mất rồi.”","pre":"那双鞋叫别人买","blank":"走","post":"了。","options":["走","来","起"],"answer":0,"explanation":"Bổ ngữ xu hướng 走: mua đi mất."},{"context":"“Điện thoại của tôi không bị em trai lấy đi, vẫn còn trên bàn.”","pre":"我的手机","blank":"没","post":"让弟弟拿走，还在桌子上呢。","options":["没","别","都"],"answer":0,"explanation":"Phủ định 没 đứng trước 让."},{"type":"sort","context":"Sắp xếp: “Video này được bạn cùng lớp tôi đăng lên mạng.”","words":["这个视频","让","我同学","放到了","互联网上"],"answer":"这个视频让我同学放到了互联网上。","explanation":"Chủ ngữ + 让 + người làm + V + 到 + nơi chốn."},{"type":"sort","context":"Sắp xếp: “Xe đạp của tôi bị bạn đạp đi mất rồi.”","words":["我的自行车","让","朋友","骑走了"],"answer":"我的自行车让朋友骑走了。","explanation":"让 + O + V + bổ ngữ 走 + 了."},{"type":"sort","context":"Sắp xếp: “Bánh ngọt bị bọn trẻ ăn hết sạch rồi.”","words":["蛋糕","都","叫","孩子们","给","吃完了"],"answer":"蛋糕都叫孩子们给吃完了。","explanation":"都 trước 叫; 给 ngay trước động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"那本书让借走了。","isCorrect":false,"correctVersion":"那本书让同学借走了。","explanation":"Sau 让 bị động phải có người làm."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我的钱包叫小偷给偷了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 叫 + người làm + 给 + V + 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"饺子都让我吃。","isCorrect":false,"correctVersion":"饺子都让我吃了。","explanation":"Thiếu 了 sau động từ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bánh trung thu của tôi bị em trai ăn hết rồi.","answer":"我的月饼都让弟弟吃了。","answerPy":"Wǒ de yuèbing dōu ràng dìdi chī le.","explanation":"Chủ ngữ chịu tác động + 让 / 叫 + người làm + V + 了."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Video của chúng tôi được bạn cùng lớp đăng lên mạng, rất nhiều người vào bấm thích.","answer":"我们的视频让同学放到了互联网上，很多人都来点赞。","answerPy":"Wǒmen de shìpín ràng tóngxué fàngdào le hùliánwǎng shàng, hěn duō rén dōu lái diǎnzàn.","explanation":"Bị động 让 + từ mới 互联网, 点赞."}]},{"point":"语气副词“到底” — rốt cuộc, rốt cục (truy hỏi đến cùng)","items":[{"context":"“Rốt cuộc công nghệ đã tạo ra ảnh hưởng như thế nào …?”","pre":"科技","blank":"到底","post":"对世界产生了怎样的影响？","options":["到底","终于","一定"],"answer":0,"explanation":"Câu hỏi truy vấn → 到底."},{"context":"“Rốt cuộc các bạn còn đến hay không?”","pre":"你们到底还来","blank":"不","post":"来？","options":["不","吗","没"],"answer":0,"explanation":"到底 + V不V; không dùng 吗."},{"context":"“Rốt cuộc bạn nghĩ thế nào? Sao không đồng ý?”","pre":"你到底是怎么想的？为什么不","blank":"同意","post":"？","options":["同意","讨论","预约"],"answer":0,"explanation":"不同意 = không đồng ý."},{"context":"“Rốt cuộc là ai đã đăng video lên mạng?”","pre":"到底","blank":"谁","post":"把视频放到了互联网上？","options":["谁","什么","哪儿"],"answer":0,"explanation":"到底 + 谁 (chủ ngữ là đại từ nghi vấn)."},{"context":"“Rốt cuộc chi phí chuyến du lịch này là bao nhiêu?”","pre":"这次旅行的","blank":"费用","post":"到底是多少？我们一起算一下吧。","options":["费用","原因","说明"],"answer":0,"explanation":"费用 = chi phí (từ mới của bài)."},{"type":"sort","context":"Sắp xếp: “Rốt cuộc các bạn còn đến hay không?”","words":["你们","到底","还","来不来"],"answer":"你们到底还来不来？","explanation":"Chủ ngữ + 到底 + V不V?"},{"type":"sort","context":"Sắp xếp: “Rốt cuộc ai đã đăng video lên mạng?”","words":["到底","谁","把视频","放到了","互联网上"],"answer":"到底谁把视频放到了互联网上？","explanation":"到底 + 谁 + 把……"},{"type":"sort","context":"Sắp xếp: “Rốt cuộc bạn đi xe buýt hay đạp xe đạp công cộng?”","words":["你","到底","是坐公交车","还是","骑共享单车"],"answer":"你到底是坐公交车还是骑共享单车？","explanation":"到底 + (是) A 还是 B?"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你到底喜欢不喜欢这部电影吗？","isCorrect":false,"correctVersion":"你到底喜欢不喜欢这部电影？","explanation":"Câu chính phản + 到底, không thêm 吗."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个问题到底怎么解决？","isCorrect":true,"correctVersion":"","explanation":"Đúng: 到底 + 怎么 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"谁到底说得对？","isCorrect":false,"correctVersion":"到底谁说得对？","explanation":"Chủ ngữ là 谁 → 到底 đứng trước."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Rốt cuộc bạn có đi hay không? Mọi người đều đang đợi bạn đấy.","answer":"你到底去不去？大家都在等你呢。","answerPy":"Nǐ dàodǐ qù bu qù? Dàjiā dōu zài děng nǐ ne.","explanation":"到底 + V不V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Rốt cuộc công nghệ đã thay đổi cuộc sống của chúng ta như thế nào?","answer":"科技到底怎样改变了我们的生活？","answerPy":"Kējì dàodǐ zěnyàng gǎibiàn le wǒmen de shēnghuó?","explanation":"到底 + đại từ nghi vấn 怎样 / 怎么."}]},{"point":"转折复句“……，然而……” — …, thế nhưng / tuy nhiên …","items":[{"context":"“… phải thường xuyên đi công tác, thế nhưng lại rất lo cho con mèo.”","pre":"由于工作等原因，她需要经常出差，","blank":"然而","post":"又很担心猫的安全。","options":["然而","而且","于是"],"answer":0,"explanation":"Hai vế trái ngược → 然而."},{"context":"“… có thể gặp đủ thứ vấn đề.”","pre":"毕业旅行越来越流行，然而由于学生没什么社会经验，可能会","blank":"遇到","post":"各种问题。","options":["遇到","提出","推出"],"answer":0,"explanation":"遇到 + 问题 = gặp vấn đề."},{"context":"“… vậy mà giờ hoa vẫn chưa nở.”","pre":"春天应该是花开的季节，然而现在花都","blank":"没","post":"开。","options":["没","才","就"],"answer":0,"explanation":"都没 + V: đều chưa."},{"context":"“… vậy mà đến hôm xuất phát, trời lại đổ mưa to.” (ôn 却 – Bài 16)","pre":"我们计划了一周，然而到了出发那天，天","blank":"却","post":"下起了大雨。","options":["却","就","才"],"answer":0,"explanation":"然而……却……: nhấn mạnh trái ngược."},{"context":"“Dịch vụ tận nhà rất tiện, tuy nhiên một số nhân viên hiện có chưa đủ chuyên nghiệp.”","pre":"上门服务很方便，","blank":"然而","post":"现有服务人员有些还不够专业。","options":["然而","所以","因为"],"answer":0,"explanation":"Ưu điểm ↔ vấn đề → 然而."},{"type":"sort","context":"Sắp xếp: “Cô ấy rất muốn đi du lịch, thế nhưng công việc bận quá.”","words":["她","很想去旅行","，","然而","工作","太忙了"],"answer":"她很想去旅行，然而工作太忙了。","explanation":"Vế 1，然而 + vế 2."},{"type":"sort","context":"Sắp xếp: “Mùa xuân lẽ ra là mùa hoa nở, vậy mà giờ hoa vẫn chưa nở.”","words":["春天","应该是","花开的季节","，","然而","现在","花都没开"],"answer":"春天应该是花开的季节，然而现在花都没开。","explanation":"Dự đoán (应该) ↔ thực tế → 然而."},{"type":"sort","context":"Sắp xếp: “Chúng tôi chuẩn bị rất lâu, vậy mà cuộc thi lại bị hủy.”","words":["我们","准备了很久","，","然而","比赛","却","取消了"],"answer":"我们准备了很久，然而比赛却取消了。","explanation":"然而 + chủ ngữ + 却 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"大家都在等他，他然而没有来。","isCorrect":false,"correctVersion":"大家都在等他，然而他没有来。","explanation":"然而 đứng trước chủ ngữ vế sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这家饭店的菜很好吃，然而价格也不贵。","isCorrect":false,"correctVersion":"这家饭店的菜很好吃，而且价格也不贵。","explanation":"Hai vế cùng chiều → 而且."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他学了三年中文，然而还是不敢开口说。","isCorrect":true,"correctVersion":"","explanation":"Đúng: học lâu ↔ vẫn không dám nói (trái dự đoán)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cô ấy rất muốn nuôi một con mèo, thế nhưng lại phải thường xuyên đi công tác.","answer":"她很想养一只猫，然而又需要经常出差。","answerPy":"Tā hěn xiǎng yǎng yì zhī māo, rán'ér yòu xūyào jīngcháng chūchāi.","explanation":"Mong muốn ↔ thực tế → 然而 (+ 又)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Dịch vụ tận nhà rất tiện lợi, tuy nhiên một số nhân viên phục vụ vẫn chưa đủ chuyên nghiệp.","answer":"上门服务很方便，然而有些服务人员还不够专业。","answerPy":"Shàngmén fúwù hěn fāngbiàn, rán'ér yǒuxiē fúwù rényuán hái bú gòu zhuānyè.","explanation":"然而 + từ mới 上门, 现有."}]}],"/lessons/hsk4v3-bai-19.html":[{"point":"选择复句“不是……，就是……” — không phải … thì là …","items":[{"context":"“Có lúc không phải quên lời thì là quên động tác.”","pre":"有时候","blank":"不是","post":"忘词，就是忘记做动作。","options":["不是","不但","虽然"],"answer":0,"explanation":"Vế sau có 就是 → vế trước dùng 不是 (lựa chọn một trong hai)."},{"context":"“… không ở nhà đọc sách thì là ra ngoài xem biểu diễn.” (lúc thế này, lúc thế kia)","pre":"周末的时候，小文不是在家看书，","blank":"就是","post":"出去看演出。","options":["就是","而是","还是"],"answer":0,"explanation":"Hai việc luân phiên, một trong hai → 不是……，就是……"},{"context":"“… không đi công tác thì là tăng ca ở công ty.”","pre":"杨同乐最近很忙，不是去外地出差，就是在公司","blank":"加班","post":"。","options":["加班","度假","散步"],"answer":0,"explanation":"Rất bận → 出差 / 加班 cùng loại công việc."},{"context":"“Cô ấy không phải người Trung Quốc mà là người Hàn, tôi từng nói chuyện với cô ấy.” (biết chắc)","pre":"她不是中国人，","blank":"而是","post":"韩国人，我跟她聊过。","options":["而是","就是","或者"],"answer":0,"explanation":"Biết chắc → phủ định A, khẳng định B → 不是……而是…… (Bài 11 · điểm 3), không dùng 就是."},{"context":"“… cộng thêm trời trở lạnh, nhiều người bị cảm.” (ôn Bài 14)","pre":"这几天不是刮大风，就是下大雨，","blank":"加上","post":"降温，好多人都感冒了。","options":["加上","于是","甚至"],"answer":0,"explanation":"加上 = cộng thêm nguyên nhân (Bài 14 · điểm 3)."},{"type":"sort","context":"Sắp xếp: “Cuối tuần Tiểu Văn không ở nhà đọc sách thì là ra ngoài xem biểu diễn.”","words":["周末","小文","不是","在家看书","，","就是","出去看演出"],"answer":"周末小文不是在家看书，就是出去看演出。","explanation":"Chủ ngữ + 不是 A，就是 B."},{"type":"sort","context":"Sắp xếp: “Chắc là ngày mai không có gió thì cũng mưa.”","words":["估计","明天","不是","刮风","，","就是","下雨"],"answer":"估计明天不是刮风，就是下雨。","explanation":"Phỏng đoán một trong hai: 估计 + 不是……就是……"},{"type":"sort","context":"Sắp xếp: “Tối nào anh ấy cũng không đi công viên chạy bộ thì là đi bơi.”","words":["他","每天晚上","不是","去公园跑步","，","就是","去游泳"],"answer":"他每天晚上不是去公园跑步，就是去游泳。","explanation":"Trạng ngữ thời gian đứng trước 不是."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"杨同乐最近很忙，不是去外地出差，就是在公司加班。","isCorrect":true,"correctVersion":"","explanation":"Đúng: hai việc luân phiên, cùng kết cấu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"最近很忙，不是出差，就加班。","isCorrect":false,"correctVersion":"最近很忙，不是出差，就是加班。","explanation":"Vế sau phải là 就是."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"那本书不是小王的，就是小李的，你看，上面写着小李的名字。","isCorrect":false,"correctVersion":"那本书不是小王的，而是小李的，你看，上面写着小李的名字。","explanation":"Đã biết chắc là của Tiểu Lý → 不是……而是……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Dạo này anh ấy rất bận, không đi công tác thì là tăng ca.","answer":"他最近很忙，不是出差，就是加班。","answerPy":"Tā zuìjìn hěn máng, bú shì chūchāi, jiùshì jiābān.","explanation":"不是 A，就是 B — hai việc luân phiên."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cuối tuần tôi không ở nhà đọc sách thì là đi xem biểu diễn với bạn.","answer":"周末我不是在家看书，就是和朋友去看演出。","answerPy":"Zhōumò wǒ bú shì zài jiā kànshū, jiùshì hé péngyou qù kàn yǎnchū.","explanation":"Chủ ngữ đứng trước 不是."}]},{"point":"固定格式“动词+一×是一×” — làm được … nào hay … ấy","items":[{"context":"“… hiểu được chút nào hay chút ấy.”","pre":"咱们先做做功课，提前了解下，能懂一点儿","blank":"是","post":"一点儿。","options":["是","就","也"],"answer":0,"explanation":"V + 一点儿 + 是 + 一点儿."},{"context":"“… đọc được trang nào hay trang ấy.”","pre":"虽然这本书很厚，但是我还是要看，看一","blank":"页","post":"是一页。","options":["页","本","次"],"answer":0,"explanation":"Hai lượng từ phải giống nhau: 一页……一页."},{"context":"“… như vậy sức khoẻ mới khá lên được.”","pre":"你能多吃一点儿是一点儿，这样身体","blank":"才","post":"能好起来。","options":["才","就","都"],"answer":0,"explanation":"这样……才…… = có như thế mới… (điều kiện cần)."},{"context":"“… làm được việc nào hay việc ấy.”","pre":"事情实在太多了，别着急，慢慢做，做一","blank":"件","post":"是一件。","options":["件","个","遍"],"answer":0,"explanation":"事情 dùng lượng từ 件; hai bên phải cùng 件."},{"context":"“Cho dù mỗi ngày chỉ có mười phút, tôi cũng kiên trì…” (ôn Bài 11)","pre":"即使每天只有十分钟，我","blank":"也","post":"坚持背生词，背一个是一个。","options":["也","就","才"],"answer":0,"explanation":"即使……，Sub + 也…… (Bài 11 · điểm 1)."},{"type":"sort","context":"Sắp xếp: “Chúng mình cứ chuẩn bị trước, hiểu được chút nào hay chút ấy.”","words":["咱们","先做做功课","，","能懂","一点儿","是","一点儿"],"answer":"咱们先做做功课，能懂一点儿是一点儿。","explanation":"能 + V + 一点儿是一点儿."},{"type":"sort","context":"Sắp xếp: “Đừng vội, làm từ từ, làm được việc nào hay việc ấy.”","words":["别着急","，","慢慢做","，","做","一件","是","一件"],"answer":"别着急，慢慢做，做一件是一件。","explanation":"V + 一件 + 是 + 一件."},{"type":"sort","context":"Sắp xếp: “Nhiều vấn đề thế này, chúng ta giải quyết được cái nào hay cái ấy.”","words":["这么多问题","，","我们","解决","一个","是","一个"],"answer":"这么多问题，我们解决一个是一个。","explanation":"V + 一个是一个."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你能多吃一点儿是一点儿，这样身体才能好起来。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 能多 + V + 一点儿是一点儿."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"看一页看一页，最后一定能看完。","isCorrect":false,"correctVersion":"看一页是一页，最后一定能看完。","explanation":"Thiếu 是 ở giữa; không lặp động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这些生词，我每天记一个是两个。","isCorrect":false,"correctVersion":"这些生词，我每天记一个是一个。","explanation":"Hai bên phải cùng là 一 + cùng lượng từ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Không sao, chúng ta tìm hiểu trước một chút, hiểu được chút nào hay chút ấy.","answer":"没事，咱们提前了解一下，能懂一点儿是一点儿。","answerPy":"Méishì, zánmen tíqián liǎojiě yíxià, néng dǒng yìdiǎnr shì yìdiǎnr.","explanation":"能懂一点儿是一点儿."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cuốn sách tuy dày, nhưng đọc được trang nào hay trang ấy, cuối cùng nhất định đọc xong.","answer":"这本书虽然很厚，但是看一页是一页，最后一定能看完。","answerPy":"Zhè běn shū suīrán hěn hòu, dànshì kàn yí yè shì yí yè, zuìhòu yídìng néng kànwán.","explanation":"虽然……但是…… + 看一页是一页."}]},{"point":"“把”字句“主语+把+宾语+动词+动量补语” — làm việc gì với đối tượng mấy lần","items":[{"context":"“… đã tìm hiểu trước câu chuyện một lượt …”","pre":"因为李文他们提前把故事了解了一","blank":"遍","post":"，所以差不多都看懂了。","options":["遍","本","个"],"answer":0,"explanation":"Động lượng từ 遍 = một lượt trọn vẹn."},{"context":"“Anh ấy làm động tác này mấy lần …”","pre":"他","blank":"把","post":"这个动作做了好几次，最后终于做对了。","options":["把","被","给"],"answer":0,"explanation":"Chủ ngữ chủ động tác động lên 这个动作 → 把."},{"context":"“Bạch Gia Nguyệt LẠI đọc cuốn sách này mấy lượt …” (việc đã xảy ra)","pre":"白家月","blank":"又","post":"把这本书看了几遍，越看越喜欢。","options":["又","再","还"],"answer":0,"explanation":"又 (lặp lại, đã xảy ra) đứng trước 把; 再 dùng cho việc chưa xảy ra."},{"context":"“… chúng tôi tập tiết mục này mười mấy lượt.”","pre":"为了演好，我们把这个节目排了十几","blank":"遍","post":"。","options":["遍","趟","下"],"answer":0,"explanation":"Tập trọn tiết mục từ đầu đến cuối → 遍."},{"context":"“Anh ấy gõ cửa ba cái, nhưng không ai mở.”","pre":"他把门敲了三","blank":"下","post":"，可是没有人开。","options":["下","遍","本"],"answer":0,"explanation":"Động tác nhanh, ngắn (gõ, vỗ) → 下."},{"type":"sort","context":"Sắp xếp: “Anh ấy làm động tác này mấy lần, cuối cùng cũng làm đúng.”","words":["他","把","这个动作","做了","好几次","，","最后","终于做对了"],"answer":"他把这个动作做了好几次，最后终于做对了。","explanation":"把 + 宾 + V了 + 好几次."},{"type":"sort","context":"Sắp xếp: “Bạch Gia Nguyệt lại đọc cuốn sách này mấy lượt.”","words":["白家月","又","把","这本书","看了","几遍"],"answer":"白家月又把这本书看了几遍。","explanation":"又 đứng trước 把."},{"type":"sort","context":"Sắp xếp: “Chúng tôi tập tiết mục này mười mấy lượt.”","words":["我们","把","这个节目","排了","十几遍"],"answer":"我们把这个节目排了十几遍。","explanation":"Số lần ở cuối câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"因为李文他们提前把故事了解了一遍，所以差不多都看懂了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 提前 đứng trước 把, 一遍 sau động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把这本书两遍看了。","isCorrect":false,"correctVersion":"我把这本书看了两遍。","explanation":"Bổ ngữ động lượng đứng sau động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他把一个问题讲了好几遍。","isCorrect":false,"correctVersion":"他把这个问题讲了好几遍。","explanation":"Tân ngữ của 把 phải xác định."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cô ấy đã đọc cuốn sách này mấy lượt, càng đọc càng thích.","answer":"她把这本书看了好几遍，越看越喜欢。","answerPy":"Tā bǎ zhè běn shū kàn le hǎojǐ biàn, yuè kàn yuè xǐhuan.","explanation":"把 + 宾 + V了 + 好几遍 + ôn 越……越……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi đã xem trước bài khoá một lượt, nên trên lớp nghe hiểu hết.","answer":"我提前把课文看了一遍，所以上课都听懂了。","answerPy":"Wǒ tíqián bǎ kèwén kàn le yí biàn, suǒyǐ shàngkè dōu tīngdǒng le.","explanation":"提前 đứng trước 把; 一遍 sau động từ."}]},{"point":"“把”字句“主语+把+宾语+动词+时量补语” — làm việc gì với đối tượng trong bao lâu","items":[{"context":"“Về đến nhà, tôi lại đọc cuốn sách này suốt hai ngày.”","pre":"到家后，我又把这本书看了两","blank":"天","post":"。","options":["天","本","页"],"answer":0,"explanation":"Bổ ngữ thời lượng: 两天."},{"context":"“… mọi người MỚI hiểu.” (muộn, khó khăn)","pre":"王老师把这个问题又讲了十分钟，大家","blank":"才","post":"明白。","options":["才","就","都"],"answer":0,"explanation":"Tốn thời gian rồi mới có kết quả → 才."},{"context":"“… luyện động tác này thêm một tiếng.”","pre":"为了演好，陈天中把这个动作又练了一个","blank":"小时","post":"。","options":["小时","遍","次"],"answer":0,"explanation":"一个 + 小时 (thời lượng); 遍 / 次 không đi với 个."},{"context":"“… tôi sắp xếp chúng mất nửa tiếng.”","pre":"桌子上的东西太多、太乱了，我把它们","blank":"整理","post":"了半个小时。","options":["整理","转发","报考"],"answer":0,"explanation":"整理 = sắp xếp (từ mới bài khoá 4)."},{"context":"“… không chừng sẽ thành công.” (ôn Bài 16)","pre":"为了这次面试，他把自我介绍准备了整整一个星期，","blank":"说不定","post":"能成功。","options":["说不定","到底","究竟"],"answer":0,"explanation":"说不定 = có lẽ, không chừng (Bài 16 · điểm 3)."},{"type":"sort","context":"Sắp xếp: “Thầy Vương giảng vấn đề này thêm mười phút.”","words":["王老师","把","这个问题","又","讲了","十分钟"],"answer":"王老师把这个问题又讲了十分钟。","explanation":"又 đứng trước động từ (hoặc trước 把)."},{"type":"sort","context":"Sắp xếp: “Về đến nhà tôi lại đọc cuốn sách này suốt hai ngày.”","words":["我","到家后","又","把","这本书","看了","两天"],"answer":"我到家后又把这本书看了两天。","explanation":"Thời lượng ở cuối câu."},{"type":"sort","context":"Sắp xếp: “Các bạn luyện chữ Hán này cả một buổi sáng.”","words":["同学们","把","这个汉字","练了","一个上午"],"answer":"同学们把这个汉字练了一个上午。","explanation":"把 + 宾 + V了 + 一个上午."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"陈天中把这个动作又练了一小时。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 又 + V了 + thời lượng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把这本书两天看了。","isCorrect":false,"correctVersion":"我把这本书看了两天。","explanation":"Thời lượng đứng sau động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"王老师讲了这个问题十分钟。","isCorrect":false,"correctVersion":"王老师把这个问题讲了十分钟。","explanation":"Không đặt thời lượng sau tân ngữ → dùng 把."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thầy Vương giảng vấn đề này thêm mười phút, mọi người mới hiểu.","answer":"王老师把这个问题又讲了十分钟，大家才明白。","answerPy":"Wáng lǎoshī bǎ zhège wèntí yòu jiǎng le shí fēnzhōng, dàjiā cái míngbai.","explanation":"把 + 宾 + 又 + V了 + 十分钟，……才……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Về đến nhà, tôi lại đọc cuốn sách này suốt hai ngày.","answer":"到家后，我又把这本书看了两天。","answerPy":"Dào jiā hòu, wǒ yòu bǎ zhè běn shū kàn le liǎng tiān.","explanation":"又 + 把 + 宾 + V了 + 两天."}]}],"/lessons/hsk4v3-bai-2.html":[{"point":"固定格式“×就是了” — cứ … là được","items":[{"context":"“Nếu quyết định thuê thì cứ báo tôi là được.”","pre":"如果决定租了，告诉我","blank":"就是了","post":"。","options":["就是了","就是","是了"],"answer":0,"explanation":"Cấu trúc cố định: V + 就是了 (phải có 了)."},{"context":"“Tôi nhất định làm được, ông cứ yên tâm.”","pre":"我一定能办到，您","blank":"放心","post":"就是了。","options":["放心","担心","关心"],"answer":0,"explanation":"放心就是了 = cứ yên tâm."},{"context":"“Lần sau cố gắng là được.”","pre":"这次考得不好没关系，下次努力","blank":"就是了","post":"。","options":["就是了","才是了","也是了"],"answer":0,"explanation":"Đặt 就是了 ở cuối câu để động viên."},{"context":"“Bạn hài lòng thì cứ thuê luôn.” (ôn từ mới + 要是 – Bài 1)","pre":"你要是满意，","blank":"租","post":"下来就是了。","options":["租","出租","房租"],"answer":0,"explanation":"租下来 = thuê luôn; 出租 = cho thuê; 房租 = tiền thuê."},{"context":"“Phòng đã dọn xong, hôm nay bạn cứ dọn vào.”","pre":"房间已经","blank":"收拾","post":"好了，你今天搬进来就是了。","options":["收拾","入住","毕业"],"answer":0,"explanation":"收拾好了 = dọn dẹp xong."},{"type":"sort","context":"Sắp xếp: “Nếu bạn hài lòng thì cứ thuê luôn đi.”","words":["你","要是","满意","，","租下来","就是了"],"answer":"你要是满意，租下来就是了。","explanation":"要是……，V + 就是了."},{"type":"sort","context":"Sắp xếp: “Có bất kỳ vấn đề gì cứ gọi cho tôi là được.”","words":["有","任何","问题","，","给我","打电话","就是了"],"answer":"有任何问题，给我打电话就是了。","explanation":"Ôn 任何 (Bài 1) + 就是了 cuối câu."},{"type":"sort","context":"Sắp xếp: “Không biết làm cũng không sao, tôi dạy bạn là được.”","words":["不会","做","没关系","，","我","教你","就是了"],"answer":"不会做没关系，我教你就是了。","explanation":"Chủ ngữ 我 + V + 就是了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你别担心，我明天一定来就是了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 就是了 cuối câu, trấn an người nghe."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服很漂亮，你买下来就是。","isCorrect":false,"correctVersion":"这件衣服很漂亮，你买下来就是了。","explanation":"Thiếu 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"就是了你下次努力。","isCorrect":false,"correctVersion":"你下次努力就是了。","explanation":"就是了 phải đặt cuối câu."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nếu bạn thích thì cứ lấy đi là được.","answer":"你要是喜欢，拿走就是了。","answerPy":"Nǐ yàoshi xǐhuan, názǒu jiùshì le.","explanation":"要是……，V + 就是了 (ôn Bài 1 · điểm 2)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Có bất kỳ vấn đề gì, bạn cứ hỏi tôi là được.","answer":"有任何问题，你问我就是了。","answerPy":"Yǒu rènhé wèntí, nǐ wèn wǒ jiùshì le.","explanation":"任何 (Bài 1 · điểm 1) + 就是了."}]},{"point":"转折复句“……，不过……” — …, có điều …","items":[{"context":"“Môi trường đẹp thật, có điều nghe nói gần đây có nhiều công ty.”","pre":"这个小区的环境真不错，","blank":"不过","post":"我听说，附近有十几家公司。","options":["不过","所以","而且"],"answer":0,"explanation":"Vế sau chuyển ý → 不过."},{"context":"“… có điều không thấy gấu trúc.”","pre":"我们在动物园看见了很多动物，不过","blank":"没","post":"看见大熊猫。","options":["没","不","别"],"answer":0,"explanation":"Phủ định việc đã xảy ra: 没 + V."},{"context":"“… có điều rất nhanh đã thích nghi.” (ôn từ Bài 1)","pre":"我刚来北京时还不太习惯这里的天气，不过很快就","blank":"适应","post":"了。","options":["适应","交流","申请"],"answer":0,"explanation":"适应 = thích nghi."},{"context":"“Phòng này khá sáng, có điều hơi nhỏ.”","pre":"这个房间挺","blank":"亮","post":"，不过有点儿小。","options":["亮","租","种"],"answer":0,"explanation":"挺亮 = khá sáng (tính từ)."},{"context":"“Tiền thuê không cao, có điều hơi xa công ty.”","pre":"房租不高，","blank":"不过","post":"离公司有点儿远。","options":["不过","因为","并且"],"answer":0,"explanation":"Khen trước, góp ý sau → 不过."},{"type":"sort","context":"Sắp xếp: “Chiếc điện thoại này cũng được, có điều hơi đắt.”","words":["这个手机","还可以","，","不过","有点儿贵"],"answer":"这个手机还可以，不过有点儿贵。","explanation":"……，不过 + ý chuyển."},{"type":"sort","context":"Sắp xếp: “Nhà rất đẹp, có điều xung quanh không yên tĩnh lắm.”","words":["房子","很漂亮","，","不过","周围","不太安静"],"answer":"房子很漂亮，不过周围不太安静。","explanation":"不过 đứng trước chủ ngữ vế sau (周围)."},{"type":"sort","context":"Sắp xếp: “Tôi rất muốn đi, có điều e là không có thời gian.”","words":["我","很想去","，","不过","恐怕","没有时间"],"answer":"我很想去，不过恐怕没有时间。","explanation":"不过 + 恐怕 (từ mới bài này)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个小区很安静，不过环境也很好。","isCorrect":false,"correctVersion":"这个小区很安静，而且环境也很好。","explanation":"Hai ý cùng chiều tốt → dùng 而且, không dùng 不过."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"天气预报说明天是晴天，不过可能会刮风。","isCorrect":true,"correctVersion":"","explanation":"Đúng: trời nắng (tốt) — có điều có gió (chưa tốt)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不过他很忙，他每天都去跑步。","isCorrect":false,"correctVersion":"他很忙，不过每天都去跑步。","explanation":"不过 đứng ở đầu vế SAU."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Căn nhà này vị trí rất tốt, có điều tiền thuê hơi đắt.","answer":"这个房子位置很好，不过房租有点儿贵。","answerPy":"Zhège fángzi wèizhì hěn hǎo, búguò fángzū yǒudiǎnr guì.","explanation":"位置, 房租 (từ mới) + 不过."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi rất muốn đi du lịch, có điều e là không có thời gian.","answer":"我很想去旅游，不过恐怕没有时间。","answerPy":"Wǒ hěn xiǎng qù lǚyóu, búguò kǒngpà méiyǒu shíjiān.","explanation":"不过 + 恐怕."}]},{"point":"连词/副词“并” — và, đồng thời; hoàn toàn (không)","items":[{"context":"“… và chỉ cho tôi cách dùng.”","pre":"房东又向我介绍了一下房子里的东西，","blank":"并","post":"告诉我这些东西怎么用。","options":["并","和","跟"],"answer":0,"explanation":"Nối hai cụm động từ → 并 (和 nối danh từ)."},{"context":"“… lần thuê nhà này chẳng hề dễ.”","pre":"对白家月来说，这次租房并","blank":"不","post":"容易。","options":["不","没","很"],"answer":0,"explanation":"并不 + tính từ."},{"context":"“… và xin được học bổng.” (ôn từ Bài 1)","pre":"她考上了北京大学并申请到了","blank":"奖学金","post":"。","options":["奖学金","房租","工资"],"answer":0,"explanation":"申请到 + 奖学金."},{"context":"“Tôi đâu có đồng ý thuê ngay …”","pre":"我","blank":"并","post":"没有答应你就租这个房子，我还要再想想。","options":["并","也","就"],"answer":0,"explanation":"并没有 = phủ định mạnh, phản bác."},{"context":"“Học chữ Hán chẳng khó, cứ viết nhiều luyện nhiều là được.” (ôn 就是了 – điểm 1)","pre":"学汉字","blank":"并","post":"不难，多写多练就是了。","options":["并","和","还"],"answer":0,"explanation":"并不难 = chẳng khó chút nào."},{"type":"sort","context":"Sắp xếp: “Tốt nghiệp xong anh ấy đến Bắc Kinh làm việc, và thuê một căn nhà gần công ty.”","words":["他","毕业后","来北京工作","，","并","在公司附近","租了个房子"],"answer":"他毕业后来北京工作，并在公司附近租了个房子。","explanation":"V1……，并 + V2……"},{"type":"sort","context":"Sắp xếp: “Khu chung cư này chẳng yên tĩnh chút nào.”","words":["这个","小区","并","不","安静"],"answer":"这个小区并不安静。","explanation":"并不 + Adj."},{"type":"sort","context":"Sắp xếp: “Chúng tôi đã thảo luận vấn đề này và đưa ra quyết định.”","words":["我们","讨论了","这个问题","，","并","做出了","决定"],"answer":"我们讨论了这个问题，并做出了决定。","explanation":"Hai hành động nối tiếp, cùng chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我买了苹果并香蕉。","isCorrect":false,"correctVersion":"我买了苹果和香蕉。","explanation":"并 không nối hai danh từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"其实这个问题并不难。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 并不 phản bác suy nghĩ “khó”."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在北京租房子不并容易。","isCorrect":false,"correctVersion":"在北京租房子并不容易。","explanation":"Thứ tự đúng: 并不."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cô ấy tìm được việc làm và thuê một căn nhà gần công ty.","answer":"她找到了工作，并在公司附近租了一个房子。","answerPy":"Tā zhǎodào le gōngzuò, bìng zài gōngsī fùjìn zū le yí gè fángzi.","explanation":"并 nối hai hành động, không lặp chủ ngữ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thực ra thuê nhà ở Bắc Kinh chẳng hề rẻ.","answer":"其实在北京租房子并不便宜。","answerPy":"Qíshí zài Běijīng zū fángzi bìng bú piányi.","explanation":"并不 + Adj: phản bác suy nghĩ “rẻ”."}]},{"point":"连词/介词“由于” — do, bởi vì","items":[{"context":"“Do trời mưa to suốt, nên …”","pre":"","blank":"由于","post":"一直下大雨，所以我们决定不爬山了。","options":["由于","虽然","要是"],"answer":0,"explanation":"由于……，所以…… (nhân quả)."},{"context":"“… nên lúc đầu họ cũng không mua nhà.”","pre":"由于很多刚工作的年轻人工资还不太高，","blank":"所以","post":"他们一开始也不买房。","options":["所以","但是","而且"],"answer":0,"explanation":"Vế sau của 由于 dùng 所以 / 因此."},{"context":"“Nhờ sự nỗ lực của mọi người …”","pre":"由于大家的","blank":"努力","post":"，这次运动会我们班获得了第一名。","options":["努力","房租","位置"],"answer":0,"explanation":"Giới từ: 由于 + danh từ."},{"context":"“… vì vậy nhiều người thích thuê nhà ở đây.”","pre":"由于这个小区很安静，房子价格也不高，","blank":"因此","post":"，很多人都喜欢在这里租房子。","options":["因此","不过","并"],"answer":0,"explanation":"由于……，因此…… (因此 yīncǐ = vì vậy)."},{"context":"“… cô ấy quyết định thuê nhà gần công ty.”","pre":"由于新公司离她住的地方比较远，她决定在公司","blank":"附近","post":"租个房子。","options":["附近","价格","信息"],"answer":0,"explanation":"在 + nơi + 附近 = ở gần …"},{"type":"sort","context":"Sắp xếp: “Do điện thoại hết pin, cô ấy không có cách nào gọi điện.”","words":["由于","手机","没电了","，","她","没有办法","打电话"],"answer":"由于手机没电了，她没有办法打电话。","explanation":"由于 + nguyên nhân，kết quả."},{"type":"sort","context":"Sắp xếp: “Do lương không cao lắm nên anh ấy chọn thuê nhà.”","words":["由于","工资","不太高","，","所以","他","选择租房"],"answer":"由于工资不太高，所以他选择租房。","explanation":"由于……，所以……"},{"type":"sort","context":"Sắp xếp: “Nhờ sự giúp đỡ của mọi người, chúng tôi đã nhanh chóng hoàn thành công việc.”","words":["由于","大家的","帮助","，","我们","很快就","完成了工作"],"answer":"由于大家的帮助，我们很快就完成了工作。","explanation":"Giới từ: 由于 + cụm danh từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"由于天气不好，所以飞机晚到了两个小时。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 由于……，所以……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"由于下雨，但是比赛没有停。","isCorrect":false,"correctVersion":"虽然下雨，但是比赛没有停。","explanation":"Đây là quan hệ nhượng bộ → 虽然……但是……; 由于 chỉ nguyên nhân."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我没去上课，由于我生病了。","isCorrect":false,"correctVersion":"由于我生病了，所以没去上课。","explanation":"由于 đứng ở vế trước."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Do lương còn chưa cao nên nhiều người trẻ chọn thuê nhà.","answer":"由于工资还不太高，所以很多年轻人选择租房。","answerPy":"Yóuyú gōngzī hái bú tài gāo, suǒyǐ hěn duō niánqīngrén xuǎnzé zū fáng.","explanation":"由于……，所以…… + từ mới 工资."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nhờ sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt đã thuê được căn nhà phù hợp.","answer":"由于李文的帮助，白家月租到了合适的房子。","answerPy":"Yóuyú Lǐ Wén de bāngzhù, Bái Jiāyuè zū dào le héshì de fángzi.","explanation":"Giới từ: 由于 + cụm danh từ."}]}],"/lessons/hsk4v3-bai-20.html":[{"point":"语气副词“难道” — lẽ nào, chẳng lẽ (câu hỏi tu từ, phỏng đoán)","items":[{"context":"“… chẳng lẽ cậu mua vé không có chỗ ngồi à?”","pre":"看你一直不坐下，我还在想，","blank":"难道","post":"你买的是无座票吗？","options":["难道","到底","究竟"],"answer":0,"explanation":"Câu tu từ có 吗 → 难道; 到底 / 究竟 là hỏi thật, không đi với 吗."},{"context":"“Chẳng lẽ chúng ta không nên bảo vệ môi trường sao?”","pre":"难道我们不应该保护环境","blank":"吗","post":"？","options":["吗","呢","吧"],"answer":0,"explanation":"Khuôn 难道……吗？"},{"context":"“… lẽ nào không sợ bị cảm à?”","pre":"这么冷的天，你只穿了一件衬衫，难道不怕","blank":"感冒","post":"吗？","options":["感冒","堵车","登机"],"answer":0,"explanation":"Phủ định 不怕 → ý khẳng định: sẽ bị cảm đấy."},{"context":"“Bạn nói tiếng Trung lưu loát thế, lẽ nào bạn từng sống ở Trung Quốc?”","pre":"你中文说得这么","blank":"流利","post":"，难道你在中国住过吗？","options":["流利","所有","细"],"answer":0,"explanation":"难道 dùng để phỏng đoán; V得 + 流利."},{"context":"“Chuyện này ai cũng biết, chẳng lẽ bạn không biết?”","pre":"这件事大家都知道，难道你","blank":"不","post":"知道吗？","options":["不","也","就"],"answer":0,"explanation":"难道 + 不 + V + 吗？ = ý khẳng định: bạn phải biết chứ."},{"type":"sort","context":"Sắp xếp: “Chẳng lẽ cậu mua vé không có chỗ ngồi à?”","words":["难道","你","买的","是","无座票","吗"],"answer":"难道你买的是无座票吗？","explanation":"难道 + câu + 吗？"},{"type":"sort","context":"Sắp xếp: “Chẳng lẽ chúng ta không nên bảo vệ môi trường sao?”","words":["难道","我们","不应该","保护","环境","吗"],"answer":"难道我们不应该保护环境吗？","explanation":"难道 đứng đầu câu hoặc sau chủ ngữ."},{"type":"sort","context":"Sắp xếp: “Tàu sắp chạy rồi, anh ấy vẫn chưa đến, lẽ nào anh ấy không đi nữa?”","words":["车快开了","，","他还没到","，","难道","他不去了"],"answer":"车快开了，他还没到，难道他不去了？","explanation":"难道 biểu thị phỏng đoán, có thể không có 吗."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你已经是大学生了，难道这点儿小事也不会做吗？","isCorrect":true,"correctVersion":"","explanation":"Đúng: phủ định 不会做 → ý khẳng định “việc nhỏ này bạn phải làm được”."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"难道你知道不知道这件事？","isCorrect":false,"correctVersion":"难道你不知道这件事吗？","explanation":"难道 không đi với câu hỏi chính phản V不V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我难道是你的朋友吗？我一定会帮你的。","isCorrect":false,"correctVersion":"难道我不是你的朋友吗？我一定会帮你的。","explanation":"Muốn khẳng định “tôi là bạn của bạn” phải dùng hình thức phủ định 难道……不……吗？"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chẳng lẽ bạn không biết ngày mai có kỳ thi sao?","answer":"难道你不知道明天有考试吗？","answerPy":"Nándào nǐ bù zhīdao míngtiān yǒu kǎoshì ma?","explanation":"难道 + 不 + V + 吗？ → ý khẳng định."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đã mười giờ rồi mà anh ấy vẫn chưa đến, lẽ nào anh ấy quên rồi?","answer":"已经十点了他还没来，难道他忘了？","answerPy":"Yǐjīng shí diǎn le tā hái méi lái, nándào tā wàng le?","explanation":"难道 biểu thị phỏng đoán."}]},{"point":"反问句：由疑问代词构成的反问句 — Câu hỏi tu từ (phản vấn) dùng đại từ nghi vấn 「谁、什么、怎么、哪里、为什么」","items":[{"context":"“Ai bảo không phải chứ?” (= đúng thế)","pre":"中国文化真是读也读不完。——谁说不","blank":"是","post":"呢？","options":["是","对","好"],"answer":0,"explanation":"Câu cố định 谁说不是呢？ biểu thị đồng tình."},{"context":"“… sao chúng ta lại không đi Tô Châu chơi?” (= nên đi)","pre":"这里离苏州这么近，我们为什么","blank":"不","post":"去苏州玩玩呢？","options":["不","没","也"],"answer":0,"explanation":"为什么不……呢？ phủ định → ý khẳng định."},{"context":"“… làm sao mà tra được những thông tin này?”","pre":"我们连手机都没有，","blank":"怎么","post":"能查到这些信息啊？","options":["怎么","什么","谁"],"answer":0,"explanation":"怎么能……？ = không thể … (ôn 连……都…… – Bài 17)."},{"context":"“Tôi đã kiểm tra mấy lần rồi, làm sao mà sai được?”","pre":"我已经检查好几遍了，怎么会出错","blank":"呢","post":"？","options":["呢","吗","吧"],"answer":0,"explanation":"Câu tu từ có đại từ nghi vấn dùng 呢, không dùng 吗."},{"context":"“Cậu ấy một câu tiếng Trung cũng không biết, làm sao mà đọc hiểu tiểu thuyết của Lão Xá được?”","pre":"他一句中文都不会，","blank":"哪儿","post":"能看懂老舍的小说呢？","options":["哪儿","什么","谁"],"answer":0,"explanation":"哪儿能……？ = không thể …; ôn 一……都不…… (HSK 3)."},{"type":"sort","context":"Sắp xếp: “Ở đây gần Tô Châu thế, sao chúng ta lại không đi Tô Châu chơi?”","words":["这里","离苏州","这么近","，","我们","为什么不","去苏州玩玩呢"],"answer":"这里离苏州这么近，我们为什么不去苏州玩玩呢？","explanation":"为什么不……呢？"},{"type":"sort","context":"Sắp xếp: “Chúng ta đến điện thoại cũng không có, làm sao tra được những thông tin này?”","words":["我们","连手机都没有","，","怎么能","查到","这些信息啊"],"answer":"我们连手机都没有，怎么能查到这些信息啊？","explanation":"怎么能 + V？ = không thể."},{"type":"sort","context":"Sắp xếp: “Tôi đã kiểm tra mấy lần rồi, làm sao mà sai được?”","words":["我","已经检查好几遍了","，","怎么会","出错呢"],"answer":"我已经检查好几遍了，怎么会出错呢？","explanation":"怎么会……呢？ = không thể nào …"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"谁说不是呢？中国文化真是读也读不完。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 谁说不是呢 = đồng tình."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我已经检查好几遍了，怎么会出错吗？","isCorrect":false,"correctVersion":"我已经检查好几遍了，怎么会出错呢？","explanation":"Đã có 怎么 thì không dùng 吗."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这么好的机会，你为什么去试试呢？","isCorrect":false,"correctVersion":"这么好的机会，你为什么不去试试呢？","explanation":"Khuyên nên làm → 为什么不……呢？"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tiền tiết kiệm được, sao lại không dùng để đi du lịch?","answer":"节省下来的钱，为什么不用来旅行呢？","answerPy":"Jiéshěng xiàlai de qián, wèishénme bú yònglái lǚxíng ne?","explanation":"为什么不……呢？ = nên làm."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bài tập nhiều thế này, một ngày làm sao làm xong được?","answer":"作业这么多，一天怎么能做完呢？","answerPy":"Zuòyè zhème duō, yì tiān zěnme néng zuòwán ne?","explanation":"怎么能 / 怎么 + V得完 + 呢？ = không thể."}]},{"point":"固定格式“×就×（点儿）吧” — … thì … (một chút) thôi, cũng được (chấp nhận, nhượng bộ)","items":[{"context":"“… mệt thì mệt một chút thôi …”","pre":"虽然有些累，但累就","blank":"累","post":"点儿吧，花更少的钱去看更多的地方，很值得。","options":["累","远","慢"],"answer":0,"explanation":"× lặp lại nguyên dạng: 累就累点儿吧."},{"context":"“… xa thì xa thôi, ít nhất tiền thuê rẻ.”","pre":"我租的房子离公司有些远，我想，远","blank":"就","post":"远吧，至少房租便宜。","options":["就","也","才"],"answer":0,"explanation":"× + 就 + × + 吧."},{"context":"“Chậm thì chậm một chút, an toàn là quan trọng nhất.”","pre":"慢就慢点儿吧，","blank":"安全","post":"最重要。","options":["安全","特点","意见"],"answer":0,"explanation":"Vế sau nêu lý do chấp nhận."},{"context":"“Chiếc áo này đắt thì đắt một chút, chất lượng tốt là được.”","pre":"这件衣服贵就贵点儿","blank":"吧","post":"，质量好就行。","options":["吧","吗","呢"],"answer":0,"explanation":"Khuôn kết thúc bằng 吧."},{"context":"“… tiền tiết kiệm được coi như là phong bao lì xì lớn tặng mình.”","pre":"转机累就累点儿吧，节省下来的钱就","blank":"当","post":"是给自己的大红包了。","options":["当","把","让"],"answer":0,"explanation":"当 (dàng) = coi như (từ mới)."},{"type":"sort","context":"Sắp xếp: “Mệt thì mệt một chút, tiêu ít tiền hơn mà đi được nhiều nơi hơn.”","words":["累","就","累点儿吧","，","花更少的钱","去看更多的地方"],"answer":"累就累点儿吧，花更少的钱去看更多的地方。","explanation":"Adj就Adj点儿吧，+ lý do."},{"type":"sort","context":"Sắp xếp: “Xa thì xa thôi, ít nhất tiền thuê rẻ.”","words":["远就远吧","，","至少","房租","便宜"],"answer":"远就远吧，至少房租便宜。","explanation":"至少 (Bài 5) nêu lý do chấp nhận."},{"type":"sort","context":"Sắp xếp: “Chậm thì chậm một chút, an toàn là quan trọng nhất.”","words":["慢","就","慢点儿吧","，","安全","最重要"],"answer":"慢就慢点儿吧，安全最重要。","explanation":"……最重要 = lý do."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"贵就贵点儿吧，质量好最重要。","isCorrect":true,"correctVersion":"","explanation":"Đúng: Adj就Adj点儿吧 + lý do."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"累就累吧点儿，很值得。","isCorrect":false,"correctVersion":"累就累点儿吧，很值得。","explanation":"点儿 đứng trước 吧."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"远就很远吧，所以房租便宜。","isCorrect":false,"correctVersion":"远就远吧，至少房租便宜。","explanation":"Không thêm 很; vế sau dùng 至少, không dùng 所以."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chậm thì chậm một chút, an toàn là quan trọng nhất.","answer":"慢就慢点儿吧，安全最重要。","answerPy":"Màn jiù màn diǎnr ba, ānquán zuì zhòngyào.","explanation":"Adj就Adj点儿吧，……最重要."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đắt thì đắt một chút thôi, đồ tốt dùng được lâu.","answer":"贵就贵点儿吧，好东西可以用很久。","answerPy":"Guì jiù guì diǎnr ba, hǎo dōngxi kěyǐ yòng hěn jiǔ.","explanation":"贵就贵点儿吧 + lý do chấp nhận."}]},{"point":"假设复句“要是……，（就）……，否则……” — nếu … thì …, nếu không thì …","items":[{"context":"“Các em nếu muốn hiểu thêm về Trung Quốc thì …”","pre":"你们","blank":"要是","post":"想多了解中国，就不能只通过读书。","options":["要是","即使","难道"],"answer":0,"explanation":"Giả thiết + 就 → 要是……就……"},{"context":"“… nếu không thì tớ chẳng đi đâu cả.”","pre":"要是出去的话，咱们就爬山，","blank":"否则","post":"我哪儿都不去。","options":["否则","然后","于是"],"answer":0,"explanation":"否则 = nếu không thì."},{"context":"“… kế hoạch này được thông qua …”","pre":"要是你同意的话，这个计划就","blank":"通过","post":"，否则可能需要重新讨论。","options":["通过","解释","总结"],"answer":0,"explanation":"计划 + 通过 = thông qua kế hoạch."},{"context":"“Nếu tắc đường thì các bạn đổi sang tàu điện ngầm …” (ôn 来不及 – Bài 4)","pre":"要是路上堵车，你们","blank":"就","post":"改乘地铁，否则会来不及的。","options":["就","才","也"],"answer":0,"explanation":"要是……，(主语) + 就……"},{"context":"“… nếu không thì rất khó đặt được.”","pre":"节假日要是想出去玩，就得早点儿订机票，否则很难订","blank":"到","post":"。","options":["到","完","住"],"answer":0,"explanation":"订到 = đặt được (bổ ngữ kết quả 到)."},{"type":"sort","context":"Sắp xếp: “Nếu bạn đồng ý thì kế hoạch này thông qua, nếu không phải thảo luận lại.”","words":["要是","你同意的话","，","这个计划","就通过","，","否则","需要重新讨论"],"answer":"要是你同意的话，这个计划就通过，否则需要重新讨论。","explanation":"要是……，就……，否则……"},{"type":"sort","context":"Sắp xếp: “Nếu tắc đường thì các bạn đổi sang tàu điện ngầm, nếu không sẽ không kịp.”","words":["要是","路上堵车","，","你们就","改乘地铁","，","否则","会来不及的"],"answer":"要是路上堵车，你们就改乘地铁，否则会来不及的。","explanation":"否则 + 会……的 (hậu quả)."},{"type":"sort","context":"Sắp xếp: “Nếu muốn nói lưu loát thì phải luyện nói mỗi ngày, nếu không sẽ quên.”","words":["要是","想说得流利","，","就得","每天练口语","，","否则","会忘的"],"answer":"要是想说得流利，就得每天练口语，否则会忘的。","explanation":"就得 (děi) = thì phải."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"要是出去的话，咱们就爬山，否则我哪儿都不去。","isCorrect":true,"correctVersion":"","explanation":"Đúng: đủ ba vế 要是……就……否则……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"要是下雨，你们就关上窗户，但是雨水会进到房间里。","isCorrect":false,"correctVersion":"要是下雨，你们就关上窗户，否则雨水会进到房间里。","explanation":"“Nếu không thì” → 否则, không dùng 但是."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"要是天气好，否则我们去爬山。","isCorrect":false,"correctVersion":"要是天气好，我们就去爬山，否则就在家学习。","explanation":"Thiếu vế 就; 否则 nói hậu quả ở vế thứ ba."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nếu bạn muốn hiểu Trung Quốc thì phải đi du lịch nhiều, nếu không chỉ biết một Trung Quốc trong sách.","answer":"要是你想了解中国，就要多出门旅行，否则只能认识书里的中国。","answerPy":"Yàoshi nǐ xiǎng liǎojiě Zhōngguó, jiù yào duō chūmén lǚxíng, fǒuzé zhǐnéng rènshi shū lǐ de Zhōngguó.","explanation":"要是……就……，否则只能……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nếu không khỏe thì về nhà nghỉ sớm đi, nếu không bệnh sẽ ngày càng nặng.","answer":"要是不舒服，就早点儿回家休息吧，否则病会越来越厉害。","answerPy":"Yàoshi bù shūfu, jiù zǎodiǎnr huíjiā xiūxi ba, fǒuzé bìng huì yuèláiyuè lìhai.","explanation":"否则 + 会 + hậu quả; ôn 厉害 (Bài 6)."}]}],"/lessons/hsk4v3-bai-3.html":[{"point":"转折复句“……×是×，就是/不过……” — … thì … thật, nhưng / chỉ là …","items":[{"context":"“Bắc Kinh to thì to thật, nhưng …”","pre":"北京大是","blank":"大","post":"，不过这边的路基本上都是正南正北的。","options":["大","很大","太大"],"answer":0,"explanation":"Hai bên 是 lặp lại đúng một từ: 大是大."},{"context":"“Căn nhà này rẻ thì rẻ thật, chỉ là cách công ty xa quá.”","pre":"这个房子便宜是便宜，","blank":"就是","post":"离我的公司太远了。","options":["就是","所以","因为"],"answer":0,"explanation":"Vế sau dùng 就是 / 不过 chỉ ra hạn chế."},{"context":"“Chúng tôi nghĩ thì có nghĩ rồi …”","pre":"我们想是","blank":"想","post":"了，就是没想出更好的办法。","options":["想","想想","想到"],"answer":0,"explanation":"想是想了 — 了 ở cuối khung."},{"context":"“… chỉ là dễ tiêu tiền lung tung.” (ôn từ mới)","pre":"网购方便是方便，就是容易","blank":"乱","post":"花钱。","options":["乱","正","直接"],"answer":0,"explanation":"乱花钱 = tiêu tiền lung tung."},{"context":"“Mát thì mát rồi, có điều mùa hè chưa hết …”","pre":"凉快是凉快了，","blank":"不过","post":"夏天还没结束，过几天又会热起来了。","options":["不过","于是","甚至"],"answer":0,"explanation":"×是×，不过……"},{"type":"sort","context":"Sắp xếp: “Cái áo này đẹp thì đẹp thật, chỉ là hơi đắt.”","words":["这件衣服","好看","是","好看","，","就是","有点儿贵"],"answer":"这件衣服好看是好看，就是有点儿贵。","explanation":"A是A，就是……"},{"type":"sort","context":"Sắp xếp: “Phần mềm này tiện thì tiện thật, nhưng tôi vẫn chưa biết dùng lắm.”","words":["这个软件","方便","是","方便","，","不过","我还不太会用"],"answer":"这个软件方便是方便，不过我还不太会用。","explanation":"A是A，不过……"},{"type":"sort","context":"Sắp xếp: “Bài tập viết xong thì viết xong rồi, nhưng có câu không biết làm.”","words":["作业","写完","是","写完了","，","不过","有的题","不会写"],"answer":"作业写完是写完了，不过有的题不会写。","explanation":"Cụm động từ: 写完是写完了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"北京大是很大，不过路很好找。","isCorrect":false,"correctVersion":"北京大是大，不过路很好找。","explanation":"Hai bên 是 giống hệt nhau, không thêm 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这家饭馆的菜好吃是好吃，就是价格有点儿高。","isCorrect":true,"correctVersion":"","explanation":"Đúng: A是A，就是……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我累是累，所以还想再学一会儿。","isCorrect":false,"correctVersion":"我累是累，不过还想再学一会儿。","explanation":"Vế sau là chuyển ngoặt → 不过 / 就是, không dùng 所以."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Điện thoại này đẹp thì đẹp thật, chỉ là hơi đắt.","answer":"这个手机好看是好看，就是有点儿贵。","answerPy":"Zhège shǒujī hǎokàn shì hǎokàn, jiùshì yǒudiǎnr guì.","explanation":"A是A，就是 / 不过……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi muốn đi thì muốn thật, có điều hôm nay không có thời gian.","answer":"我想去是想去，不过今天没有时间。","answerPy":"Wǒ xiǎng qù shì xiǎng qù, búguò jīntiān méiyǒu shíjiān.","explanation":"Cụm động từ 想去是想去."}]},{"point":"递进复句“不仅/不光……，还/而且……” — không những … mà còn …","items":[{"context":"“Giờ tôi không những biết quét mã thanh toán …”","pre":"现在我","blank":"不仅","post":"会扫码结账，还会用手机在网上购物了。","options":["不仅","虽然","要是"],"answer":0,"explanation":"不仅……，还……"},{"context":"“… mà còn đưa chúng tôi tìm hiểu văn hóa.”","pre":"王老师不光教我们说中文，","blank":"而且","post":"带我们了解中国文化。","options":["而且","但是","所以"],"answer":0,"explanation":"不光……，而且……"},{"context":"“… mà còn bán cà phê và trà sữa.”","pre":"现在很多书店不仅卖书，","blank":"还","post":"卖咖啡和奶茶。","options":["还","就","才"],"answer":0,"explanation":"还 đứng ngay trước động từ 卖."},{"context":"“… mà còn gửi được chuyển phát nhanh.” (ôn từ mới)","pre":"这个软件不仅能支付，还能","blank":"寄","post":"快递。","options":["寄","管","转"],"answer":0,"explanation":"寄快递 = gửi chuyển phát nhanh."},{"context":"“… mà giao hàng còn nhanh.”","pre":"在中国网购，不仅选择多、价格不高，","blank":"而且","post":"送货很快。","options":["而且","于是","不过"],"answer":0,"explanation":"不仅……，而且……"},{"type":"sort","context":"Sắp xếp: “Cô ấy không những biết hát bài tiếng Trung, mà còn hát rất hay.”","words":["她","不仅","会唱","中文歌","，","而且","唱得很好"],"answer":"她不仅会唱中文歌，而且唱得很好。","explanation":"Chủ ngữ + 不仅……，而且……"},{"type":"sort","context":"Sắp xếp: “Tôi không những biết quét mã thanh toán, mà còn biết mua online.”","words":["我","不仅","会","扫码结账","，","还","会","网购"],"answer":"我不仅会扫码结账，还会网购。","explanation":"还 + 会 + V."},{"type":"sort","context":"Sắp xếp: “Quán này không những món ngon mà giá cũng không cao.”","words":["这家饭馆","不光","菜好吃","，","而且","价格","也不高"],"answer":"这家饭馆不光菜好吃，而且价格也不高。","explanation":"而且……也……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不仅他会说中文，还会说英文。","isCorrect":false,"correctVersion":"他不仅会说中文，还会说英文。","explanation":"Cùng chủ ngữ → chủ ngữ đứng trước 不仅."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"现在很多书店不仅卖书，还卖咖啡和奶茶。","isCorrect":true,"correctVersion":"","explanation":"Đúng: chủ ngữ + 不仅……，还……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她不仅很漂亮，但是很聪明。","isCorrect":false,"correctVersion":"她不仅很漂亮，而且很聪明。","explanation":"不仅 đi với 而且 / 还, không đi với 但是."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thanh toán bằng điện thoại không những nhanh mà còn rất tiện.","answer":"用手机支付不仅很快，而且很方便。","answerPy":"Yòng shǒujī zhīfù bùjǐn hěn kuài, érqiě hěn fāngbiàn.","explanation":"不仅……，而且 / 还……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cậu ấy không những giúp tôi tải WeChat, mà còn dạy tôi cách dùng.","answer":"他不仅帮我下载了微信，还教我怎么用。","answerPy":"Tā bùjǐn bāng wǒ xiàzài le Wēixìn, hái jiào wǒ zěnme yòng.","explanation":"Chủ ngữ 他 đứng trước 不仅."}]},{"point":"连词“甚至” — thậm chí, ngay cả","items":[{"context":"“… nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm.”","pre":"在中国网购，送货很快，很多留学生","blank":"甚至","post":"改变了自己的购物习惯。","options":["甚至","不仅","于是"],"answer":0,"explanation":"甚至 + V: nhấn mạnh điều vượt dự đoán."},{"context":"“Tàu cao tốc nhanh thật, thậm chí chưa nhìn rõ …”","pre":"高铁速度真快，","blank":"甚至","post":"还没看清楚，它就已经开过去了。","options":["甚至","虽然","要是"],"answer":0,"explanation":"甚至 đứng trước phần được nhấn mạnh."},{"context":"“… thậm chí còn có một siêu thị.”","pre":"这个小区真不错，有小花园、球场，甚至","blank":"还","post":"有一个超市。","options":["还","就","才"],"answer":0,"explanation":"甚至还 + 有……"},{"context":"“… thậm chí ngay cả thời gian ăn cơm cũng không có.”","pre":"他太忙了，甚至","blank":"连","post":"吃饭的时间都没有。","options":["连","把","被"],"answer":0,"explanation":"甚至连……都……"},{"context":"“… thậm chí nhiều người nổi tiếng cũng đến uống.”","pre":"这家咖啡店很有名，甚至很多","blank":"名人","post":"都会来喝咖啡。","options":["名人","手指","现金"],"answer":0,"explanation":"名人 = người nổi tiếng."},{"type":"sort","context":"Sắp xếp: “Anh ấy hiểu tôi quá, thậm chí tôi chưa nói anh ấy đã biết tôi muốn làm gì.”","words":["他","太了解我了","，","甚至","我还没说话","，","他就知道","我想做什么"],"answer":"他太了解我了，甚至我还没说话，他就知道我想做什么。","explanation":"甚至 + câu ngắn (还没……就……)."},{"type":"sort","context":"Sắp xếp: “Khu này có vườn hoa, sân bóng, thậm chí còn có một siêu thị.”","words":["这个小区","有小花园、球场","，","甚至","还有","一个超市"],"answer":"这个小区有小花园、球场，甚至还有一个超市。","explanation":"Liệt kê: 甚至 trước mục cuối."},{"type":"sort","context":"Sắp xếp: “Anh ấy bận đến mức thậm chí quên cả ăn cơm.”","words":["他","忙得","甚至","连饭","都","忘了吃"],"answer":"他忙得甚至连饭都忘了吃。","explanation":"V得 + 甚至连……都……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"甚至在中国寄快递很快。","isCorrect":false,"correctVersion":"在中国寄快递特别快，甚至上午寄出下午就收到了。","explanation":"甚至 không mở đầu câu; phần sau 甚至 phải vượt dự đoán."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他中文说得很好，甚至能看懂中文报纸。","isCorrect":true,"correctVersion":"","explanation":"Đúng: đọc hiểu báo là mức cao hơn nói tốt."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他每天起得很早，甚至七点起床。","isCorrect":false,"correctVersion":"他每天起得很早，甚至五点就起床了。","explanation":"Phần sau 甚至 phải nổi bật hơn hẳn; 7 giờ không “sớm” đến mức bất ngờ, thêm 就……了 nhấn mạnh."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Ở Trung Quốc mọi người đều dùng điện thoại trả tiền, thậm chí mua một chai nước cũng quét mã.","answer":"在中国大家都用手机支付，甚至买一瓶水也扫码。","answerPy":"Zài Zhōngguó dàjiā dōu yòng shǒujī zhīfù, shènzhì mǎi yì píng shuǐ yě sǎomǎ.","explanation":"甚至 + phần bất ngờ + 也 / 都."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Anh ấy bận lắm, thậm chí cuối tuần cũng phải đi làm.","answer":"他很忙，甚至周末也要上班。","answerPy":"Tā hěn máng, shènzhì zhōumò yě yào shàngbān.","explanation":"甚至 + 周末也……"}]},{"point":"承接复句“……，于是……” — …, thế là …","items":[{"context":"“… thế là có người nói ra nỗi lo trên mạng.”","pre":"我们担心个人信息能否得到保护，","blank":"于是","post":"有人在网上说出了自己的担心。","options":["于是","甚至","不仅"],"answer":0,"explanation":"于是 đứng đầu vế sau."},{"context":"“… thế là lên đại học chọn học y.”","pre":"她从小就想当医生，于是上大学时就选择了学","blank":"医","post":"。","options":["医","法律","技术"],"answer":0,"explanation":"学医 = học y; 当医生 ôn Bài 1."},{"context":"“… quyết định khỏi bệnh sẽ tập thể dục.”","pre":"最近总感冒，于是他决定病好后就开始","blank":"锻炼","post":"身体。","options":["锻炼","保护","改变"],"answer":0,"explanation":"锻炼身体 = rèn luyện thân thể (HSK 3)."},{"context":"“… thế là tôi cũng không muốn nói nữa.”","pre":"大家都不说话，于是我","blank":"也","post":"不想说话了。","options":["也","才","再"],"answer":0,"explanation":"于是 + chủ ngữ + 也……"},{"context":"“… thế là tôi đi thư viện một mình.” (综合练习 3)","pre":"在十字路口等了半个小时，他们也没来，","blank":"于是","post":"我就一个人去图书馆了。","options":["于是","而且","甚至"],"answer":0,"explanation":"于是……就……"},{"type":"sort","context":"Sắp xếp: “Tôi rất mệt, thế là về nhà nghỉ.”","words":["我","很累","，","于是","就","回家","休息了"],"answer":"我很累，于是就回家休息了。","explanation":"……，于是就……"},{"type":"sort","context":"Sắp xếp: “Anh ấy không thạo đường, thế là hỏi đường một bạn học.”","words":["他","不熟悉路","，","于是","向","一位同学","问路"],"answer":"他不熟悉路，于是向一位同学问路。","explanation":"于是 + 向 + ai + V."},{"type":"sort","context":"Sắp xếp: “Điện thoại hết pin, thế là tôi trả bằng tiền mặt.”","words":["手机没电了","，","于是","我","用现金","结了账"],"answer":"手机没电了，于是我用现金结了账。","explanation":"于是 + chủ ngữ 我 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"于是天黑了，我们回家了。","isCorrect":false,"correctVersion":"天黑了，于是我们回家了。","explanation":"于是 đứng đầu vế sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他想学好中文，于是来中国留学了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: việc trước dẫn đến việc sau, đã xảy ra."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"天冷了，于是你多穿点儿衣服吧。","isCorrect":false,"correctVersion":"天冷了，你多穿点儿衣服吧。","explanation":"Câu khuyên → không dùng 于是 (có thể dùng 所以)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi không biết dùng WeChat, thế là bạn Trung Quốc dạy tôi.","answer":"我不会用微信，于是中国朋友教我。","answerPy":"Wǒ bú huì yòng Wēixìn, yúshì Zhōngguó péngyou jiào wǒ.","explanation":"……，于是……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Mua online quá tiện, thế là cô ấy hay tiêu tiền lung tung.","answer":"网购太方便了，于是她常常乱花钱。","answerPy":"Wǎnggòu tài fāngbiàn le, yúshì tā chángcháng luàn huāqián.","explanation":"于是 + chủ ngữ + V; từ mới 网购, 乱."}]}],"/lessons/hsk4v3-bai-4.html":[{"point":"可能补语“动词+得/不+了” — làm được / không làm được","items":[{"context":"“Điện thoại không có sóng, không lên mạng được.”","pre":"手机没有信号，上","blank":"不了","post":"网。","options":["不了","得了","不能"],"answer":0,"explanation":"上网 là từ ly hợp → 上不了网."},{"context":"“Hôm nay cô ấy không đến được nữa.”","pre":"她刚才给我发信息，说她今天来","blank":"不了","post":"了。","options":["不了","得了","没有"],"answer":0,"explanation":"来不了 = không đến được; 了 cuối câu báo sự thay đổi."},{"context":"“… có tham gia được không?”","pre":"明天的足球比赛，你们班男生参加","blank":"得了","post":"吗？","options":["得了","了得","得不"],"answer":0,"explanation":"Hỏi khả năng: V + 得了 + 吗？"},{"context":"“Món gọi không nhiều, ăn hết được.”","pre":"咱们点的菜不多，吃","blank":"得了","post":"。","options":["得了","不了","了"],"answer":0,"explanation":"菜不多 → 吃得了 (ăn hết được)."},{"context":"“Mất ví rồi, không mua được vé tàu điện ngầm.”","pre":"我的钱包丢了，买","blank":"不了","post":"地铁票了。","options":["不了","得了","不能"],"answer":0,"explanation":"买不了 + tân ngữ."},{"type":"sort","context":"Sắp xếp: “Điện thoại không có sóng, tôi không lên mạng được.”","words":["手机","没有信号","，","我","上不了","网"],"answer":"手机没有信号，我上不了网。","explanation":"上 + 不了 + 网."},{"type":"sort","context":"Sắp xếp: “Mai bạn có đến được không?”","words":["明天","你","来得了","来不了","？"],"answer":"明天你来得了来不了？","explanation":"Câu hỏi chính phản: V得了V不了？"},{"type":"sort","context":"Sắp xếp: “Nhiều món thế này, chúng mình ăn hết được không?”","words":["这么多","菜","，","咱们","吃得了","吗","？"],"answer":"这么多菜，咱们吃得了吗？","explanation":"V得了吗？"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我今天有点儿事，去不了你家了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 去不了 + nơi chốn + 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"雨太大了，我们出门不了。","isCorrect":false,"correctVersion":"雨太大了，我们出不了门。","explanation":"出门 là từ ly hợp: 出不了门."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他病了，明天不能来不了。","isCorrect":false,"correctVersion":"他病了，明天来不了。","explanation":"Bỏ 不能 — không phủ định hai lần."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Điện thoại tôi hết pin rồi, không quét mã được.","answer":"我的手机没电了，扫不了码。","answerPy":"Wǒ de shǒujī méi diàn le, sǎo bu le mǎ.","explanation":"扫码 là từ ly hợp → 扫不了码."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bài tập nhiều thế này, một ngày bạn làm xong được không?","answer":"这么多作业，你一天做得了吗？","answerPy":"Zhème duō zuòyè, nǐ yì tiān zuò de liǎo ma?","explanation":"V得了吗？ hỏi khả năng hoàn thành."}]},{"point":"连词“再说” — vả lại, hơn nữa","items":[{"context":"“… vả lại hàng xóm với nhau phải giúp nhau.”","pre":"我提着这些东西就算锻炼身体了，","blank":"再说","post":"邻居之间就是要互相帮助啊。","options":["再说","不过","于是"],"answer":0,"explanation":"再说 bổ sung lý do thứ hai."},{"context":"“… vả lại ngoài trời vẫn đang mưa đấy.”","pre":"今天太晚了，别去超市了，再说外面还在下雨","blank":"呢","post":"。","options":["呢","吗","吧"],"answer":0,"explanation":"还在 + V + 呢: sự việc đang tiếp diễn (HSK 2/3)."},{"context":"“… vả lại đông người cũng vui hơn.”","pre":"你今天正好有时间，再说人多","blank":"也","post":"更热闹。","options":["也","就","才"],"answer":0,"explanation":"Vế 再说 hay có 也 / 还."},{"context":"“… coi như là tập thể dục rồi.” (ôn từ mới)","pre":"我提着这些东西就","blank":"算","post":"锻炼身体了。","options":["算","像","变"],"answer":0,"explanation":"就算……了 = coi như là."},{"context":"“… vả lại bạn đã có nhiều áo rồi.”","pre":"别买这件了，太贵了，","blank":"再说","post":"你已经有很多衣服了。","options":["再说","不过","甚至"],"answer":0,"explanation":"Hai lý do cùng chiều (đắt + đã có nhiều) → 再说."},{"type":"sort","context":"Sắp xếp: “Hôm nay muộn quá rồi, vả lại ngoài trời vẫn đang mưa.”","words":["今天","太晚了","，","再说","外面","还在下雨呢"],"answer":"今天太晚了，再说外面还在下雨呢。","explanation":"Lý do 1，再说 + lý do 2."},{"type":"sort","context":"Sắp xếp: “Căn nhà này gần trường, vả lại tiền thuê cũng không đắt.”","words":["这个房子","离学校很近","，","再说","房租","也不贵"],"answer":"这个房子离学校很近，再说房租也不贵。","explanation":"再说 + chủ ngữ + 也 + …"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"咱们打车去吧，时间不多了，再说东西也很多。","isCorrect":true,"correctVersion":"","explanation":"Đúng: hai lý do cùng chiều (ít thời gian + nhiều đồ) → đi taxi."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服很漂亮，再说太贵了，我不买了。","isCorrect":false,"correctVersion":"这件衣服很漂亮，不过太贵了，我不买了。","explanation":"Hai ý trái chiều → dùng 不过 (Bài 2 · điểm 2)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"再说外面很冷，你别出去了。","isCorrect":false,"correctVersion":"已经很晚了，再说外面很冷，你别出去了。","explanation":"再说 không mở đầu khi chưa có lý do thứ nhất."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chúng mình đi tàu điện ngầm đi, nhanh, vả lại cũng không đắt.","answer":"咱们坐地铁去吧，很快，再说也不贵。","answerPy":"Zánmen zuò dìtiě qù ba, hěn kuài, zàishuō yě bú guì.","explanation":"Lý do 1，再说 + 也 + lý do 2."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đừng khách sáo, việc này rất đơn giản, vả lại hàng xóm với nhau nên giúp đỡ lẫn nhau.","answer":"别客气，这件事很简单，再说邻居之间应该互相帮助。","answerPy":"Bié kèqi, zhè jiàn shì hěn jiǎndān, zàishuō línjū zhījiān yīnggāi hùxiāng bāngzhù.","explanation":"再说 + từ mới 之间, 互相."}]},{"point":"并列复句“既……，又/也……” — vừa … vừa …","items":[{"context":"“Cô ấy thấy như vậy vừa tiện, vừa …”","pre":"她觉得这样","blank":"既","post":"方便，又能锻炼身体。","options":["既","也","还"],"answer":0,"explanation":"Vế đầu dùng 既."},{"context":"“… vừa ngon vừa rẻ.”","pre":"这家饭馆的菜既好吃，","blank":"又","post":"便宜。","options":["又","再","就"],"answer":0,"explanation":"既……又……"},{"context":"“… cũng học được kiến thức lịch sử.”","pre":"我很喜欢这门课程，既能提高中文水平，","blank":"也","post":"能学到历史知识。","options":["也","都","才"],"answer":0,"explanation":"既……也…… (vế sau là cụm động từ)."},{"context":"“… lại còn bảo vệ được môi trường.”","pre":"她觉得骑车既方便，又能锻炼身体，","blank":"还","post":"能保护环境。","options":["还","既","就"],"answer":0,"explanation":"Ý thứ ba dùng 还."},{"context":"“… sạc điện cũng rất tiện.” (ôn từ mới)","pre":"电动车速度快，价格不高，","blank":"充电","post":"也很方便。","options":["充电","速度","力气"],"answer":0,"explanation":"充电 = sạc điện."},{"type":"sort","context":"Sắp xếp: “Món ăn ở nhà hàng này vừa ngon vừa rẻ.”","words":["这家","饭馆的菜","既","好吃","又","便宜"],"answer":"这家饭馆的菜既好吃又便宜。","explanation":"Chủ ngữ + 既 + A + 又 + B."},{"type":"sort","context":"Sắp xếp: “Đi xe đạp vừa rèn luyện thân thể, cũng bảo vệ được môi trường.”","words":["骑自行车","既","能锻炼身体","，","也","能保护环境"],"answer":"骑自行车既能锻炼身体，也能保护环境。","explanation":"既……也……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他既是我的老师，也是我的朋友。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 既是……也是……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"既他会说汉语，又他会说英语。","isCorrect":false,"correctVersion":"他既会说汉语，又会说英语。","explanation":"既 / 又 đứng sau chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服既漂亮，又不好看。","isCorrect":false,"correctVersion":"这件衣服既漂亮，又便宜。","explanation":"Hai ý mâu thuẫn — phải cùng chiều."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Xe điện vừa nhanh vừa rẻ, nên ngày càng thịnh hành.","answer":"电动车既快又便宜，所以越来越流行。","answerPy":"Diàndòngchē jì kuài yòu piányi, suǒyǐ yuèláiyuè liúxíng.","explanation":"既……又…… + 流行."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đi tàu điện ngầm vừa không bị tắc đường, vừa tiết kiệm được thời gian.","answer":"坐地铁既不堵车，又能省时间。","answerPy":"Zuò dìtiě jì bù dǔchē, yòu néng shěng shíjiān.","explanation":"既……又 / 也…… + 省."}]},{"point":"固定短语“来得及/来不及” — kịp / không kịp","items":[{"context":"“Người không kịp ăn sáng …”","pre":"没","blank":"来得及","post":"吃早饭的人在这里就能买到热包子。","options":["来得及","来不及","不来及"],"answer":0,"explanation":"没来得及 + V (✗ 没来不及)."},{"context":"“… tôi không kịp thông báo cho mọi người nữa.”","pre":"你现在才告诉我，我","blank":"来不及","post":"通知大家了。","options":["来不及","来得及","没来得及"],"answer":0,"explanation":"来不及 + V + 了."},{"context":"“… 9 giờ xuất phát có kịp không?”","pre":"中午12点的飞机，咱们9点出发","blank":"来得及","post":"吗？","options":["来得及","来不及了","没来得及"],"answer":0,"explanation":"Hỏi: ……来得及吗？"},{"context":"“… kịp ăn sáng.”","pre":"别着急，还有15分钟，咱们来得及吃","blank":"早饭","post":"。","options":["早饭","速度","乘客"],"answer":0,"explanation":"来得及 + V + O."},{"context":"“… bạn không kịp đi tàu điện ngầm về nữa …”","pre":"时间太晚了，你","blank":"来不及","post":"坐地铁回去了，就住在我们这儿吧。","options":["来不及","来得及","没来得及"],"answer":0,"explanation":"来不及 + V + 了."},{"type":"sort","context":"Sắp xếp: “Còn nửa tiếng, chúng mình kịp ăn sáng.”","words":["还有","半个小时","，","咱们","来得及","吃早饭"],"answer":"还有半个小时，咱们来得及吃早饭。","explanation":"来得及 + V."},{"type":"sort","context":"Sắp xếp: “Sáng nay tôi chưa kịp ăn sáng đã đi làm rồi.”","words":["我","早上","没来得及","吃早饭","就","去上班了"],"answer":"我早上没来得及吃早饭就去上班了。","explanation":"没来得及 + V + 就……了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"现在出发还来得及。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 还来得及 = vẫn còn kịp."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"昨天我没来不及跟你说再见。","isCorrect":false,"correctVersion":"昨天我没来得及跟你说再见。","explanation":"Việc đã qua: 没来得及."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"飞机十点起飞，现在已经九点半了，来得及不了。","isCorrect":false,"correctVersion":"飞机十点起飞，现在已经九点半了，来不及了。","explanation":"Phủ định là 来不及, không có 来得及不了."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Sáng nay tôi dậy muộn, không kịp ăn sáng.","answer":"今天早上我起晚了，没来得及吃早饭。","answerPy":"Jīntiān zǎoshang wǒ qǐwǎn le, méi láidejí chī zǎofàn.","explanation":"Việc đã qua → 没来得及 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Phim 8 giờ bắt đầu, bây giờ đi còn kịp không?","answer":"电影八点开始，现在去还来得及吗？","answerPy":"Diànyǐng bā diǎn kāishǐ, xiànzài qù hái láidejí ma?","explanation":"……，来得及吗？"}]}],"/lessons/hsk4v3-bai-5.html":[{"point":"范围副词“至少” — ít nhất, tối thiểu","items":[{"context":"“Cháu sang Trung Quốc ít nhất hai tháng rồi …”","pre":"家月，你来中国","blank":"至少","post":"两个月了，习惯吃中餐了吗？","options":["至少","专门","任何"],"answer":0,"explanation":"至少 + cụm thời gian."},{"context":"“Mỗi năm có ít nhất hai trăm du học sinh …”","pre":"每年至少","blank":"有","post":"两百名留学生来我校学习中文专业。","options":["有","是","在"],"answer":0,"explanation":"至少 + 有 + số lượng."},{"context":"“Tuy chưa gặp mặt, nhưng ít ra cũng đã trò chuyện trên mạng nhiều lần.”","pre":"我们虽然没有见过面，","blank":"但","post":"至少在网上聊过很多次。","options":["但","就","于是"],"answer":0,"explanation":"虽然……，但至少…… — ôn 虽然……但是…… (HSK 3)."},{"context":"“Đi xe đạp điện ít nhất cũng nhanh được mười phút.”","pre":"骑电动车至少","blank":"能","post":"快十分钟。","options":["能","敢","够"],"answer":0,"explanation":"至少 + 能 + V + số lượng."},{"context":"“Cũ thì cũ, nhưng ít ra cũng sạch.” (ôn Bài 3)","pre":"这个房子旧是旧，","blank":"不过","post":"至少很干净。","options":["不过","因为","要是"],"answer":0,"explanation":"×是×，不过至少…… — ôn Bài 3 · điểm 1."},{"type":"sort","context":"Sắp xếp: “Mỗi ngày tôi học ít nhất hai tiếng.”","words":["我","每天","至少","学习","两个小时"],"answer":"我每天至少学习两个小时。","explanation":"Chủ ngữ + thời gian + 至少 + V + thời lượng."},{"type":"sort","context":"Sắp xếp: “Năm nhất cao học phải chọn ít nhất ba môn.”","words":["研究生一年级","至少","要","选","三门课"],"answer":"研究生一年级至少要选三门课。","explanation":"至少 + 要 + V + số lượng."},{"type":"sort","context":"Sắp xếp: “Căn nhà này cũ thì cũ, nhưng ít ra cũng sạch.”","words":["这个","房子","旧是旧","，","不过","至少","很干净"],"answer":"这个房子旧是旧，不过至少很干净。","explanation":"Ôn ×是×，不过…… + 至少."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我每天睡觉八个小时至少。","isCorrect":false,"correctVersion":"我每天至少睡八个小时。","explanation":"至少 không đứng cuối câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"每年至少有两百名留学生来我校学习。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 至少 + 有 + số lượng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他至少的朋友有十个。","isCorrect":false,"correctVersion":"他至少有十个朋友。","explanation":"至少 là phó từ, không thêm 的 làm định ngữ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Muốn học giỏi tiếng Trung, mỗi ngày ít nhất phải học một tiếng.","answer":"要想学好中文，每天至少要学习一个小时。","answerPy":"Yào xiǎng xuéhǎo Zhōngwén, měitiān zhìshǎo yào xuéxí yí gè xiǎoshí.","explanation":"至少 + 要 + V + thời lượng."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi đã đến Bắc Kinh ít nhất năm lần rồi.","answer":"我至少来过北京五次了。","answerPy":"Wǒ zhìshǎo lái guò Běijīng wǔcì le.","explanation":"至少 + V过 + số lần."}]},{"point":"副词/动词“够” — thật là …; đủ","items":[{"context":"“Trình độ tiếng Trung của cậu cao thật đấy!”","pre":"你的中文水平","blank":"够","post":"高的，这都听懂了！","options":["够","不够","至少"],"answer":0,"explanation":"够 + Adj + 的 = thật là …"},{"context":"“Vẫn chưa đủ ngọt, thêm chút đường đi.”","pre":"我尝了一下，还","blank":"不够","post":"甜，再加一点儿糖吧。","options":["不够","够","至少"],"answer":0,"explanation":"不够 + Adj = chưa đủ …"},{"context":"“Bốn món có đủ không?”","pre":"明天请家月和李文来家里吃饭，四个菜","blank":"够不够","post":"？","options":["够不够","够没够","不够够"],"answer":0,"explanation":"Câu hỏi chính phản: 够不够."},{"context":"“Hôm nay trời lạnh thật đấy, mặc thêm áo vào.”","pre":"今天的天气够冷","blank":"的","post":"，多穿点儿衣服吧。","options":["的","了","吗"],"answer":0,"explanation":"Khung cố định 够……的."},{"context":"“… thời gian không đủ.”","pre":"完成这个工作需要三天，现在只有两天，时间","blank":"不够","post":"。","options":["不够","够的","至少"],"answer":0,"explanation":"N + 不够 (động từ)."},{"type":"sort","context":"Sắp xếp: “Nhà bạn to thật đấy.”","words":["你家","房子","够","大","的"],"answer":"你家房子够大的。","explanation":"够 + Adj + 的."},{"type":"sort","context":"Sắp xếp: “Cái thùng này không đủ to, không để vừa nhiều đồ thế.”","words":["这个","箱子","不够大","，","放不下","这么多东西"],"answer":"这个箱子不够大，放不下这么多东西。","explanation":"不够 + Adj + bổ ngữ khả năng 放不下."},{"type":"sort","context":"Sắp xếp: “Tôi nếm thử rồi, vẫn chưa đủ ngọt.”","words":["我","尝了一下","，","还","不够","甜"],"answer":"我尝了一下，还不够甜。","explanation":"还 + 不够 + Adj."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个箱子够不大，放不下这么多东西。","isCorrect":false,"correctVersion":"这个箱子不够大，放不下这么多东西。","explanation":"Phủ định: 不够 + Adj."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你的中文水平够高的，这都听懂了！","isCorrect":true,"correctVersion":"","explanation":"Đúng: 够……的 cảm thán."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们只有两个人，三个菜够了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 够 làm động từ — đủ (số lượng)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Món này vẫn chưa đủ cay, cho thêm chút ớt nữa đi.","answer":"这道菜还不够辣，再放一点儿辣椒吧。","answerPy":"Zhè dào cài hái búgòu là, zài fàng yìdiǎnr làjiāo ba.","explanation":"不够 + Adj; từ mới 辣椒."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Hôm nay trời nóng thật đấy!","answer":"今天天气够热的！","answerPy":"Jīntiān tiānqì gòu rè de!","explanation":"够 + Adj + 的."}]},{"point":"固定格式“各×各的” — ai … nấy, mỗi người tự …","items":[{"context":"“… vẫn là ai trả phần nấy thì hợp hơn.”","pre":"大家觉得还是各付","blank":"各","post":"的更合适。","options":["各","自己","每"],"answer":0,"explanation":"各 + V + 各 + 的."},{"context":"“… ai bận việc nấy.”","pre":"到了办公室，大家就开始各","blank":"忙","post":"各的了。","options":["忙","付","坐"],"answer":0,"explanation":"各忙各的."},{"context":"“… ai đọc sách nấy.”","pre":"在图书馆里，大家都很安静，各看各的","blank":"书","post":"。","options":["书","饭","菜"],"answer":0,"explanation":"各V各的 + danh từ."},{"context":"“Khẩu vị họ khác nhau, thế là mỗi người ăn phần mình.” (ôn Bài 3)","pre":"他们口味不同，","blank":"于是","post":"就各吃各的。","options":["于是","甚至","不仅"],"answer":0,"explanation":"于是 nối kết quả — Bài 3 · điểm 4."},{"context":"“… mỗi người mua một kiểu.”","pre":"他们想买的东西不一样，到了商场以后就各买","blank":"各的","post":"了。","options":["各的","自己","他的"],"answer":0,"explanation":"各买各的."},{"type":"sort","context":"Sắp xếp: “Mọi người thấy vẫn là ai trả phần nấy thì hợp hơn.”","words":["大家","觉得","还是","各付各的","更合适"],"answer":"大家觉得还是各付各的更合适。","explanation":"还是……更合适 + 各付各的."},{"type":"sort","context":"Sắp xếp: “Đến văn phòng, mọi người bắt đầu ai bận việc nấy.”","words":["到了","办公室","，","大家","就","开始","各忙各的了"],"answer":"到了办公室，大家就开始各忙各的了。","explanation":"Chủ ngữ số nhiều + 就 + 各V各的."},{"type":"sort","context":"Sắp xếp: “Thầy nói xong, mọi người ai làm bài nấy.”","words":["老师","说完","以后","，","大家","就","各做各的"],"answer":"老师说完以后，大家就各做各的。","explanation":"……以后，大家就各V各的."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我各吃各的。","isCorrect":false,"correctVersion":"我们各吃各的。","explanation":"Chủ ngữ phải là nhiều người."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在图书馆里，大家都很安静，各看各的书。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 各看各的 + 书."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他们各的做各的。","isCorrect":false,"correctVersion":"他们各做各的。","explanation":"Không có 的 sau 各 thứ nhất."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bạn bè đi ăn với nhau, chúng tôi thường ai trả phần nấy.","answer":"朋友一起吃饭，我们一般各付各的。","answerPy":"Péngyou yìqǐ chīfàn, wǒmen yìbān gè fù gè de.","explanation":"各付各的 + từ mới 聚餐."}]},{"point":"介词“等” — đợi đến khi, chờ đến lúc","items":[{"context":"“… người trẻ phải đợi người già ngồi xuống rồi mới ngồi.”","pre":"如果聚餐时有老人，年轻人要","blank":"等","post":"老人坐下后再坐。","options":["等","在","从"],"answer":0,"explanation":"等 + sự việc + 后，再 + V."},{"context":"“Đợi tớ làm xong bài rồi mới đi chơi với cậu.”","pre":"等我写完作业，","blank":"再","post":"跟你出去玩。","options":["再","又","还"],"answer":0,"explanation":"等……，再…… (việc chưa xảy ra)."},{"context":"“… tàu đã chạy mất rồi.”","pre":"等我们到火车站的时候，火车","blank":"已经","post":"开走了。","options":["已经","正在","马上"],"answer":0,"explanation":"等……的时候，已经……了."},{"context":"“Đừng vội, đợi tớ xong việc thì sẽ đi tìm cậu.”","pre":"别着急，等我忙完了","blank":"就","post":"去找你。","options":["就","才","也"],"answer":0,"explanation":"等……，就…… (đáp án gợi ý của sách)."},{"context":"“Đến lúc chúng tôi chạy tới thì đã không kịp rồi.” (ôn Bài 4)","pre":"","blank":"等","post":"我们赶到的时候，已经来不及了。","options":["等","随着","要是"],"answer":0,"explanation":"等……的时候 + 来不及 (Bài 4 · điểm 4)."},{"type":"sort","context":"Sắp xếp: “Đợi tớ làm xong bài tập rồi đi chơi với cậu.”","words":["等","我","写完作业","，","再","跟你","出去玩"],"answer":"等我写完作业，再跟你出去玩。","explanation":"等……，再……"},{"type":"sort","context":"Sắp xếp: “Người trẻ phải đợi người già ngồi xuống rồi mới ngồi.”","words":["年轻人","要","等","老人","坐下后","再坐"],"answer":"年轻人要等老人坐下后再坐。","explanation":"Chủ ngữ + 要 + 等 + sự việc + 后 + 再 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我写完作业等，再跟你出去玩。","isCorrect":false,"correctVersion":"等我写完作业，再跟你出去玩。","explanation":"等 đứng đầu vế câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"等我们到火车站的时候，火车已经开走了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 等……的时候，已经……了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"等你办了信用卡以后，你又能先花钱再还钱了。","isCorrect":false,"correctVersion":"等你办了信用卡以后，你就能先花钱再还钱了。","explanation":"Kết quả khi điều kiện đạt được dùng 就, không dùng 又."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đợi mọi người đến đủ rồi chúng ta mới bắt đầu ăn.","answer":"等大家都到了，我们再开始吃。","answerPy":"Děng dàjiā dōu dào le, wǒmen zài kāishǐ chī.","explanation":"等……，再……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đợi tôi tốt nghiệp xong, tôi sẽ về nước làm giáo viên.","answer":"等我毕业以后，就回国当老师。","answerPy":"Děng wǒ bìyè yǐhòu, jiù huíguó dāng lǎoshī.","explanation":"等……，就…… + 当 (Bài 1)."}]}],"/lessons/hsk4v3-bai-6.html":[{"point":"形容词“厉害” — … dữ dội, … kinh khủng","items":[{"context":"“… ho dữ lắm.”","pre":"我还发烧，一直咳嗽，咳得很","blank":"厉害","post":"。","options":["厉害","有效","按时"],"answer":0,"explanation":"V + 得 + 很 + 厉害."},{"context":"“… hôm nay chân đau dữ dội.”","pre":"我昨天跑步跑多了，今天腿疼","blank":"得","post":"厉害。","options":["得","的","地"],"answer":0,"explanation":"Bổ ngữ mức độ nối bằng 得."},{"context":"“Món này cay kinh khủng …”","pre":"这道菜辣得","blank":"厉害","post":"，我吃了一口就不敢再吃了。","options":["厉害","好吃","一点儿"],"answer":0,"explanation":"Adj + 得 + 厉害."},{"context":"“Gió thổi mạnh lắm, đợi lát nữa hãy đi.”","pre":"外面风刮","blank":"得","post":"很厉害，咱们等会儿再走吧。","options":["得","了","着"],"answer":0,"explanation":"刮 + 得 + 很厉害."},{"context":"“… mau đi bệnh viện khám đi.” (ôn từ mới)","pre":"我看你病得很厉害，","blank":"赶快","post":"去医院看看吧。","options":["赶快","偶尔","按时"],"answer":0,"explanation":"赶快 + V: giục làm ngay."},{"type":"sort","context":"Sắp xếp: “Bụng tôi đau dữ dội.”","words":["我","肚子","疼","得","很厉害"],"answer":"我肚子疼得很厉害。","explanation":"Adj + 得 + 很厉害."},{"type":"sort","context":"Sắp xếp: “Anh ấy ho rất dữ.”","words":["他","咳嗽","咳","得","特别厉害"],"answer":"他咳嗽咳得特别厉害。","explanation":"Động từ có tân ngữ → lặp động từ."},{"type":"sort","context":"Sắp xếp: “Hôm nay lạnh kinh khủng, mặc thêm áo vào.”","words":["今天","冷","得","厉害","，","多穿点儿衣服"],"answer":"今天冷得厉害，多穿点儿衣服。","explanation":"Adj + 得 + 厉害."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这道菜辣得很厉害，我不敢吃。","isCorrect":true,"correctVersion":"","explanation":"Đúng: Adj + 得 + 很厉害."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我很疼得厉害。","isCorrect":false,"correctVersion":"我疼得很厉害。","explanation":"很 đứng trước 厉害, không đứng trước 疼."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他咳嗽得厉害很。","isCorrect":false,"correctVersion":"他咳嗽得很厉害。","explanation":"Phó từ 很 đứng trước 厉害."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Hôm qua tôi ngủ muộn quá, hôm nay đầu đau dữ dội.","answer":"昨天我睡得太晚了，今天头疼得厉害。","answerPy":"Zuótiān wǒ shuì de tài wǎn le, jīntiān tóuténg de lìhai.","explanation":"头 + 疼 + 得 + (很) + 厉害."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Món này cay kinh khủng, có điều tôi vẫn ăn được.","answer":"这道菜辣得厉害，不过我吃得了。","answerPy":"Zhè dào cài là de lìhai, búguò wǒ chī de liǎo.","explanation":"辣得厉害 + ôn 不过 (Bài 2) và V得了 (Bài 4)."}]},{"point":"固定格式“（没）有什么（好）×的” — có gì mà phải …, chẳng có gì (đáng) …","items":[{"context":"“Cậu với tớ có gì mà phải khách sáo.”","pre":"你跟我有什么好","blank":"客气","post":"的。","options":["客气","厉害","严重"],"answer":0,"explanation":"有什么好 + V + 的."},{"context":"“… chẳng có gì lạ cả.”","pre":"这种事在网上有很多，没有什么奇怪","blank":"的","post":"。","options":["的","了","吗"],"answer":0,"explanation":"Cuối câu bắt buộc có 的."},{"context":"“… chẳng có gì đáng mua.”","pre":"这家商场里的东西都很一般，没有什么","blank":"好","post":"买的。","options":["好","很","太"],"answer":0,"explanation":"好 + V = đáng để làm."},{"context":"“Tớ chỉ bị cảm nhẹ, chẳng có gì phải lo.”","pre":"我得的只是小感冒，没有什么好","blank":"担心","post":"的。","options":["担心","放心","高兴"],"answer":0,"explanation":"没有什么好担心的."},{"context":"“… chẳng có gì phải dọn.”","pre":"前天刚打扫过，还很干净，","blank":"没有","post":"什么好打扫的。","options":["没有","不是","不"],"answer":0,"explanation":"Phủ định dùng 没有什么, không dùng 不什么."},{"type":"sort","context":"Sắp xếp: “Chúng mình là bạn thân, chẳng có gì phải khách sáo.”","words":["咱们","是","好朋友","，","没有什么","好","客气","的"],"answer":"咱们是好朋友，没有什么好客气的。","explanation":"没有什么 + 好 + V + 的."},{"type":"sort","context":"Sắp xếp: “Vấn đề này đơn giản lắm, có gì mà phải bàn.”","words":["这个问题","很简单","，","有什么","好","讨论","的"],"answer":"这个问题很简单，有什么好讨论的？","explanation":"有什么好 + V + 的: hỏi tu từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你跟我有什么好客气的。","isCorrect":true,"correctVersion":"","explanation":"Đúng: câu hỏi tu từ, gạt đi lời cảm ơn."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这部电影很一般，没有什么好看。","isCorrect":false,"correctVersion":"这部电影很一般，没有什么好看的。","explanation":"Thiếu 的 cuối câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"考试很简单，没有什么好紧张的。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 没有什么好 + V + 的."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chúng ta là bạn bè, có gì mà phải khách sáo.","answer":"我们是朋友，有什么好客气的。","answerPy":"Wǒmen shì péngyou, yǒu shénme hǎo kèqi de.","explanation":"有什么好客气的."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bộ phim này rất bình thường, chẳng có gì đáng xem.","answer":"这部电影很一般，没有什么好看的。","answerPy":"Zhè bù diànyǐng hěn yìbān, méiyǒu shénme hǎokàn de.","explanation":"没有什么好看的."}]},{"point":"频率副词“偶尔” — thỉnh thoảng, lâu lâu mới","items":[{"context":"“… lâu lâu mới ốm một lần.”","pre":"她平时身体不错，","blank":"偶尔","post":"才会生一次病。","options":["偶尔","经常","总是"],"answer":0,"explanation":"偶尔 + 才: hiếm khi."},{"context":"“… thỉnh thoảng mới ra rạp.”","pre":"他经常在家看电影，偶尔","blank":"才","post":"去电影院看。","options":["才","就","都"],"answer":0,"explanation":"偶尔才 + V."},{"context":"“… thỉnh thoảng đi ăn ngoài với bạn.”","pre":"我一般都在学校食堂吃饭，","blank":"偶尔","post":"会跟朋友一起出去吃。","options":["偶尔","一直","按时"],"answer":0,"explanation":"一般……，偶尔……"},{"context":"“… có điều thỉnh thoảng cũng muốn ăn đồ ngọt.”","pre":"我喜欢吃辣的菜，不过偶尔","blank":"也","post":"想吃点儿甜的。","options":["也","才","就"],"answer":0,"explanation":"偶尔也 = cũng có lúc."},{"context":"“… uống thuốc đúng giờ.” (phân biệt với 偶尔)","pre":"医生让她回家以后","blank":"按时","post":"吃药，多喝水，多休息。","options":["按时","偶尔","光"],"answer":0,"explanation":"Uống thuốc phải 按时, không thể 偶尔."},{"type":"sort","context":"Sắp xếp: “Tôi thường đi tàu điện ngầm, thỉnh thoảng mới đi taxi.”","words":["我","一般","坐地铁","，","偶尔","才","打车"],"answer":"我一般坐地铁，偶尔才打车。","explanation":"一般……，偶尔才……"},{"type":"sort","context":"Sắp xếp: “Bình thường anh ấy không uống rượu, thỉnh thoảng uống một chút.”","words":["他","平时","不喝酒","，","偶尔","会","喝一点儿"],"answer":"他平时不喝酒，偶尔会喝一点儿。","explanation":"偶尔会 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我吃偶尔辣的菜。","isCorrect":false,"correctVersion":"我偶尔吃辣的菜。","explanation":"偶尔 đứng trước động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她身体很好，偶尔才生一次病。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 偶尔才 + 生一次病."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他每天都偶尔去跑步。","isCorrect":false,"correctVersion":"他偶尔去跑步。","explanation":"每天都 (ngày nào cũng) mâu thuẫn với 偶尔."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi thường học ở thư viện, thỉnh thoảng mới học ở ký túc xá.","answer":"我经常在图书馆学习，偶尔才在宿舍学习。","answerPy":"Wǒ jīngcháng zài túshūguǎn xuéxí, ǒu'ěr cái zài sùshè xuéxí.","explanation":"经常 / 一般……，偶尔才……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Anh ấy rất ít khi ốm, thỉnh thoảng mới bị cảm một lần.","answer":"他很少生病，偶尔才感冒一次。","answerPy":"Tā hěn shǎo shēngbìng, ǒu'ěr cái gǎnmào yí cì.","explanation":"偶尔才 + V + 一次."}]},{"point":"目的复句“……，好……” — …, để (tiện / dễ) …","items":[{"context":"“… để đưa ra cách điều trị phù hợp.”","pre":"医生有时还会做一些检查，","blank":"好","post":"给出合适的治疗方法。","options":["好","就","才"],"answer":0,"explanation":"……，好 + V (mục đích)."},{"context":"“Các bạn tìm hiểu tình hình trước …”","pre":"你们先了解一下","blank":"情况","post":"，好做出决定。","options":["情况","过程","结果"],"answer":0,"explanation":"了解 + 情况."},{"context":"“… sau này có việc gì thì tiện liên lạc với tôi.”","pre":"我把电话号码告诉你，以后有什么事","blank":"好","post":"联系我。","options":["好","再","又"],"answer":0,"explanation":"好 đứng ngay trước động từ 联系."},{"context":"“… để họ yên tâm.”","pre":"我每天都给家人打电话，好","blank":"让","post":"他们放心。","options":["让","被","把"],"answer":0,"explanation":"好 + 让 + ai + Adj."},{"context":"“Khám bệnh ở Trung Quốc phải lấy số trước …” (ôn từ mới)","pre":"在中国看病要先","blank":"挂号","post":"，然后再去找医生。","options":["挂号","打针","收费"],"answer":0,"explanation":"先挂号，然后再看病."},{"type":"sort","context":"Sắp xếp: “Bạn ngủ sớm đi, để mai còn dậy sớm.”","words":["你","早点儿","睡","，","明天","好","早起"],"answer":"你早点儿睡，明天好早起。","explanation":"Trạng ngữ 明天 + 好 + V."},{"type":"sort","context":"Sắp xếp: “Xin để lại địa chỉ, để chúng tôi tiện gửi đồ cho bạn.”","words":["请","留下","你的地址","，","我们","好","给你寄东西"],"answer":"请留下你的地址，我们好给你寄东西。","explanation":"Chủ ngữ 我们 + 好 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把电话号码告诉你，以后有什么事好联系我。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 好 đứng trước 联系."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"好让他们放心，我每天给家人打电话。","isCorrect":false,"correctVersion":"我每天给家人打电话，好让他们放心。","explanation":"Vế 好 (mục đích) đặt sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你先在大厅休息，我去排队挂号，好节省时间。","isCorrect":true,"correctVersion":"","explanation":"Đúng: vế cuối 好 + V nêu mục đích."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bạn mang theo hộ chiếu, để tiện đi lấy số.","answer":"你带上护照，好去挂号。","answerPy":"Nǐ dàishàng hùzhào, hǎo qù guàhào.","explanation":"……，好 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi ghi lại các bước nấu món ăn, để lần sau dễ làm.","answer":"我把做菜的过程写下来，下次好做。","answerPy":"Wǒ bǎ zuò cài de guòchéng xiěxiàlái, xià cì hǎo zuò.","explanation":"Trạng ngữ 下次 + 好 + V."}]}],"/lessons/hsk4v3-bai-7.html":[{"point":"固定格式“在……方面” — về mặt …, trong lĩnh vực …","items":[{"context":"“Về mặt nội dung, chị thấy có chỗ nào cần sửa không?”","pre":"","blank":"在","post":"内容方面，您觉得有需要改的吗？","options":["在","从","对"],"answer":0,"explanation":"Cấu trúc cố định: 在 + N + 方面."},{"context":"“Về mặt sắp xếp thời gian …”","pre":"在时间安排","blank":"方面","post":"，你可以再想一想。","options":["方面","一方面","地方"],"answer":0,"explanation":"在……方面 khoanh vùng một mặt; 一方面 dùng khi liệt kê hai mặt (Bài 1)."},{"context":"“… về mặt sinh hoạt vẫn chưa quen lắm.”","pre":"他才来中国两个月，在生活方面，还不太","blank":"习惯","post":"。","options":["习惯","经验","产品"],"answer":0,"explanation":"不太习惯 = chưa quen lắm."},{"context":"“Về mặt giá cả, mua trên mạng thường rẻ hơn cửa hàng.” (ôn 往往 – Bài 4)","pre":"在价格方面，网购","blank":"往往","post":"比商店便宜。","options":["往往","及时","提前"],"answer":0,"explanation":"往往 = thường thường (theo quy luật)."},{"context":"“Con trai tôi về mặt học tập thể hiện rất tốt.” (ôn 表现 – Bài 1)","pre":"我儿子在学习方面","blank":"表现","post":"很好。","options":["表现","效果","内容"],"answer":0,"explanation":"表现很好 = biểu hiện / thể hiện tốt."},{"type":"sort","context":"Sắp xếp: “Về mặt nội dung, chị thấy có chỗ nào cần sửa không?”","words":["在","内容","方面","，","您","觉得","有需要改的吗"],"answer":"在内容方面，您觉得有需要改的吗？","explanation":"在 + N + 方面 đứng đầu câu."},{"type":"sort","context":"Sắp xếp: “Về mặt công việc, cô ấy vừa cẩn thận vừa nghiêm túc.”","words":["她","在","工作","方面","既","细心","又","认真"],"answer":"她在工作方面既细心又认真。","explanation":"Chủ ngữ + 在……方面 + vị ngữ; ôn 既……又…… (Bài 4)."},{"type":"sort","context":"Sắp xếp: “Về mặt sinh hoạt, anh ấy vẫn chưa quen lắm.”","words":["在","生活","方面","，","他","还","不太习惯"],"answer":"在生活方面，他还不太习惯。","explanation":"在……方面 đứng đầu câu hoặc sau chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他在交流方面能力很强。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 在交流方面 đứng trước vị ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她很细心在工作方面。","isCorrect":false,"correctVersion":"她在工作方面很细心。","explanation":"在……方面 phải đứng TRƯỚC vị ngữ 很细心."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在学习方面上，他的表现很好。","isCorrect":false,"correctVersion":"在学习方面，他的表现很好。","explanation":"Không thêm 上 sau 方面."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Về mặt nội dung, bản kế hoạch này chẳng có gì phải sửa.","answer":"在内容方面，这个计划书没有什么好改的。","answerPy":"Zài nèiróng fāngmiàn, zhège jìhuàshū méiyǒu shénme hǎo gǎi de.","explanation":"在……方面 + 没有什么好×的 (Bài 6 · điểm 2)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Về mặt giá cả, mua trên mạng thường rẻ hơn ở cửa hàng.","answer":"在价格方面，网购往往比商店便宜。","answerPy":"Zài jiàgé fāngmiàn, wǎnggòu wǎngwǎng bǐ shāngdiàn piányi.","explanation":"在价格方面 + 往往 (Bài 4) + câu so sánh 比."}]},{"point":"因果复句“既然……，就……” — đã … thì …","items":[{"context":"“Đã đi công tác không lâu thì …”","pre":"","blank":"既然","post":"出差时间不长，就要安排好时间。","options":["既然","虽然","不但"],"answer":0,"explanation":"既然……，就……: tiền đề → kết luận."},{"context":"“… thì chúng ta làm như vậy đi.”","pre":"既然大家都同意，我们","blank":"就","post":"这么做吧。","options":["就","才","都"],"answer":0,"explanation":"就 đứng sau chủ ngữ 我们."},{"context":"“… thì đừng sửa nữa.”","pre":"既然你们已经决定了，就不要再","blank":"改","post":"了。","options":["改","谈","管理"],"answer":0,"explanation":"不要再改了 = đừng sửa nữa."},{"context":"“Bạn đã có kinh nghiệm về mặt này thì giới thiệu cho chúng tôi đi.”","pre":"既然你有这方面的","blank":"经验","post":"，就给我们介绍一下吧。","options":["经验","产品","市场"],"answer":0,"explanation":"有……方面的经验."},{"context":"“Đã không kịp nữa thì đi taxi thôi.” (ôn Bài 4)","pre":"既然","blank":"来不及","post":"了，我们就坐出租车去吧。","options":["来不及","来得及","来不了"],"answer":0,"explanation":"来不及 = không kịp (thời gian)."},{"type":"sort","context":"Sắp xếp: “Mọi người đã đồng ý cả thì chúng ta làm như vậy đi.”","words":["既然","大家","都同意","，","我们","就","这么做吧"],"answer":"既然大家都同意，我们就这么做吧。","explanation":"既然……，Sub + 就……"},{"type":"sort","context":"Sắp xếp: “Bạn đã không khỏe thì về nhà nghỉ đi.”","words":["既然","你","不舒服","，","就","回家","休息吧"],"answer":"既然你不舒服，就回家休息吧。","explanation":"既然 có thể đứng trước hoặc sau chủ ngữ."},{"type":"sort","context":"Sắp xếp: “Đã đi công tác không lâu thì phải sắp xếp thời gian cho tốt.”","words":["既然","出差时间","不长","，","就要","安排好","时间"],"answer":"既然出差时间不长，就要安排好时间。","explanation":"Câu trong bài khoá 2."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"既然你已经决定了，我也不说什么了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: vế sau có thể dùng 也."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"既然他生病了，所以没来上课。","isCorrect":false,"correctVersion":"因为他生病了，所以没来上课。","explanation":"Kể nguyên nhân – kết quả khách quan dùng 因为……所以……; vế sau của 既然 là kết luận / đề nghị."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"既然下雨了，就咱们不出去了吧。","isCorrect":false,"correctVersion":"既然下雨了，咱们就不出去了吧。","explanation":"就 đứng sau chủ ngữ 咱们."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đã đến rồi thì ngồi thêm một lúc nữa đi.","answer":"既然来了，就再坐一会儿吧。","answerPy":"Jìrán lái le, jiù zài zuò yíhuìr ba.","explanation":"既然……，就…… + 吧 (lời mời, đề nghị)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đã không có cơ hội phát triển thì đổi một công việc khác đi.","answer":"既然没有发展机会，就换一个工作吧。","answerPy":"Jìrán méiyǒu fāzhǎn jīhuì, jiù huàn yí gè gōngzuò ba.","explanation":"Đáp án gợi ý của sách; 一份工作 (lượng từ 份 – từ mới)."}]},{"point":"固定格式“拿……来说” — lấy … mà nói, ví dụ như …","items":[{"context":"“Lấy mua sắm mà nói …”","pre":"现在的生活很方便。","blank":"拿","post":"购物来说，人们不出门就能买到想要的东西。","options":["拿","对","把"],"answer":0,"explanation":"Dẫn ví dụ → 拿……来说."},{"context":"“Lấy chuyện ăn uống mà nói …”","pre":"在中国，南北方的生活习惯不同。拿吃饭来","blank":"说","post":"，一般南方人更爱吃米饭。","options":["说","看","想"],"answer":0,"explanation":"Cấu trúc cố định 拿……来说."},{"context":"“Lấy việc trao đổi với khách hàng mà nói …”","pre":"她也遇到了一些困难。拿和客户","blank":"交流","post":"来说，实际效果并不理想。","options":["交流","产品","效果"],"answer":0,"explanation":"Giữa 拿 và 来说 có thể là cụm động từ: 和客户交流."},{"context":"“Lấy tốc độ mà nói, hôm nay mua mai đã nhận.” (ôn 速度 – Bài 4)","pre":"网购有很多优点。拿","blank":"速度","post":"来说，今天买的东西明天就能收到。","options":["速度","能力","基础"],"answer":0,"explanation":"Ví dụ về ưu điểm “tốc độ” của mua hàng trên mạng."},{"context":"“Lấy môi trường mà nói, đâu cũng có hoa …” (ôn Bài 2)","pre":"这个小区很不错。拿","blank":"环境","post":"来说，到处都是花，还种了很多树。","options":["环境","房租","经验"],"answer":0,"explanation":"Hoa, cây → nói về 环境."},{"type":"sort","context":"Sắp xếp: “Lấy chuyện ăn uống mà nói, người miền Nam thường thích ăn cơm hơn.”","words":["拿","吃饭","来说","，","一般","南方人","更爱吃","米饭"],"answer":"拿吃饭来说，一般南方人更爱吃米饭。","explanation":"拿 + N + 来说，……"},{"type":"sort","context":"Sắp xếp: “Lấy mua sắm mà nói, người ta không ra khỏi nhà cũng mua được thứ mình muốn.”","words":["拿","购物","来说","，","人们","不出门","就能","买到想要的东西"],"answer":"拿购物来说，人们不出门就能买到想要的东西。","explanation":"Ví dụ của sách."},{"type":"sort","context":"Sắp xếp: “Lấy tôi làm ví dụ, mỗi ngày tôi học ít nhất hai tiếng.”","words":["拿","我","来说","，","我","每天","至少","学习两个小时"],"answer":"拿我来说，我每天至少学习两个小时。","explanation":"拿 + người + 来说; ôn 至少 (Bài 5)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这家饭馆的菜很好吃。拿水煮鱼来说，又香又辣。","isCorrect":true,"correctVersion":"","explanation":"Đúng: nhận định chung trước, ví dụ 拿……来说 sau (水煮鱼 – Bài 5)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们班同学经常互相帮助。拿学习说，大家经常一起研究难题。","isCorrect":false,"correctVersion":"我们班同学经常互相帮助。拿学习来说，大家经常一起研究难题。","explanation":"Thiếu 来."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"拿我来说，这个问题太难了。","isCorrect":false,"correctVersion":"对我来说，这个问题太难了。","explanation":"Nói cảm nhận của một người → 对……来说."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Giao thông thành phố này rất thuận tiện. Lấy tàu điện ngầm mà nói, đi đâu cũng tiện.","answer":"这个城市的交通很方便。拿地铁来说，去哪儿都很方便。","answerPy":"Zhège chéngshì de jiāotōng hěn fāngbiàn. Ná dìtiě láishuō, qù nǎr dōu hěn fāngbiàn.","explanation":"Nhận định chung + 拿……来说 + ví dụ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Lớp nào cũng có ưu điểm. Lấy lớp chúng tôi mà nói, các bạn thường xuyên giúp đỡ lẫn nhau.","answer":"每个班都有优点。拿我们班来说，同学之间经常互相帮助。","answerPy":"Měi gè bān dōu yǒu yōudiǎn. Ná wǒmen bān láishuō, tóngxué zhījiān jīngcháng hùxiāng bāngzhù.","explanation":"优点 (từ mới) + ôn 之间, 互相 (Bài 4)."}]},{"point":"兼语句“主语+使+宾语+动词短语” — A khiến (làm cho) B …","items":[{"context":"“Phương pháp mới khiến công việc đơn giản hơn.”","pre":"这个新方法","blank":"使","post":"工作变得更加简单了。","options":["使","被","把"],"answer":0,"explanation":"A + 使 + B + 变得 + Adj."},{"context":"“… khiến sự phát triển của bản thân bị ảnh hưởng.”","pre":"如果总是换工作，可能会使自己的发展","blank":"受到","post":"影响。","options":["受到","得到","收到"],"answer":0,"explanation":"受到影响 = bị ảnh hưởng."},{"context":"“… giúp du học sinh nhanh chóng thích nghi với cuộc sống đại học.” (ôn 适应 – Bài 1)","pre":"参加这些交流活动使留学生更快","blank":"适应","post":"了大学生活。","options":["适应","进入","积累"],"answer":0,"explanation":"适应 + 生活 / 环境."},{"context":"“Lâu không nghỉ ngơi có thể khiến sức khỏe bị ảnh hưởng.”","pre":"长时间不休息可能会使","blank":"健康","post":"受到影响。","options":["健康","效果","能力"],"answer":0,"explanation":"Đáp án gợi ý của sách."},{"context":"“… thích nghi với môi trường làm việc mới.”","pre":"和同事多交流可以使你更快适应新的工作","blank":"环境","post":"。","options":["环境","产品","内容"],"answer":0,"explanation":"工作环境 = môi trường làm việc."},{"type":"sort","context":"Sắp xếp: “Phương pháp mới này khiến công việc trở nên đơn giản hơn.”","words":["这个","新方法","使","工作","变得","更加简单了"],"answer":"这个新方法使工作变得更加简单了。","explanation":"Chủ ngữ + 使 + tân ngữ + 变得 + Adj."},{"type":"sort","context":"Sắp xếp: “Lần khảo sát thị trường này giúp chúng tôi hiểu suy nghĩ của khách hàng hơn.”","words":["这次","市场调查","使","我们","更了解","客户的想法"],"answer":"这次市场调查使我们更了解客户的想法。","explanation":"我们 vừa là tân ngữ của 使 vừa là chủ ngữ của 了解."},{"type":"sort","context":"Sắp xếp: “Mua sắm trên mạng khiến cuộc sống của mọi người tiện hơn.”","words":["网购","使","人们的生活","更加","方便了"],"answer":"网购使人们的生活更加方便了。","explanation":"使 + B + 更加 + Adj (ôn Bài 3, 4)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个消息使大家都很高兴。","isCorrect":true,"correctVersion":"","explanation":"Đúng: sự việc (消息) khiến mọi người vui."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"老师使我们写一篇作文。","isCorrect":false,"correctVersion":"老师让我们写一篇作文。","explanation":"Giao việc, sai bảo dùng 让, không dùng 使."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这次出差使积累了很多经验。","isCorrect":false,"correctVersion":"这次出差使我积累了很多经验。","explanation":"Sau 使 phải có tân ngữ (我)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thường xuyên thức khuya sẽ khiến sức khỏe bị ảnh hưởng.","answer":"经常熬夜会使健康受到影响。","answerPy":"Jīngcháng áoyè huì shǐ jiànkāng shòudào yǐngxiǎng.","explanation":"会 + 使 + B + 受到影响."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chuyến công tác lần này giúp tôi tích lũy được không ít kinh nghiệm.","answer":"这次出差使我积累了不少经验。","answerPy":"Zhè cì chūchāi shǐ wǒ jīlěi le bùshǎo jīngyàn.","explanation":"出差, 积累, 经验 (từ mới) + 使."}]}],"/lessons/hsk4v3-bai-8.html":[{"point":"条件复句“不管……，都/也……” — bất kể …, đều / cũng …","items":[{"context":"“Đi đâu cũng được, miễn là nơi có thể thư giãn.”","pre":"","blank":"不管","post":"去哪儿，能放松的地方都行。","options":["不管","虽然","因为"],"answer":0,"explanation":"不管 + từ để hỏi (哪儿)，都……"},{"context":"“Bất kể có suy nghĩ gì, bạn cũng phải nói ra.”","pre":"不管有什么想法，你","blank":"都","post":"要说出来。","options":["都","就","才"],"answer":0,"explanation":"Vế sau của 不管 dùng 都 / 也."},{"context":"“Bất kể thời tiết tốt hay không …”","pre":"不管天气","blank":"好不好","post":"，他每天都去跑步。","options":["好不好","很好","不好"],"answer":0,"explanation":"Sau 不管 dùng dạng lựa chọn Adj不Adj, không dùng 很好 (sự thật xác định)."},{"context":"“Dù gặp khó khăn lớn đến đâu, chúng ta cũng phải kiên trì.”","pre":"不管遇到多大困难，我们","blank":"也","post":"要坚持。","options":["也","还","再"],"answer":0,"explanation":"都 / 也 đứng sau chủ ngữ 我们."},{"context":"“Dù bận đến đâu …” (ôn 至少 – Bài 5)","pre":"不管","blank":"多","post":"忙，他每个星期都至少锻炼两次。","options":["多","很","太"],"answer":0,"explanation":"不管 + 多 + Adj = dù … đến đâu."},{"type":"sort","context":"Sắp xếp: “Bất kể căn nhà này to hay nhỏ, tôi cũng thuê.”","words":["不管","这个房子","大还是小","，","我","都要租"],"answer":"不管这个房子大还是小，我都要租。","explanation":"不管 + A还是B，Sub + 都……"},{"type":"sort","context":"Sắp xếp: “Bất kể ai đến, bạn cũng phải báo cho tôi.”","words":["不管","谁","来","，","你","都","要告诉我"],"answer":"不管谁来，你都要告诉我。","explanation":"不管 + 谁 (từ để hỏi)."},{"type":"sort","context":"Sắp xếp: “Dù đi du lịch ở đâu, cô ấy cũng đội chiếc mũ này.”","words":["不管","去哪儿","旅游","，","她","都","戴着这顶帽子"],"answer":"不管去哪儿旅游，她都戴着这顶帽子。","explanation":"Từ mới 戴, 帽子 + 不管……都……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不管明天下不下雨，我们都去参观故宫。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 不管 + V不V，Sub + 都……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不管天气很热，他也戴着帽子。","isCorrect":false,"correctVersion":"不管天气多热，他都戴着帽子。","explanation":"Sau 不管 không dùng sự thật xác định 很热 → dùng 多热."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不管有什么问题，都你可以问我。","isCorrect":false,"correctVersion":"不管有什么问题，你都可以问我。","explanation":"都 đứng sau chủ ngữ 你."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bất kể đi đâu, chỉ cần thư giãn được là được.","answer":"不管去哪儿，能放松就行。","answerPy":"Bùguǎn qù nǎr, néng fàngsōng jiù xíng.","explanation":"不管 + từ để hỏi，……都 / 就行."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Dù công việc bận đến đâu, cuối tuần anh ấy cũng đi ngoại ô thư giãn.","answer":"不管工作多忙，周末他都去郊区放松。","answerPy":"Bùguǎn gōngzuò duō máng, zhōumò tā dōu qù jiāoqū fàngsōng.","explanation":"不管 + 多 + Adj，Sub + 都 / 也……"}]},{"point":"假设复句“……，否则……” — …, nếu không thì …","items":[{"context":"“… nếu không mất sức khỏe thì chẳng đáng.”","pre":"还是别给自己太大压力，","blank":"否则","post":"，失去健康就不值得了。","options":["否则","因此","不过"],"answer":0,"explanation":"Lời khuyên，否则 + hậu quả."},{"context":"“… nếu không rất dễ hỏng.”","pre":"吃不完的菜要放进冰箱，否则很容易","blank":"坏","post":"。","options":["坏","好","新鲜"],"answer":0,"explanation":"Vế sau của 否则 là hậu quả xấu."},{"context":"“… nếu không sáng mai dậy không nổi.” (ôn bổ ngữ khả năng – Bài 4)","pre":"今晚早点儿睡吧，否则明天早上","blank":"起不来","post":"。","options":["起不来","起得来","起来了"],"answer":0,"explanation":"起不来 = không dậy nổi."},{"context":"“Ra ngoài nhớ đội mũ, nếu không sẽ bị nắng làm đau đầu.”","pre":"外出记得戴帽子，","blank":"否则","post":"会被太阳晒得头疼。","options":["否则","所以","并"],"answer":0,"explanation":"否则 đứng đầu vế sau."},{"context":"“… nếu không sẽ không kịp.” (ôn Bài 4 · điểm 4)","pre":"我们得马上出发，否则就","blank":"来不及","post":"了。","options":["来不及","来得及","不来"],"answer":0,"explanation":"来不及 = không kịp."},{"type":"sort","context":"Sắp xếp: “Đừng thức khuya nữa, nếu không cơ thể sẽ không chịu nổi đâu.”","words":["别","熬夜了","，","否则","身体","会","受不了的"],"answer":"别熬夜了，否则身体会受不了的。","explanation":"Lời khuyên，否则 + hậu quả (ôn V不了 – Bài 4)."},{"type":"sort","context":"Sắp xếp: “Đi nhanh lên, nếu không chúng ta sẽ bị muộn.”","words":["快","走吧","，","否则","我们","就要","迟到了"],"answer":"快走吧，否则我们就要迟到了。","explanation":"否则……就要……了."},{"type":"sort","context":"Sắp xếp: “Mang ô theo, nếu không trời mưa thì phiền lắm.”","words":["带上","雨伞","，","否则","下雨","就","麻烦了"],"answer":"带上雨伞，否则下雨就麻烦了。","explanation":"否则 + điều kiện + 就 + hậu quả."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你得按时吃饭，否则对身体不好。","isCorrect":true,"correctVersion":"","explanation":"Đúng: yêu cầu，否则 + hậu quả xấu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"否则会感冒，你多穿点儿衣服。","isCorrect":false,"correctVersion":"你多穿点儿衣服，否则会感冒。","explanation":"否则 đứng ở đầu vế sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"多休息吧，否则工作效率会更高。","isCorrect":false,"correctVersion":"多休息吧，否则工作效率会下降。","explanation":"Vế sau 否则 phải là hậu quả xấu khi KHÔNG nghỉ ngơi."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đừng tăng ca nữa, nếu không sức khỏe sẽ bị ảnh hưởng.","answer":"别再加班了，否则健康会受到影响。","answerPy":"Bié zài jiābān le, fǒuzé jiànkāng huì shòudào yǐngxiǎng.","explanation":"Lời khuyên，否则 + hậu quả."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bạn phải nhắc tôi nhé, nếu không tôi nhất định sẽ quên.","answer":"你要提醒我，否则我一定会忘的。","answerPy":"Nǐ yào tíxǐng wǒ, fǒuzé wǒ yídìng huì wàng de.","explanation":"提醒 (từ mới) + 否则."}]},{"point":"比较句“跟……相比” — so với …","items":[{"context":"“So với tăng ca liên tục …”","pre":"跟一直加班","blank":"相比","post":"，休息好了再工作，效率更高。","options":["相比","比较","一样"],"answer":0,"explanation":"跟 + A + 相比."},{"context":"“So với học thạc sĩ …”","pre":"","blank":"跟","post":"读研究生相比，我更想直接工作。","options":["跟","比","对"],"answer":0,"explanation":"跟……相比 (khẩu ngữ)."},{"context":"“… thanh toán bằng điện thoại tiện hơn.”","pre":"跟用现金相比，手机支付","blank":"更","post":"方便些。","options":["更","很","非常"],"answer":0,"explanation":"Câu so sánh dùng 更, không dùng 很."},{"context":"“So với năm ngoái …” (văn viết)","pre":"","blank":"与","post":"去年相比，今年来这里游玩的人多了一倍。","options":["与","比","被"],"answer":0,"explanation":"与……相比: trang trọng, văn viết."},{"context":"“… không khí ngoại ô trong lành hơn nhiều.”","pre":"跟市区相比，郊区的空气新鲜","blank":"多了","post":"。","options":["多了","很多","非常"],"answer":0,"explanation":"Adj + 多了 = … hơn nhiều."},{"type":"sort","context":"Sắp xếp: “So với đi máy bay, đi tàu cao tốc thoải mái hơn.”","words":["跟","坐飞机","相比","，","坐高铁","更","舒服"],"answer":"跟坐飞机相比，坐高铁更舒服。","explanation":"跟 + A + 相比，B + 更 + Adj."},{"type":"sort","context":"Sắp xếp: “So với trước đây, hiệu suất làm việc của anh ấy đã tăng nhiều.”","words":["与","以前","相比","，","他的","工作效率","提高了很多"],"answer":"与以前相比，他的工作效率提高了很多。","explanation":"与……相比 (văn viết)."},{"type":"sort","context":"Sắp xếp: “So với ở nhà xem tivi, tôi thích đi ngoại ô chơi hơn.”","words":["跟","在家看电视","相比","，","我","更喜欢","去郊区游玩"],"answer":"跟在家看电视相比，我更喜欢去郊区游玩。","explanation":"Chủ ngữ 我 đứng ở vế sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"跟市区相比，郊区安静多了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: Adj + 多了 trong câu so sánh."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"跟去年相比，今年的夏天非常热。","isCorrect":false,"correctVersion":"跟去年相比，今年的夏天更热。","explanation":"Câu so sánh dùng 更, không dùng 非常."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"跟一直学习，休息一下效率更高。","isCorrect":false,"correctVersion":"跟一直学习相比，休息一下效率更高。","explanation":"Thiếu 相比."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"So với đi taxi, đi tàu điện ngầm rẻ hơn nhiều.","answer":"跟打车相比，坐地铁便宜多了。","answerPy":"Gēn dǎchē xiāngbǐ, zuò dìtiě piányi duō le.","explanation":"跟……相比，B + Adj + 多了."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"So với nội thành, ngoại ô có núi có sông, phong cảnh đẹp hơn.","answer":"跟市区相比，郊区有山有水，风景更美。","answerPy":"Gēn shìqū xiāngbǐ, jiāoqū yǒu shān yǒu shuǐ, fēngjǐng gèng měi.","explanation":"跟……相比 + 有A有B (điểm 4)."}]},{"point":"固定短语“有A有B” — có A có B","items":[{"context":"“Ngoại ô có núi có sông …”","pre":"郊区有山有","blank":"水","post":"，还有很多农家乐。","options":["水","人","车"],"answer":0,"explanation":"有山有水 — cặp gần nghĩa, chỉ cảnh đẹp."},{"context":"“… có quả to quả nhỏ …”","pre":"超市里的苹果有大有","blank":"小","post":"，有红有绿。","options":["小","多","好"],"answer":0,"explanation":"有大有小 — cặp trái nghĩa."},{"context":"“… có nam có nữ …”","pre":"公园里到处都是人，有男有","blank":"女","post":"，特别热闹。","options":["女","老","人"],"answer":0,"explanation":"有男有女."},{"context":"“Họ ở cùng nhau nói nói cười cười …”","pre":"他们在一起有说有","blank":"笑","post":"，特别开心。","options":["笑","听","哭"],"answer":0,"explanation":"有说有笑 = vừa nói vừa cười, vui vẻ."},{"context":"“Món ăn có món ngọt có món cay …” (ôn từ Bài 5)","pre":"这家饭馆的菜有","blank":"甜","post":"有辣，大家都能找到喜欢的。","options":["甜","饭","好"],"answer":0,"explanation":"有甜有辣 — hai vị khác nhau."},{"type":"sort","context":"Sắp xếp: “Khu vườn nhỏ có hoa có cỏ, rất đẹp.”","words":["小花园里","有花","有草","，","非常","漂亮"],"answer":"小花园里有花有草，非常漂亮。","explanation":"Nơi chốn + 有A有B."},{"type":"sort","context":"Sắp xếp: “Bạn học lớp tôi có nam có nữ, có lớn có nhỏ.”","words":["我们班的同学","有男","有女","，","有大","有小"],"answer":"我们班的同学有男有女，有大有小。","explanation":"Hai cụm 有A有B nối tiếp."},{"type":"sort","context":"Sắp xếp: “Cuộc sống lúc nào cũng có đắng có ngọt.”","words":["生活","总是","有苦","有甜","的"],"answer":"生活总是有苦有甜的。","explanation":"有苦有甜 — trái nghĩa."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个地方有山有水，景色十分美丽。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 有山有水 + từ mới 景色, 十分, 美丽."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"市场里的水果有大和有小。","isCorrect":false,"correctVersion":"市场里的水果有大有小。","explanation":"Không thêm 和."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"大家在一起有说笑，特别热闹。","isCorrect":false,"correctVersion":"大家在一起有说有笑，特别热闹。","explanation":"Thiếu chữ 有 thứ hai."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Ngoại ô có núi có sông, ăn, chơi, ở đều rất tiện.","answer":"郊区有山有水，吃、玩、住都十分方便。","answerPy":"Jiāoqū yǒu shān yǒu shuǐ, chī, wán, zhù dōu shífēn fāngbiàn.","explanation":"有A有B + 十分 (từ mới)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Trong công viên có người lớn có trẻ con, vô cùng náo nhiệt.","answer":"公园里有大人有孩子，十分热闹。","answerPy":"Gōngyuán lǐ yǒu dàrén yǒu háizi, shífēn rènao.","explanation":"A, B hai âm tiết: 有大人有孩子."}]}],"/lessons/hsk4v3-bai-9.html":[{"point":"紧缩复句“不……也……” — không … cũng (vẫn) …","items":[{"context":"“Em không nói anh cũng hiểu em đang nghĩ gì.”","pre":"我不说你","blank":"也","post":"懂我在想什么。","options":["也","就","还"],"answer":0,"explanation":"不……也……: dù không nói, kết quả vẫn là hiểu."},{"context":"“Cậu ấy không ôn cũng thi được điểm cao.”","pre":"他不","blank":"复习","post":"也能考出好成绩。","options":["复习","错过","祝"],"answer":0,"explanation":"不 + V1 (复习) + 也 + kết quả."},{"context":"“… không hỏi tôi cũng biết.”","pre":"我很清楚他为什么生气，","blank":"不","post":"问我也知道。","options":["不","没","别"],"answer":0,"explanation":"Mẫu cố định dùng 不 ở vế đầu."},{"context":"“Đường này tôi đi nhiều lần rồi, không dùng điện thoại cũng tìm được.”","pre":"这条路我走过很多次了，不用手机","blank":"也","post":"能找到。","options":["也","才","再"],"answer":0,"explanation":"不用……也能…… = không cần … cũng có thể …"},{"context":"“Trưa ăn no quá, tối không ăn cũng không đói.”","pre":"我中午吃得太饱了，晚上不吃饭也不","blank":"饿","post":"。","options":["饿","饱","累"],"answer":0,"explanation":"Vế sau có thể là phủ định: 也不饿."},{"type":"sort","context":"Sắp xếp: “Em không nói anh cũng hiểu.”","words":["我","不说","你","也","懂"],"answer":"我不说你也懂。","explanation":"Sub1 + 不 + V1 + Sub2 + 也 + V2."},{"type":"sort","context":"Sắp xếp: “Cậu ấy không ôn cũng thi được điểm cao.”","words":["他","不","复习","也能","考出","好成绩"],"answer":"他不复习也能考出好成绩。","explanation":"不 + V1 + 也能 + V2."},{"type":"sort","context":"Sắp xếp: “Chuyện này không hỏi tôi cũng biết.”","words":["这件事","不问","我","也","知道"],"answer":"这件事不问我也知道。","explanation":"Chủ ngữ vế sau (我) đứng trước 也."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你不告诉我，我也知道你在想什么。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 不……也…… (có thể có dấu phẩy khi chủ ngữ hai vế khác nhau)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我不说也你懂。","isCorrect":false,"correctVersion":"我不说你也懂。","explanation":"也 phải đứng sau chủ ngữ 你."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不用地图，但是我也能找到。","isCorrect":false,"correctVersion":"不用地图我也能找到。","explanation":"Câu rút gọn không dùng 但是."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Em không nói anh cũng hiểu em đang nghĩ gì.","answer":"我不说你也懂我在想什么。","answerPy":"Wǒ bù shuō nǐ yě dǒng wǒ zài xiǎng shénme.","explanation":"Sub1 + 不 + V + Sub2 + 也 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bài này dễ quá, không ôn cũng làm được.","answer":"这个题太简单了，不复习也做得了。","answerPy":"Zhège tí tài jiǎndān le, bú fùxí yě zuò de liǎo.","explanation":"不复习也 + V得了 (ôn Bài 4 · điểm 1)."}]},{"point":"转折复句“尽管……，但是/可是……” — mặc dù …, nhưng …","items":[{"context":"“Họ tuy tính cách khác nhau nhưng …”","pre":"他们","blank":"尽管","post":"性格不同，但是有很多共同爱好。","options":["尽管","由于","不管"],"answer":0,"explanation":"尽管……，但是…… (chuyển ngoặt)."},{"context":"“… nhưng họ vẫn hoàn thành nhiệm vụ.”","pre":"尽管时间紧张、压力很大，","blank":"但是","post":"他们还是完成了任务。","options":["但是","所以","而且"],"answer":0,"explanation":"Vế sau của 尽管 dùng 但是 / 可是."},{"context":"“… nhưng vẫn kiên nhẫn đọc truyện cho con.”","pre":"尽管她已经很累了，可是","blank":"还是","post":"很耐心地给女儿读睡前故事。","options":["还是","才","就"],"answer":0,"explanation":"可是 + 还是: nhấn mạnh “vẫn”."},{"context":"“Mặc dù đã sống ở Trung Quốc năm năm, nhưng vẫn chưa quen ăn cay.” (phân biệt 不管 – Bài 8, 既然 – Bài 7)","pre":"","blank":"尽管","post":"他已经在中国住了五年，但是还是不太习惯吃辣的。","options":["尽管","不管","既然"],"answer":0,"explanation":"Sự thật cụ thể + kết quả trái chiều → 尽管."},{"context":"“Mặc dù công việc bận, nhưng anh ấy rất có trách nhiệm với gia đình …”","pre":"尽管工作很忙，但是他对家庭很","blank":"负责","post":"，从来没忘过孩子的生日。","options":["负责","积极","浪漫"],"answer":0,"explanation":"对……负责 = có trách nhiệm với …"},{"type":"sort","context":"Sắp xếp: “Mặc dù lâu lắm không gặp, nhưng mọi người vẫn thấy rất thân quen.”","words":["尽管","很久没见了","，","但是","大家","还是","感觉很熟悉"],"answer":"尽管很久没见了，但是大家还是感觉很熟悉。","explanation":"尽管……，但是 + Sub + 还是……"},{"type":"sort","context":"Sắp xếp: “Anh ấy tuy công việc rất bận nhưng ngày nào cũng gọi cho bạn gái.”","words":["他","尽管","工作很忙","，","可是","每天","都给女朋友打电话"],"answer":"他尽管工作很忙，可是每天都给女朋友打电话。","explanation":"尽管 đứng trước hoặc sau chủ ngữ đều được."},{"type":"sort","context":"Sắp xếp: “Mặc dù tôi rất thích chiếc máy tính đó, nhưng cuối cùng vẫn không mua.”","words":["尽管","我","很喜欢那台电脑","，","但是","最后","还是没有买"],"answer":"尽管我很喜欢那台电脑，但是最后还是没有买。","explanation":"Đáp án tham khảo của sách (bài tập 3)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"尽管雨下得很大，但是比赛还是按时开始了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: mưa to (sự thật) — trận đấu vẫn bắt đầu đúng giờ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"尽管他生病了，所以没来上课。","isCorrect":false,"correctVersion":"由于他生病了，所以没来上课。","explanation":"Quan hệ nhân quả → 由于……，所以…… (Bài 2)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"尽管你说什么，我都不相信。","isCorrect":false,"correctVersion":"不管你说什么，我都不相信。","explanation":"Điều kiện bất kỳ (什么) → 不管……都…… (Bài 8)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Mặc dù tính cách họ khác nhau, nhưng họ có rất nhiều sở thích chung.","answer":"尽管他们性格不同，但是有很多共同爱好。","answerPy":"Jǐnguǎn tāmen xìnggé bùtóng, dànshì yǒu hěn duō gòngtóng àihào.","explanation":"尽管……，但是 / 可是…… + từ mới 性格, 共同."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Mặc dù đã học tiếng Trung hai năm, nhưng tôi vẫn xem không hiểu phim Trung Quốc.","answer":"尽管我已经学了两年中文，但是还是看不懂中国电影。","answerPy":"Jǐnguǎn wǒ yǐjīng xué le liǎng nián Zhōngwén, dànshì háishi kàn bu dǒng Zhōngguó diànyǐng.","explanation":"但是 + 还是 + V不懂."}]},{"point":"指示代词“此” — này, đây (văn viết, trang trọng)","items":[{"context":"“Chuyến công tác lần này khiến hai người thân quen.”","pre":"","blank":"此","post":"次出差，让两人熟悉了起来。","options":["此","那","哪"],"answer":0,"explanation":"此次 = 这次 (văn viết)."},{"context":"“… nhất định hoàn thành tốt nhiệm vụ.”","pre":"此人聪明、有能力，一定能顺利完成","blank":"任务","post":"。","options":["任务","印象","日子"],"answer":0,"explanation":"完成任务 = hoàn thành nhiệm vụ."},{"context":"“Tài liệu này rất quan trọng, phải giao tận tay anh ấy.”","pre":"此材料很重要，必须直接","blank":"交","post":"给他。","options":["交","让","叫"],"answer":0,"explanation":"交给 + người = giao cho ai."},{"context":"“… từ đó thành bạn tốt.”","pre":"他们一起出了次差，","blank":"从此","post":"成了好朋友。","options":["从此","从来","当时"],"answer":0,"explanation":"从此 = từ mốc đó về sau."},{"context":"“… tôi chịu trách nhiệm về việc này.” (ôn 任何 – Bài 1)","pre":"关于此次活动，大家有任何问题都可以问我，我对","blank":"此","post":"负责。","options":["此","这儿","那儿"],"answer":0,"explanation":"对此负责 = chịu trách nhiệm về việc này."},{"type":"sort","context":"Sắp xếp: “Chuyến công tác lần này khiến hai người thân quen.”","words":["此次","出差","让","两人","熟悉了起来"],"answer":"此次出差让两人熟悉了起来。","explanation":"此次 + N làm chủ ngữ."},{"type":"sort","context":"Sắp xếp: “Công việc này do bạn phụ trách.”","words":["此项","工作","由","你","负责"],"answer":"此项工作由你负责。","explanation":"此 + lượng từ 项 + N; 由 + người + 负责."},{"type":"sort","context":"Sắp xếp: “Chúng tôi đều rất hài lòng về việc này.”","words":["我们","对此","都","很满意"],"answer":"我们对此都很满意。","explanation":"对此 = 对这件事."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"此人做事积极，工作负责，大家都很喜欢他。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 此人 = 这个人 (trang trọng)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你看，此是我新买的手机。","isCorrect":false,"correctVersion":"你看，这是我新买的手机。","explanation":"Khẩu ngữ dùng 这 làm chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"从此以前，他再也没迟到过。","isCorrect":false,"correctVersion":"从此以后，他再也没迟到过。","explanation":"从此 đi với 以后."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chuyến công tác lần này khiến hai người trở nên thân quen, từ đó thành bạn tốt.","answer":"此次出差让两人熟悉了起来，从此成了好朋友。","answerPy":"Cǐ cì chūchāi ràng liǎng rén shúxi le qǐlai, cóngcǐ chéng le hǎo péngyou.","explanation":"此次 + 从此 (từ mới)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Người này vừa thông minh vừa có trách nhiệm, việc này giao cho anh ấy là được.","answer":"此人既聪明又负责，这件事交给他就是了。","answerPy":"Cǐ rén jì cōngming yòu fùzé, zhè jiàn shì jiāogěi tā jiùshì le.","explanation":"此人 + 既……又…… (Bài 4) + 就是了 (Bài 2)."}]},{"point":"时间副词“从来” — từ trước đến nay (luôn / chưa từng)","items":[{"context":"“Tình yêu, từ trước đến nay luôn là …”","pre":"爱，","blank":"从来","post":"都是相互尊重、理解与支持，不是吗？","options":["从来","从此","当时"],"answer":0,"explanation":"从来都是 = từ trước đến nay luôn là."},{"context":"“Tôi chưa từng thấy loài hoa màu này.”","pre":"我从来没见","blank":"过","post":"这个颜色的花，它叫什么名字啊？","options":["过","了","着"],"answer":0,"explanation":"从来没 + V + 过."},{"context":"“Tôi trước giờ không thích đi du lịch một mình.”","pre":"我从来","blank":"不","post":"喜欢一个人旅游，每次都要和家人或朋友一起去。","options":["不","没","别"],"answer":0,"explanation":"Sở thích, thói quen → 从来不."},{"context":"“… chưa từng đến muộn.”","pre":"他工作很负责，从来","blank":"没","post":"迟到过。","options":["没","不","别"],"answer":0,"explanation":"Có 过 → 从来没 + V + 过."},{"context":"“Anh ấy là người rất thật thà, trước giờ không nói dối.”","pre":"他这个人很","blank":"实在","post":"，从来不说假话。","options":["实在","浪漫","积极"],"answer":0,"explanation":"实在 = thật thà (từ mới bài khoá 3)."},{"type":"sort","context":"Sắp xếp: “Tôi chưa từng đến Vạn Lý Trường Thành.”","words":["我","从来","没","去过","长城"],"answer":"我从来没去过长城。","explanation":"从来没 + V + 过 + O."},{"type":"sort","context":"Sắp xếp: “Anh ấy trước giờ không uống cà phê.”","words":["他","从来","不","喝","咖啡"],"answer":"他从来不喝咖啡。","explanation":"从来不 + V: thói quen."},{"type":"sort","context":"Sắp xếp: “Tình yêu từ trước đến nay luôn là ủng hộ lẫn nhau.”","words":["爱","从来","都是","相互","支持的"],"answer":"爱从来都是相互支持的。","explanation":"Khẳng định: 从来都是……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我从来没吃过这么好吃的巧克力。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 从来没 + V + 过."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她不从来迟到。","isCorrect":false,"correctVersion":"她从来不迟到。","explanation":"从来 đứng trước 不."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"上个星期六我从来没去公园。","isCorrect":false,"correctVersion":"上个星期六我没去公园。","explanation":"Một thời điểm cụ thể không dùng 从来."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi chưa từng xem bộ phim này, nghe nói rất hay.","answer":"我从来没看过这个电影，听说很精彩。","answerPy":"Wǒ cónglái méi kàn guò zhège diànyǐng, tīngshuō hěn jīngcǎi.","explanation":"从来没 + V + 过 + từ mới 精彩."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Anh ấy trước giờ không nói dối, bạn cứ yên tâm là được.","answer":"他从来不说假话，你放心就是了。","answerPy":"Tā cónglái bù shuō jiǎhuà, nǐ fàngxīn jiùshì le.","explanation":"从来不 + 就是了 (ôn Bài 2 · điểm 1)."}]}]});
